import{a as e}from"./jsx-runtime-Bzw2jH9X.js";var t=e({default:()=>n}),n=JSON.parse(`[{"id":"qx-a1-001","clusterId":"A","werkstueckRef":"A.1.1","stufe":1,"question":"Bei einem Streit um die Ursache eines Phänomens sagt jemand: „Nach Ockhams Rasiermesser ist die einfachste Erklärung die wahre, also ist jede Erklärung mit mehr Annahmen damit widerlegt.“ Was ist an dieser Schlussfolgerung falsch?","options":["Das Sparsamkeitsprinzip gilt als Priorisierungswerkzeug und legt nur fest, welche Erklärung man zuerst prüft, ohne deren Wahrheit zu beweisen.","Das Sparsamkeitsprinzip gilt als Naturgesetz und bestätigt deshalb stets die Erklärung mit den wenigsten Annahmen als die tatsächlich zutreffende.","Das Sparsamkeitsprinzip gilt als Beweisverfahren und widerlegt deshalb jede Erklärung, die mehr Annahmen benötigt als eine konkurrierende.","Das Sparsamkeitsprinzip gilt als Verständlichkeitstest und verwirft deshalb jede Erklärung, die ein Laie nicht auf Anhieb nachvollziehen kann."],"correctIndex":0,"explanation":"Die Schlussfolgerung verwechselt ein Priorisierungswerkzeug mit einem Beweis. Das Sparsamkeitsprinzip sagt nur, welche Erklärung man zuerst prüfen sollte: die mit den wenigsten unbewiesenen Annahmen. Dass sie zutrifft, folgt daraus nicht. Eine Erklärung mit mehr Annahmen ist damit nicht widerlegt, sondern nur die schlechtere Ausgangsbasis.","coreRule":"⚡ Sparsamkeit sortiert Hypothesen nach ihren unbewiesenen Annahmen: Sie ist ein Priorisierungswerkzeug, kein Wahrheitsbeweis.","quote":"Man sollte nicht mehr Ursachen zur Erklärung heranziehen, als unbedingt notwendig sind.","quoteLabel":"Merksatz:","beleg":"Werkstück A.1.1 (Kontext & Tiefe; Der Kipppunkt)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"08db8313e037585c","vermerk":"Prüfpult"},"scenario":"","kurz":"Das Sparsamkeitsprinzip sagt nur, welche Erklärung man zuerst prüfen sollte, nämlich die mit den wenigsten unbewiesenen Annahmen. Der Fehler liegt darin, aus „zuerst prüfen“ ein „wahr“ zu machen: Eine Erklärung mit mehr Annahmen ist so nicht widerlegt.","prueffrage":"Was müsste man beobachten, um eine Erklärung wirklich zu widerlegen, und kommt so etwas in dem Satz überhaupt vor?","rueckmeldung":[{"option":1,"text":"Dass sparsame Erklärungen oft ein guter Anfang sind, macht das Prinzip noch nicht zum Naturgesetz. Es ist eine methodische Faustregel, und dass die Erklärung mit den wenigsten Annahmen tatsächlich zutrifft, folgt daraus keineswegs."},{"option":2,"text":"Wer das Prinzip für ein Beweisverfahren hält, wiederholt den Fehler des Satzes, statt ihn zu finden. Es ordnet Erklärungen nur: Wer mehr Annahmen braucht, startet schlechter, ist deshalb aber nicht widerlegt."},{"option":3,"text":"Beim Sparsamkeitsprinzip zählen unbewiesene Annahmen, nicht die Verständlichkeit für Laien. Eine einfache Erklärung muss nicht leicht zu verstehen sein, und verworfen wird durch das Prinzip ohnehin nichts: Es legt nur die Prüfreihenfolge nahe."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Baker, A.: Simplicity. Stanford Encyclopedia of Philosophy (überarb. 16.05.2022), Abschn. 1–2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/simplicity/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Thorburn, W. M. (1918): The Myth of Occam's Razor. Mind 27(3), 345–353","oeffentlich":false,"doi":"10.1093/mind/XXVII.3.345"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"08db8313e037585c"}},{"id":"qx-a1-002","clusterId":"A","werkstueckRef":"A.1.1","stufe":2,"question":"Welche Ursache solltest du zuerst prüfen, und warum?","scenario":"Abends fällt dein WLAN aus, alle Geräte sind betroffen. Gestern lief noch alles. Du willst nicht wahllos suchen.","options":["Einen gezielten Angriff auf dein Heimnetz, weil diese Erklärung auch spätere Ausfälle mit abdecken würde.","Einen gezielten Angriff auf dein Heimnetz, weil erst sein Ausschluss die Suche nach harmloseren Gründen lohnt.","Einen hängenden Router oder eine Störung beim Anbieter, weil dafür keine neuen Annahmen nötig sind.","Einen gleichzeitigen Defekt aller Endgeräte, weil der Ausfall wirklich jedes Gerät im Haushalt betrifft."],"correctIndex":2,"explanation":"Ein hängender Router oder eine Anbieterstörung braucht nichts Neues: Geräte fallen aus, das weiß jeder. Ein Cyberangriff dagegen setzt einen Angreifer, ein Motiv und eine Möglichkeit voraus, die du erst belegen müsstest, und ein gleichzeitiger Defekt aller Geräte verlangt viele voneinander unabhängige Zufälle. Dass eine Erklärung mehr abdecken oder schwerer wiegen würde, macht sie nicht sparsamer: Sparsam heißt, mit den wenigsten unbewiesenen Annahmen auszukommen. Das ist eine Reihenfolge der Prüfung, kein Beweis: Hilft ein Neustart des Routers nicht und meldet der Anbieter keine Störung, rücken die nächstsparsamen Erklärungen nach, die exotischen erst am Ende.","coreRule":"⚡ Starte bei der Ursache, die nur Bekanntes voraussetzt, und erst danach bei den exotischen.","beleg":"Werkstück A.1.1 (Anwendung & Relevanz: Im Alltag, Fehlerdiagnose)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"7974a39809e8d782","vermerk":"Prüfpult"},"kurz":"Zuerst prüfst du, was keine neuen Annahmen braucht: Dass ein Router hängt oder der Anbieter eine Störung hat, kennt jeder. Ein Angriff wäre erst zu belegen und rückt ans Ende. Das ist eine Reihenfolge der Prüfung, kein Beweis.","prueffrage":"Was weißt du sicher über den Ausfall: Welche Geräte sind betroffen, und was hat sich seit gestern geändert?","rueckmeldung":[{"option":0,"text":"Dass eine Erklärung auch spätere Ausfälle abdecken würde, macht sie nicht sparsamer. Sparsam ist die Erklärung mit den wenigsten unbewiesenen Annahmen, und ein Angriff verlangt Angreifer, Motiv und Möglichkeit, die erst zu belegen wären."},{"option":1,"text":"Das Schlimmste zuerst auszuschließen wirkt vorsichtig. Doch ein Angriff braucht viele unbelegte Annahmen, und wie schwer eine Ursache wöge, sagt nichts darüber, wie wahrscheinlich sie ist; harmlose Gründe lohnen die Suche sofort."},{"option":3,"text":"Dass alle Geräte betroffen sind, ist ein wichtiger Hinweis, spricht aber gegen viele Einzeldefekte: Sie müssten unabhängig voneinander zur selben Zeit auftreten. Ein hängender Router erklärt dasselbe mit einer einzigen Annahme."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Baker, A.: Simplicity. Stanford Encyclopedia of Philosophy (überarb. 16.05.2022), Abschn. 2","oeffentlich":true,"url":"https://plato.stanford.edu/entries/simplicity/","abruf":"2026-10-12"}],"thema":"Technik und KI","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7974a39809e8d782"}},{"id":"qx-a1-003","clusterId":"A","werkstueckRef":"A.1.1","stufe":3,"question":"Was ist an dieser Berufung auf das Prinzip der Sparsamkeit falsch?","scenario":"In einer Diskussion sagt jemand: „Nach dem Prinzip der Sparsamkeit ist die einfachere Erklärung besser. Newtons Physik versteht jeder, die Relativitätstheorie fast niemand – also gilt Newton.“","options":["Das Prinzip betrifft nur Alltagsfragen, nicht physikalische Theorien mit Messdaten, daher ist der Vergleich der beiden Theorien unzulässig.","Das Prinzip bemisst Sparsamkeit an der Zahl der Annahmen, nicht an der Verständlichkeit, und Newton erklärt manche Messungen nur mit Zusatzannahmen.","Das Prinzip verlangt immer die kompliziertere Theorie, weil sie mehr Daten abdeckt und jede zusätzliche Regel einen weiteren Datenpunkt erklärt.","Das Prinzip greift erst, wenn eine der beiden Theorien durch Experimente widerlegt ist, weil es vorher keinen Maßstab für den Vergleich gibt."],"correctIndex":1,"explanation":"„Einfach“ bedeutet beim Prinzip der Sparsamkeit „wenige Annahmen“, nicht „leicht zu verstehen“. Die Relativitätstheorie ist konzeptionell anspruchsvoll, doch Newtons Physik erklärt manche Messungen nur mit eigens angefügten Zusatzannahmen oder gar nicht genau, etwa die Periheldrehung des Merkur. Wer „einfach“ mit „leicht verständlich“ verwechselt, wählt am Ende die Erklärung, die wichtige Daten ignoriert, und macht aus dem Werkzeug zur Priorisierung von Hypothesen ein Scheinargument.","coreRule":"⚡ Eine einfache Erklärung, die der Hälfte der Beweise widerspricht, ist nicht besser als eine komplexere Erklärung, die alle Beweise integriert.","quote":"„Einfach“ bedeutet „wenige Annahmen“, nicht „leicht zu verstehen“.","quoteLabel":"Typische Aussage:","beleg":"Werkstück A.1.1 (Der Kipppunkt)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"b588d2eae4167bc5","vermerk":"Prüfpult"},"kurz":"„Einfach“ heißt beim Prinzip der Sparsamkeit „wenige Annahmen“, nicht „leicht zu verstehen“. Die Relativitätstheorie ist schwer zu begreifen, doch Newtons Physik erklärt manche Messungen, etwa am Merkur, nur mit eigens angefügten Zusatzannahmen oder gar nicht genau.","prueffrage":"Gibt es Messungen, bei denen Newtons Physik und die Relativitätstheorie Verschiedenes vorhersagen, und welche liegt dort richtig?","rueckmeldung":[{"option":0,"text":"Messdaten spielen bei physikalischen Theorien eine große Rolle, doch das Prinzip lässt sich auch hier anwenden und auf beide Theorien beziehen. Der Fehler liegt im Verständnis von „einfach“, nicht im Anwendungsbereich."},{"option":2,"text":"Mehr abgedeckte Daten zählen tatsächlich für eine Theorie. Das Prinzip bevorzugt aber die mit weniger Annahmen, und eine Sonderregel, die eigens für einen Datenpunkt eingeführt wird, flickt nur eine Lücke, statt etwas vorherzusagen."},{"option":3,"text":"Dass Experimente am Ende entscheiden, stimmt. Ist eine Theorie aber widerlegt, braucht es kein Sparsamkeitsprinzip mehr; es hilft gerade vorher, Hypothesen zu ordnen. Der Fehler liegt darin, was hier als „einfach“ gilt."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Will, C. M. (2014): The Confrontation between General Relativity and Experiment. Living Reviews in Relativity 17, 4 (Abschn. „The perihelion shift of Mercury“)","oeffentlich":true,"doi":"10.12942/lrr-2014-4","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC5255900/","abruf":"2026-10-12"},{"typ":"url","kurz":"Baker, A.: Simplicity. Stanford Encyclopedia of Philosophy (überarb. 16.05.2022)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/simplicity/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"b588d2eae4167bc5"}},{"id":"qx-a1-004","clusterId":"A","werkstueckRef":"A.1.1","stufe":4,"question":"Was ist an diesem Argument der Ärztin fehlerhaft?","scenario":"Zwei Patienten kommen mit Fieber und Husten. Patientin 1 war seit Monaten nicht verreist. Patient 2 kam, wie belegt ist, vor zwei Wochen aus den Tropen zurück. Eine Ärztin sagt: „Erkältung ist bei beiden die sparsamste Erklärung, denn sie ist die häufigste.“","options":["Sie setzt „sparsam“ mit „häufig“ gleich, obwohl sich die Sparsamkeit nach den unbelegten Annahmen im Einzelfall richtet.","Sie vergisst, dass eine belegte Reise die Tropenkrankheit zur sicheren Diagnose macht und die Erkältung ausschließt.","Sie übersieht, dass das Sparsamkeitsprinzip nur in der Naturwissenschaft gilt und auf Diagnosen nicht übertragbar ist.","Sie wählt für beide Fälle dieselbe Erklärung, obwohl nach dem Sparsamkeitsprinzip eine Erklärung immer die andere ausschließt."],"correctIndex":0,"explanation":"Sparsam heißt „wenige neue, unbelegte Annahmen“. Bei Patientin 1 braucht eine Tropenkrankheit eine zusätzliche, unbelegte Annahme (eine unbemerkte Reise), deshalb liegt die Erkältung vorn. Bei Patient 2 ist die Reise belegt, diese Annahme entfällt, und die Tropenkrankheit rückt in die engere Wahl. Die Ärztin beachtet das nicht und wendet für beide dieselbe Erklärung an. Das Sparsamkeitsprinzip ist ein Werkzeug zur Priorisierung, kein Beweis: Die Tropenkrankheit gilt damit nicht als bewiesen, die Erkältung nicht als ausgeschlossen.","coreRule":"⚡ Sparsam heißt „wenige unbelegte Annahmen“, nicht „häufig“: Wird eine Zusatzannahme belegt, verschiebt sich die Rangfolge.","beleg":"Werkstück A.1.1 (Anwendung & Relevanz: In der Medizin; Der Kipppunkt)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"922a9b914d52bb3c","vermerk":"Prüfpult"},"kurz":"Sparsam heißt „wenige unbelegte Annahmen“, nicht „häufig“. Bei Patient 2 ist die Reise belegt, diese Annahme entfällt, und eine Tropenkrankheit rückt in die engere Wahl, ohne damit schon bewiesen zu sein.","prueffrage":"Worin unterscheiden sich die Vorgeschichten der beiden, und welcher Unterschied ist belegt?","rueckmeldung":[{"option":1,"text":"Die belegte Reise stärkt den Verdacht auf eine Tropenkrankheit tatsächlich. Sie macht ihn aber nicht zur sicheren Diagnose: Das Prinzip ordnet nur die Reihenfolge der Verdachtsdiagnosen, und eine Erkältung bleibt weiterhin möglich."},{"option":2,"text":"Eine klare Grenze zwischen Naturwissenschaft und Medizin wirkt ordentlich, trägt hier aber nicht: Auch in der Medizin dient Sparsamkeit als Faustregel, um Verdachtsdiagnosen zu ordnen. Der Fehler liegt in der Anwendung, nicht im Gebiet."},{"option":3,"text":"Dieselbe Erklärung für zwei Fälle zu wählen ist an sich nicht verboten, und Sparsamkeit schließt auch keine andere Erklärung aus. Entscheidend ist, dass sich die Annahmenlage der beiden Fälle unterscheidet und die Ärztin das nicht berücksichtigt."}],"familie":"sparsamste-erklaerung","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Baker, A.: Simplicity. Stanford Encyclopedia of Philosophy (überarb. 16.05.2022), Abschn. 4 (Sober)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/simplicity/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"922a9b914d52bb3c"}},{"id":"qx-a1-005","clusterId":"A","werkstueckRef":"A.1.2","stufe":1,"question":"Du schreibst einer Kollegin eine dringende Nachricht. Sie antwortet den ganzen Tag nicht. Eine andere Kollegin sagt: „Die ignoriert dich absichtlich, die kann dich eben nicht leiden.“ Du weißt: Die Kollegin war schon immer freundlich zu dir, und heute sind im Haus mehrere Systeme ausgefallen. Welche Reaktion ist am vernünftigsten?","options":["Die ausbleibende Antwort als Hinweis auf eine schlechte Beziehung werten und ab sofort nur noch das Nötigste mit ihr besprechen.","Die Erklärung der anderen Kollegin zunächst ernst nehmen, weil sie die Schweigende vielleicht besser kennt als du.","Freundlich nachfragen, ob die Nachricht angekommen ist, bevor du ihr eine Absicht unterstellst.","Warten, bis die Kollegin sich von selbst meldet, und ihr Schweigen bis dahin als Beleg gegen sie sammeln."],"correctIndex":2,"explanation":"Ein einzelnes Schweigen sagt wenig über die Absicht dahinter. Eine böse Absicht erfordert mehrere Annahmen (etwa: Die Kollegin ist böswillig, verstellt sich und plant aktiv gegen dich). Gegen eine solche Absicht spricht ihr bisheriges Verhalten. Für Panne, Überlastung oder Zufall genügt eine einzige Annahme: Technische Systeme fallen aus. Die Systemausfälle im Haus machen diese Erklärung sogar wahrscheinlich. Wer Charakter und Motive unterstellt, übersieht leicht die Umstände, die er bei sich selbst sofort anführen würde. Die sparsamste Erklärung zuerst zu prüfen heißt nicht, Absicht für unmöglich zu halten. Wiederholt sich das Muster, ändert sich die Lage. Hier ist die Nachfrage der erste Schritt.","coreRule":"⚡ Bevor du eine Absicht unterstellst, frag nach den Umständen – so wie du es bei dir selbst tust.","beleg":"Werkstück A.1.2 (Kontext & Tiefe; Verbindungen: Verwandter Bug)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"493203f53ea9a86e","vermerk":"Prüfpult"},"scenario":"","kurz":"Ein einzelnes Schweigen sagt wenig über die Absicht dahinter. Für Pech oder Überlastung genügt eine Annahme, für Böswilligkeit braucht es mehrere, und ihr bisheriges Verhalten spricht dagegen. Also zuerst die einfache Erklärung prüfen: nachfragen.","prueffrage":"Worauf stützt die andere Kollegin ihr Urteil, und was weißt du selbst über das bisherige Verhalten der Kollegin?","rueckmeldung":[{"option":0,"text":"Ein einzelner Tag ohne Antwort ist ein dünner Anlass für eine dauerhafte Distanz. Dagegen sprechen ihr bisher freundliches Verhalten und die Ausfälle im Haus. Anders sähe es aus, wenn sich das Schweigen wiederholte."},{"option":1,"text":"Vielleicht kennt sie die Kollegin tatsächlich besser, doch sie nennt nur eine Absicht, ohne etwas dafür anzuführen. Was du selbst weißt, spricht dagegen: ihre Freundlichkeit bisher und der Ausfall der Systeme."},{"option":3,"text":"Abwarten wirkt fair, doch wer ihr Schweigen als Beleg sammelt, sucht schon nach Bestätigung für die Unterstellung. Ein Einzelfall wird nicht zum Muster, nur weil man ihn aufhebt; eine kurze Nachfrage klärt mehr."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1), 21–38 (Autorenkopie, Harvard)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"},{"typ":"url","kurz":"Quote Investigator: Never Attribute to Malice That Which Is Adequately Explained by Stupidity (30.12.2016, aktual. 18.04.2025)","oeffentlich":true,"url":"https://quoteinvestigator.com/2016/12/30/not-malice/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Malle, B. F. (2006): The Actor–Observer Asymmetry in Attribution: A (Surprising) Meta-Analysis. Psychological Bulletin 132(6), 895–919","oeffentlich":false,"doi":"10.1037/0033-2909.132.6.895"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"493203f53ea9a86e"}},{"id":"qx-a1-006","clusterId":"A","werkstueckRef":"A.1.2","stufe":2,"question":"Welcher nächste Schritt ist hier am vernünftigsten?","scenario":"Dein Partner hat vergessen, die Milch mitzubringen. Dein erster Gedanke: „Meine Bedürfnisse sind ihm egal.“ Es ist das erste Mal, dass so etwas passiert, und er kam heute spät und erschöpft von der Arbeit.","options":["Zuerst harmlose Erklärungen durchgehen – müde, abgelenkt, den Einkauf vergessen –, bevor du aus einem einzelnen Vorfall auf Gleichgültigkeit schließt.","Deinem ersten Gefühl vertrauen, denn wenn sich etwas nach Gleichgültigkeit anfühlt, ist es das meistens auch, und entsprechend reagieren.","Den Vorfall als Absicht deuten und beim nächsten Mal Gleiches mit Gleichem vergelten, damit die Botschaft auch ankommt.","Gar nichts schlussfolgern und den Vorfall aus jeder Bewertung streichen, solange sich seine Ursache nicht lückenlos beweisen lässt."],"correctIndex":0,"explanation":"Ein einzelnes vergessenes Mitbringsel lässt viele Ursachen zu: Müdigkeit, Ablenkung, Stress, ein übersehener Zettel. Dass ihm deine Bedürfnisse egal sind, wäre dagegen eine Annahme über Absicht und Charakter, für die ein einziger Vorfall kaum etwas belegt. Wer daraus sofort auf Gleichgültigkeit schließt, überschätzt leicht den Charakter und unterschätzt die Umstände, zumal nach einem erschöpfenden Arbeitstag. Das ist keine Naivität: Häufen sich solche „Fehler“ und treffen immer nur dich, wird Absicht plausibler. Einen lückenlosen Beweis braucht es dafür nicht, den gibt es im Alltag fast nie; Gefühl und Vergeltung dagegen ersetzen die Prüfung durch Stimmung und eine unbelegte Annahme.","coreRule":"⚡ Aus einem einzelnen Ereignis folgt keine Absicht – prüfe zuerst die harmlose Erklärung.","beleg":"Werkstück A.1.2 (Anwendung & Relevanz: In persönlichen Beziehungen)","status":"freigegeben","freigabe":{"datum":"2026-10-13","pruefsumme":"4ad1092e4ba0659d","vermerk":"Prüfpult"},"kurz":"Ein einzelnes Vergessen lässt viele Ursachen zu, besonders nach einem erschöpfenden Tag. Wer sofort auf Gleichgültigkeit schließt, überschätzt leicht den Charakter und unterschätzt die Umstände; erst die harmlosen Erklärungen zu prüfen ist vernünftiger.","prueffrage":"Was müsste über längere Zeit geschehen, damit „Meine Bedürfnisse sind ihm egal“ eine gut gestützte Deutung wäre?","rueckmeldung":[{"option":1,"text":"Das Gefühl zeigt, dass dich etwas getroffen hat, und das darf man ernst nehmen. Als Beleg für Gleichgültigkeit reicht es aber nicht: Es ersetzt die Prüfung durch Stimmung und sagt nichts darüber, was bei ihm tatsächlich los war."},{"option":2,"text":"Vergeltung wirkt wie eine klare Grenze, baut aber auf einer unbelegten Annahme über seine Absicht auf. Beim ersten Vorfall nach einem erschöpfenden Tag würde sie einen Streit auslösen, für den es noch keinen Grund gibt."},{"option":3,"text":"Mit dem Urteil zurückhaltend zu sein, ist richtig. Einen lückenlosen Beweis zu verlangen, geht aber zu weit, denn den gibt es im Alltag fast nie. Besser: die harmloseste Erklärung zuerst prüfen und auf eine Häufung achten."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Gilbert, D. T.; Malone, P. S. (1995): The Correspondence Bias. Psychological Bulletin 117(1), 21–38 (Autorenkopie, Harvard)","oeffentlich":true,"url":"https://dtg.sites.fas.harvard.edu/Gilbert%20%26%20Malone%20%28CORRESPONDENCE%20BIAS%29.pdf","seite":"21","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"4ad1092e4ba0659d"}},{"id":"qx-a1-007","clusterId":"A","werkstueckRef":"A.1.2","stufe":3,"question":"Wie solltest du das Muster einschätzen und was ist deine beste nächste Reaktion?","scenario":"Ein Kollege hat in den letzten drei Monaten dreimal vergessen, dir einen Termin weiterzuleiten, bei etwa 30 Terminen insgesamt. Jedes Mal ging die Panne zu deinem Nachteil und zu seinem Vorteil aus.","options":["Du bleibst bei Nachlässigkeit als Erklärung, denn nach Hanlons Rasiermesser unterstellt man keine Bosheit, wo Dummheit genügt.","Du nimmst den Verdacht auf Absicht ernst und prüfst ihn, denn ein Muster zugunsten nur einer Seite ist mit Zufall kaum erklärbar.","Du führst die Pannen auf Stress und Überlastung zurück, denn Umstände erklären Verhalten oft besser als verborgene Absichten.","Du wartest, bis sich die Häufung von selbst legt, denn auffällige Serien kehren erfahrungsgemäß zum Durchschnitt zurück."],"correctIndex":1,"explanation":"Die Faustregel, Böswilligkeit nicht zu unterstellen, wo Dummheit oder Zufall genügen, ist ein sinnvoller Startpunkt, aber keine Denkverbotszone. Der Kipppunkt ist erreicht, wenn ein wiederholtes Muster von „Fehlern“ immer nur einer Partei zugutekommt und der anderen schadet: Einmal ist ein Fehler, zweimal ein Zufall, dreimal feindliche Handlung (oder zumindest grobe Fahrlässigkeit, die an Vorsatz grenzt). Genau das trifft hier zu, denn die Panne geht jedes Mal zu deinem Nachteil und zu seinem Vorteil aus. Das beweist noch keine Absicht, macht sie aber zu einer ernsthaften Möglichkeit, die du nicht einfach als Zufall abtun solltest. Sinnvoll wäre es zum Beispiel, das Muster genauer zu prüfen, etwa durch Nachfragen oder schriftliche Bestätigungen. Die anderen Antworten nennen für sich genommen vernünftige Gedanken, treffen aber den Kern nicht: Hanlons Rasiermesser ist ein Werkzeug für die erste Analyse, nicht für die abschließende Beurteilung. Stress und Überlastung würden zufällige Pannen in beide Richtungen erzeugen, nicht immer zu deinem Nachteil. Und die Rückkehr zum Durchschnitt erklärt keine Serie, die jedes Mal nur einer Seite nützt.","coreRule":"⚡ Die Faustregel „Zufall vor Absicht“ ist ein Startpunkt, kein Schutzschild: Ein Muster, das stets derselben Seite nützt, verdient eine ernste Prüfung auf Absicht.","quote":"","quoteLabel":"","beleg":"Werkstück A.1.2 (Der Kipppunkt) Szenario am 14.10.2026 nach Sturms Urteil um die Bezugsgröße ergänzt (3 von etwa 30 Terminen), Prüffrage angepasst.","status":"entwurf","kurz":"Eine Serie von Pannen, die jedes Mal nur dir schadet und ihm nützt, ist mit bloßem Zufall schlecht erklärbar. Das beweist keine Absicht, macht sie aber zu einer ernsthaften Möglichkeit, die du durch Nachfragen und schriftliche Bestätigungen prüfen solltest.","prueffrage":"Wie oft passieren ihm solche Fehler bei anderen, und wem nützen sie dann?","rueckmeldung":[{"option":0,"text":"Als erster Gedanke ist das vernünftig, denn nicht jede Panne verlangt eine Absicht als Erklärung. Als Schlusspunkt trägt es nicht: Es verbietet das Weiterdenken, auch wenn die Pannen immer nur einer Seite nützen."},{"option":2,"text":"Stress und Überlastung erklären Fehler oft gut. Sie würden aber ungefähr gleich oft zu deinem wie zu seinem Nachteil führen, und genau diese Gleichverteilung fehlt hier."},{"option":3,"text":"Das Zurückkehren zum Durchschnitt erklärt, warum zufällige Ausreißer oft von selbst verschwinden. Eine Serie, die jedes Mal dieselbe Seite begünstigt, ist aber kein zufälliger Ausreißer, und Abwarten prüft nichts."}],"familie":"umstaende-vor-absicht","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Quote Investigator: Never Attribute to Malice That Which Is Adequately Explained by Stupidity (30.12.2016, aktual. 18.04.2025)","oeffentlich":true,"url":"https://quoteinvestigator.com/2016/12/30/not-malice/","abruf":"2026-10-12"}],"thema":"Zusammenleben"},{"id":"qx-a1-008","clusterId":"A","werkstueckRef":"A.1.2","stufe":4,"question":"Auf einer Zitatseite steht: „Hanlons Rasiermesser stammt von Robert J. Hanlon, 1980.“ Du willst wissen, wie belastbar diese Zuschreibung ist. Welche Schlussfolgerung ist angemessen?","options":["Die Urheberschaft ist ungeklärt: Der Name ist eine eingeführte Bezeichnung, aber kein Beleg dafür, wer den Gedanken zuerst formuliert hat.","Hanlon ist der Urheber: Dass der Name seit 1980 unter dem Satz steht und eine spätere Quelle ihn nennt, belegt seine Autorschaft eindeutig.","Heinlein ist der Urheber: Dass sein Satz von 1941 älter ist als der Abdruck von 1980, macht den Namen Hanlon zu einer grundlosen Erfindung.","Die Zuschreibung ist unerheblich: Ein bekannter Name zeigt, dass der Satz stimmt, und die Frage nach dem Urheber ändert daran nichts."],"correctIndex":0,"explanation":"Ein Name an einem Satz ist noch kein Beleg für seinen Urheber. Der Abdruck von 1980 nennt keinen Einsender; die Behauptung, ein Robert J. Hanlon habe ihn geschickt, stammt erst von 2001 (eine im Blog weitergegebene E-Mail, die sich auf Credits der Sammlung beruft, die sich nicht finden lassen) und kann den fehlenden Beleg nicht ersetzen. Gleichzeitig ist es voreilig, nun Heinlein als gesicherten Urheber auszurufen: Die sinngleichen Formulierungen bei Heinlein (1941) und Wells (1896) zeigen nur, dass es ältere Formulierungen gibt, nicht, wer den Gedanken zuerst gesagt hat. Der Name kann als eingeführte Bezeichnung bleiben; ob er auch den Urheber bezeichnet, ist offen. Und ob der Gedanke taugt, hängt nicht davon ab, wer ihn zuerst gesagt hat, sondern davon, ob er einer Prüfung standhält.","coreRule":"⚡ Ein eingeführter Name ist kein Urheberbeleg – prüfe, wer etwas wann zuerst gesagt hat, und halte offen, was sich nicht belegen lässt.","beleg":"Werkstück A.1.2; Fn. ga-hanlon (Bloch 1980, S. 52; O’Toole 2016; Jargon File 1990; Heinlein 1941; Wells 1896). Von Sturm am 12.10.2026 im Buch geprüft (Preface, Acknowledgements and Permissions, S. 52): Weder beim Spruch noch an anderer Stelle wird ein Einsender genannt.. Früheste Nennung Hanlons: Stafford-Fraser, Q. (26.11.2001): Hanlon’s Razor, Status-Q, https://statusq.org/archives/2001/11/26/75/ (E-Mail von Joe Biglen, nicht nachprüfbar; abgerufen 12.10.2026).","status":"zurueckgezogen","scenario":"Der Satz „Schreibe nie der Böswilligkeit zu, was durch Dummheit hinreichend erklärt werden kann“ trägt im Netz meist den Namen „Hanlons Rasiermesser“. Du findest heraus: Er wurde 1980 in einer Sammlung zu Murphys Gesetz unter der Überschrift „Hanlon’s Razor“ abgedruckt, ohne dass die Sammlung einen Einsender nennt. Dass ein Robert J. Hanlon ihn eingesandt habe, steht erst 2001 in einem Blogeintrag, der die E-Mail eines Bekannten wiedergibt; die dort genannten „Credits“ der Sammlung lassen sich nicht finden. Ähnlich lautende Sätze gab es schon 1941 bei Robert A. Heinlein und 1896 bei H. G. Wells.","kurz":"Der Name steht seit 1980 über dem Satz, doch der Abdruck nennt keinen Einsender; Hanlon als Einsender steht erst 2001 in einer weitergereichten E-Mail und ist nicht nachprüfbar. Ein Name an einem Satz belegt keinen Urheber, also bleibt die Urheberschaft offen.","prueffrage":"Wer wird im Abdruck von 1980 als Einsender des Satzes genannt, und wann taucht ein Name dafür erstmals auf?","rueckmeldung":[{"option":1,"text":"Dass der Name seit 1980 unter dem Satz steht und später eine Quelle Hanlon nennt, wirkt wie eine Spur. Der Abdruck von 1980 nennt aber keinen Einsender, und eine spätere Nennung ersetzt diesen Beleg nicht. „Eindeutig“ ist zu viel."},{"option":2,"text":"Heinleins Satz von 1941 ist tatsächlich älter als der Abdruck von 1980, und bei Wells steht 1896 Ähnliches. Das zeigt aber nur, dass es ältere Formulierungen gibt, nicht, wer den Gedanken zuerst hatte, und auch nicht, dass der Name erfunden ist."},{"option":3,"text":"Daran stimmt: Ob der Gedanke taugt, hängt nicht davon ab, wer ihn zuerst sagte. Ein bekannter Name zeigt aber nicht, dass der Satz stimmt, und wer wissen will, wie belastbar die Zuschreibung ist, kann die Urheberfrage nicht für unerheblich erklären."}],"familie":"zitat-am-original-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Quote Investigator: Never Attribute to Malice That Which Is Adequately Explained by Stupidity (30.12.2016, aktual. 18.04.2025)","oeffentlich":true,"url":"https://quoteinvestigator.com/2016/12/30/not-malice/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bloch, A. (1980): Murphy's Law, Book Two: More Reasons Why Things Go Wrong!","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"4caa25546aebcd61"}},{"id":"qx-a1-009","clusterId":"A","werkstueckRef":"A.2","stufe":1,"question":"Was ist der entscheidende Grund, warum diese Geschichte allein die Wirkung der Sitzungen nicht belegt?","scenario":"Eine Bekannte erzählt dir bewegt, ihr Onkel sei nach drei Sitzungen bei einem Energieheiler wie durch ein Wunder von seiner schweren Krankheit geheilt worden. Sie meint es ehrlich und ist von der Wirkung fest überzeugt. Du möchtest wissen, wie viel diese Geschichte als Beleg für die Wirkung der Sitzungen taugt.","options":["Die Bekannte ist ehrlich und meint es aufrichtig. Der Bericht taugt deshalb als Beleg, solange niemand einen Gegenbeleg vorlegt.","Der Onkel ist ein einzelner Fall. Erst wenn mehr als zehn ähnliche Berichte vorliegen, ist die Wirkung der Sitzungen belegt.","Die Geschichte ist sehr emotional erzählt. Gefühle machen einen Bericht weniger glaubwürdig, deshalb zählt er als Beleg nicht.","Ehrlichkeit schützt nicht vor Verzerrung. Spontanbesserung, Erwartung und unerzählte Misserfolge bleiben unsichtbar."],"correctIndex":3,"explanation":"Stell dir 100 Menschen vor, die ein völlig wirkungsloses Zuckerkügelchen gegen Kopfschmerzen nehmen: Einige wären ohnehin nach kurzer Zeit besser geworden (natürlicher Krankheitsverlauf), andere fühlen sich allein durch den Glauben an die Wirkung besser (Placebo-Effekt), und nur einer der Zufriedenen schreibt eine glühende Rezension. Von den übrigen hört man nie etwas, denn es melden sich nur die, bei denen es zu klappen schien (Überlebensirrtum). Ob der Erzähler ehrlich ist, ändert daran nichts, denn die Verzerrung steckt nicht in der Absicht, sondern darin, welche Fälle erzählt werden und was sonst noch zur Besserung beigetragen haben könnte. Eine einzelne Geschichte kann deshalb nicht zeigen, ob die Behandlung gewirkt hat. Sie kann aber ein guter Anlass sein, die Frage in einer kontrollierten Untersuchung zu prüfen. Wertlos ist sie also nicht, nur als Beweis reicht sie nicht.","coreRule":"⚡ Eine Anekdote ist ein Startpunkt für eine Hypothese, kein Beweis für eine Wirkung.","quote":"Wo auf der Pyramide der Evidenz befindet sich dieser Beweis, und warum ist er nicht weiter oben?","quoteLabel":"Prüffrage","beleg":"Werkstück A.2 (Ebene 1: Anekdoten, Testimonials & persönliche Erfahrungen; Der Kipppunkt; Das Anti-Denkmuster, Aktivierungs-Frage)","status":"freigegeben","freigabe":{"datum":"2026-10-14","pruefsumme":"99afa291fb280689","vermerk":"Prüfpult"},"kurz":"Eine einzelne Heilungsgeschichte zeigt nicht, was die Besserung bewirkt hat: Sie kann auch vom natürlichen Verlauf oder von der Erwartung kommen, und von Misserfolgen hört man selten. Ehrlichkeit ändert daran nichts; als Anlass zum Prüfen taugt die Geschichte trotzdem.","prueffrage":"Wer hat die Krankheit des Onkels festgestellt, wer seine Heilung, und wann genau geschah beides?","rueckmeldung":[{"option":0,"text":"Dass die Bekannte aufrichtig erzählt, stimmt. Die Verzerrung liegt aber nicht in ihrer Absicht, sondern darin, welche Fälle erzählt werden und was sonst geholfen haben könnte; ein fehlender Gegenbeleg macht den Bericht nicht zum Beleg."},{"option":1,"text":"Ein Einzelfall zeigt tatsächlich wenig. Die Grenze von zehn Berichten ist aber willkürlich: Auch viele Geschichten stammen oft nur von denen, bei denen es zu klappen schien. Wirkung von Spontanbesserung trennt erst ein Vergleich."},{"option":2,"text":"Dass eine bewegende Erzählung mitreißt, ist richtig, doch Gefühle machen einen Bericht weder wahr noch unglaubwürdig. Das Problem liegt in der Auswahl der erzählten Fälle und in anderen möglichen Ursachen der Besserung."}],"familie":"evidenz-gewichten","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Evans, I.; Thornton, H.; Chalmers, I.; Glasziou, P.: Testing Treatments, 2. Aufl. – „Why do we need fair tests of treatments?“","oeffentlich":true,"url":"https://www.testingtreatments.org/book/need-fair-tests-treatments/","abruf":"2026-10-12"},{"typ":"url","kurz":"Evans, I.; Thornton, H.; Chalmers, I.; Glasziou, P.: Testing Treatments, 2. Aufl. – „What are fair tests of treatments?“","oeffentlich":true,"url":"https://www.testingtreatments.org/book/fair-tests-treatments/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"99afa291fb280689"}},{"id":"qx-a1-010","clusterId":"A","werkstueckRef":"A.2","stufe":2,"question":"Was fehlt dieser „Studie“ vor allem, um als Beleg für die Wirkung zu taugen?","scenario":"Eine Kosmetikfirma wirbt: „Wissenschaftlich bewiesen! 95 % von 100 befragten Frauen bestätigen: Die Haut fühlt sich nach vier Wochen Anwendung der neuen Creme straffer an.“ Die Firma schließt daraus: Die Erfahrungen der Testerinnen bestätigen die Wirksamkeit.","options":["Eine zufällige Auswahl der Befragten aus allen Frauen: Nur so ließe sich das Ergebnis auf Frauen insgesamt übertragen.","Ein Konfidenzintervall zu den 95 %: Es zeigt, wie stark der Anteil bei nur 100 Befragten zufällig schwanken kann.","Eine verblindete Vergleichsgruppe mit normaler Creme: Sonst bleibt offen, ob die Creme wirkt oder nur die Erwartung.","Eine Erfassung der Nebenwirkungen: Ohne sie lässt sich nicht beurteilen, ob die Creme für die Haut unbedenklich ist."],"correctIndex":2,"explanation":"Die Werbung stützt sich auf eine reine Befragung: Es gibt keine Vergleichsgruppe, das Ergebnis („fühlt sich straffer an“) ist subjektiv, und die Erwartung der Teilnehmerinnen wird nicht kontrolliert. Wer eine neue Creme testet und hofft, dass sie wirkt, nimmt auch ohne echte Wirkung oft eine Besserung wahr. Erst der Vergleich mit einer Gruppe, die eine normale Creme benutzt, ohne dass die Frauen wissen, welche sie bekommen, trennt die tatsächliche Wirkung von Erwartung und Zufall. Die anderen Punkte sind für sich sinnvoll, klären aber nicht, ob die Creme wirkt: Eine zufällige Auswahl betrifft nur die Frage, auf wen sich ein Ergebnis übertragen ließe. Ein Konfidenzintervall zeigt nur die Zufallsschwankung des Anteils, nicht ob die Creme dafür verantwortlich ist. Und Nebenwirkungen betreffen die Verträglichkeit, nicht die Wirkung.","coreRule":"⚡ Ohne Vergleichsgruppe misst eine Umfrage Erwartungen, nicht Wirkungen.","beleg":"Werkstück A.2 (Ebene 3: Beispiel Anti-Falten-Creme; Gekaufte Institute & Raubjournale) Szenario am 14.10.2026 nach Sturms Urteil geändert: Der Hinweis „keine Vergleichsgruppe“ steht nicht mehr im Szenario.","status":"entwurf","kurz":"Eine reine Befragung kann nicht trennen, ob die Creme wirkt oder nur die Erwartung der Testerinnen. Der naheliegende Fehler ist, ein gutes Gefühl nach der Anwendung für eine Wirkung zu halten, obwohl ein Vergleich mit normaler Creme fehlt.","prueffrage":"Wie wurde „straffer“ gemessen, und wer hat es beurteilt?","rueckmeldung":[{"option":0,"text":"Eine zufällige Auswahl entscheidet darüber, auf wen sich ein Ergebnis übertragen ließe. Ob die Creme überhaupt wirkt, klärt sie nicht: Auch bei bestens ausgewählten Befragten bliebe offen, ob Creme oder Erwartung das straffere Gefühl erzeugt."},{"option":1,"text":"Ein Konfidenzintervall zeigt, wie stark ein Anteil bei 100 Befragten zufällig schwanken kann. Es sagt aber nichts darüber, wodurch die Antworten zustande kamen: Auch ein sehr genauer Anteil kann allein von der Erwartung herrühren."},{"option":3,"text":"Nebenwirkungen zu erfassen ist wichtig, aber es geht um Verträglichkeit, nicht um Wirkung. Selbst eine nachweislich unbedenkliche Creme müsste noch zeigen, dass sie mehr bewirkt als eine normale Creme."}],"familie":"fair-testen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Evans, I.; Thornton, H.; Chalmers, I.; Glasziou, P.: Testing Treatments, 2. Aufl. – „What are fair tests of treatments?“","oeffentlich":true,"url":"https://www.testingtreatments.org/book/fair-tests-treatments/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen"},{"id":"qx-a1-011","clusterId":"A","werkstueckRef":"A.2","stufe":3,"question":"Was folgt aus dem Wort „signifikant“ für die Werbeaussage, und was nicht?","scenario":"Ein Hersteller wirbt für sein Diätmittel: „In einer Studie nahmen die Teilnehmer in sechs Monaten signifikant ab!“ Auf Nachfrage räumt er ein, dass der durchschnittliche Unterschied zur Vergleichsgruppe bei 50 Gramm liegt.","options":["Der Effekt ist groß genug, um im Alltag spürbar zu sein, sonst würde man ihn nicht „signifikant“ nennen.","Die Daten passen schlecht zu der Annahme „kein Effekt“, doch ob 50 Gramm irgendeine Bedeutung haben, bleibt offen und muss separat beurteilt werden.","Zufall und Verzerrung sind damit ausgeschlossen, und die Wirkung des Mittels gilt als sicher belegt.","Die Studie war doppelt verblindet und entspricht damit dem Goldstandard, sonst dürfte man das Ergebnis nicht „signifikant“ nennen."],"correctIndex":1,"explanation":"„Statistisch signifikant“ heißt nur: Die Daten passen schlecht zu der Annahme, dass das Mittel gar nichts bewirkt. Über die Größe oder Wichtigkeit des Effekts sagt der Begriff nichts. 50 Gramm in sechs Monaten können daher statistisch ein Erfolg und praktisch nutzlos sein. Ein signifikantes Ergebnis spricht gegen bloßen Zufall, schließt ihn aber nicht aus, und ob Verzerrungen begrenzt wurden, hängt vom Studiendesign ab: von Kontrollgruppe, Randomisierung und Verblindung. Die entscheidende Nachfrage lautet deshalb: Wie groß ist die Effektstärke, und ist sie für den Alltag relevant?","coreRule":"⚡ Signifikant ist nicht dasselbe wie relevant: Frag immer nach der Effektstärke.","beleg":"Werkstück A.2 (Ebene 4: Der Missbrauch durch „Signifikanz“; Die 4 Säulen der Resilienz)","status":"entwurf","kurz":"„Signifikant“ heißt nur, dass die Daten schlecht zu „kein Effekt“ passen, nicht, dass der Effekt groß oder wichtig ist. 50 Gramm in sechs Monaten können statistisch ein Erfolg und praktisch nutzlos sein. Entscheidend ist die Effektstärke.","prueffrage":"Was genau wurde in der Studie verglichen, und wie viele Personen waren in jeder Gruppe?","rueckmeldung":[{"option":0,"text":"Im Alltag bedeutet „signifikant“ so viel wie „bedeutsam“, in der Statistik aber nicht. Das Wort sagt nur, dass die Daten schlecht zu „kein Effekt“ passen, nicht, wie groß ein Effekt ist; 50 Gramm in sechs Monaten zeigen das gut."},{"option":2,"text":"Ein signifikantes Ergebnis spricht gegen „kein Effekt“, schließt Zufall aber nicht aus, und gegen Verzerrung helfen erst Kontrollgruppe, Randomisierung und Verblindung. „Sicher belegt“ geht deshalb zu weit."},{"option":3,"text":"Eine Verblindung ist ein wichtiges Qualitätsmerkmal des Designs, aber das Wort „signifikant“ sagt nichts darüber. Ob verblindet wurde, verrät die Werbung nicht; das Wort beschreibt nur, wie gut die Daten zu „kein Effekt“ passen."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"American Statistical Association (2016): ASA releases Statement on Statistical Significance and P-Values (Pressemitteilung mit den sechs Grundsätzen)","oeffentlich":true,"url":"https://www.amstat.org/asa/files/pdfs/p-valuestatement.pdf","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2dceb21de6d70768"}},{"id":"qx-a1-012","clusterId":"A","werkstueckRef":"A.2","stufe":4,"question":"Welches Vorgehen führt hier am ehesten zu einem verlässlichen Gesamturteil, und worauf bleibt es angewiesen?","scenario":"Ein Ratgeber schreibt: „Fünf Studien belegen die Wirkung von Vitamin X – ein überwältigender Beweis!“ Du findest heraus: Es gibt 95 weitere Studien zum selben Mittel, überwiegend groß und sorgfältig, mit einem Effekt nahe null. Du willst alle 100 Studien zu einem Gesamturteil zusammenführen.","options":["Die gemessenen Effekte aller Studien zu einem Gesamtergebnis verrechnen, wobei große, genaue Studien mehr Gewicht bekommen; das Urteil hängt davon ab, ob auch die erfolglosen Studien veröffentlicht wurden.","Die fünf positiven Studien von unabhängigen Teams wiederholen lassen und deren Ergebnis als Gesamturteil nehmen; das Urteil hängt davon ab, ob die Wiederholungen die ursprünglichen Befunde bestätigen.","Die Studien nach Land und Studiendauer in Gruppen aufteilen und jede Gruppe für sich auswerten, ohne sie später zusammenzuführen; das Urteil hängt davon ab, nach welchen Merkmalen man die Gruppen bildet.","Eine neue, große und sorgfältig geplante Studie zu Vitamin X durchführen und deren Ergebnis als Gesamturteil nehmen; das Urteil hängt davon ab, wie gut diese neue Studie geplant und umgesetzt wird."],"correctIndex":0,"explanation":"Ein verlässliches Gesamturteil zählt keine Treffer, sondern verrechnet die gemessenen Effekte aller Studien. Große, genaue Studien liefern dabei sicherere Schätzungen und verdienen mehr Gewicht als kleine, zufallsanfällige. Außerdem hängt jede Zusammenfassung von ihrem Material ab: Wenn die erfolglosen Studien in der Schublade liegen, ist auch das Gesamtergebnis verzerrt. Umgekehrt können viele kleine Studien, die einzeln nichts Sicheres zeigen, zusammen einen echten Effekt sichtbar machen. Die anderen Wege sind für sich genommen übliche Werkzeuge, führen hier aber nicht zum Ziel: Wiederholungen der fünf positiven Studien klären nur diese fünf und lassen die 95 vorhandenen außer Acht. Eine getrennte Auswertung einzelner Gruppen liefert gerade kein gemeinsames Urteil. Und eine weitere Einzelstudie wirft die Information aus den vorhandenen 100 Studien weg.","coreRule":"⚡ Bei der Zusammenfassung vieler Studien zählt das Gewicht der Effekte, nicht die Zahl der Treffer – und das Ergebnis ist nur so gut wie die Studien, die überhaupt veröffentlicht wurden.","beleg":"Werkstück A.2 (Ebene 5); Fn. ga-metaanalyse (Deeks u. a. 2024, Cochrane Handbook 6.5, Kap. 10, Abschn. 10.2.1 und 10.3; McKenzie/Brennan 2024, Kap. 12, Abschn. 12.2.2.1)","status":"entwurf","kurz":"Ein verlässliches Gesamturteil verrechnet die Effekte aller Studien und gewichtet große, genaue stärker; es hängt davon ab, ob auch die erfolglosen veröffentlicht wurden. Fünf Treffer herauszupicken, täuscht Gewissheit vor, wo 95 Studien kaum einen Effekt zeigen.","prueffrage":"Was haben die fünf zitierten Studien gemeinsam, das die 95 übrigen nicht haben?","rueckmeldung":[{"option":1,"text":"Unabhängige Wiederholungen sind ein gutes Werkzeug, um Einzelbefunde zu prüfen. Hier bleibt das Urteil aber auf diese fünf Studien beschränkt, während die 95 vorhandenen mit Effekt nahe null außen vor bleiben."},{"option":2,"text":"Eine Aufteilung nach Land und Dauer kann Unterschiede zeigen, bleibt aber bei Teilergebnissen stehen. Ohne spätere Zusammenführung gibt es kein Gesamturteil, und je nach gewählten Merkmalen fallen die Gruppenbefunde verschieden aus."},{"option":3,"text":"Eine große, sorgfältige Studie wäre eine wertvolle Ergänzung. Als alleiniges Gesamturteil verwirft sie aber, was die vorhandenen 100 Studien schon zeigen, und hängt ganz an der Qualität dieser einen Studie."}],"familie":"studie-genau-lesen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Deeks, J. J. u. a.: Analysing data and undertaking meta-analyses. Cochrane Handbook, Kap. 10","oeffentlich":true,"url":"https://www.cochrane.org/authors/handbooks-and-manuals/handbook/current/chapter-10","abruf":"2026-10-07"},{"typ":"url","kurz":"McKenzie, J. E.; Brennan, S. E.: Synthesizing and presenting findings using other methods. Cochrane Handbook, Kap. 12","oeffentlich":true,"url":"https://www.cochrane.org/authors/handbooks-and-manuals/handbook/current/chapter-12","abruf":"2026-10-12"},{"typ":"url","kurz":"Page, M. J.; Higgins, J. P. T.; Sterne, J. A. C.: Assessing risk of bias due to missing evidence in a meta-analysis. Cochrane Handbook, Kap. 13","oeffentlich":true,"url":"https://www.cochrane.org/authors/handbooks-and-manuals/handbook/current/chapter-13","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"6e369539bc676e76"}},{"id":"qx-a1-013","clusterId":"A","werkstueckRef":"A.3","stufe":1,"question":"Zwei Forscherinnen stellen jeweils eine Theorie auf. Theorie 1 sagt voraus: „Das Licht ferner Sterne wird am Rand der Sonne um einen bestimmten Betrag abgelenkt; zeigt die nächste Sonnenfinsternis keine oder eine andere Ablenkung, ist die Theorie falsch.“ Theorie 2 sagt: „Eine Ablenkung kann auftreten, muss aber nicht; fällt sie aus, haben eben andere Kräfte mitgewirkt.“ Warum ist Theorie 1 wissenschaftlich wertvoller?","options":["Sie legt sich fest und kann an einer Beobachtung scheitern, denn schon ein abweichendes Ergebnis würde sie widerlegen.","Sie ist logisch widerspruchsfreier, denn eine wissenschaftliche Theorie darf sich in ihren Aussagen nicht selbst widersprechen.","Sie ist praxisnäher, denn eine wissenschaftliche Theorie sollte vor allem Anwendungen hervorbringen, die sich technisch nutzen lassen.","Sie erklärt mehr Beobachtungen, denn eine Theorie ist umso wertvoller, je mehr verschiedene Beobachtungen sie abdeckt."],"correctIndex":0,"explanation":"Eine wissenschaftliche Theorie sagt nicht nur voraus, was passieren wird, sondern vor allem, was nicht passieren darf. Theorie 1 nennt eine Beobachtung, die sie widerlegen würde, und setzt sich damit einem echten Risiko aus. So war es auch bei Einsteins Relativitätstheorie vor der Sonnenfinsternis 1919: Hätte die Beobachtung keine oder eine falsche Ablenkung gezeigt, wäre die Theorie in ihrer damaligen Form widerlegt gewesen. Theorie 2 ist mit jedem Ergebnis vereinbar und lässt sich deshalb durch nichts prüfen. Wissenschaftlich wertvoll macht eine Theorie also nicht, dass sie sich bestätigen lässt, sondern dass sie scheitern könnte. Widerspruchsfreiheit ist eine Mindestanforderung, doch von einem inneren Widerspruch ist bei keiner der beiden Theorien die Rede. Technische Nutzbarkeit spielt hier keine Rolle, beide Aussagen betreffen dieselbe Beobachtung. Und mehr Beobachtungen deckt Theorie 2 nur scheinbar ab, denn sie ist mit jedem Ergebnis vereinbar, ohne etwas zu erklären.","coreRule":"⚡ Eine Theorie wird durch das Risiko wissenschaftlich, an der Beobachtung zu scheitern, nicht durch ihre Bestätigungen allein.","quote":"","quoteLabel":"","beleg":"Werkstück A.3 (Kontext & Tiefe); Fn. ga-popper (Popper 1935, Logik der Forschung; engl. 1959, Abgrenzungskriterium Abschn. 6)","status":"entwurf","scenario":"","kurz":"Eine Theorie ist wertvoll, wenn sie sagt, was nicht passieren darf, und so scheitern könnte. Theorie 1 riskiert das; Theorie 2 verträgt jedes Ergebnis und lässt sich durch nichts prüfen, auch wenn sie vorsichtig klingt.","prueffrage":"Was würde Theorie 2 sagen, wenn die Ablenkung doppelt so groß, halb so groß oder gar nicht aufträte?","rueckmeldung":[{"option":1,"text":"Widerspruchsfreiheit ist eine echte Mindestanforderung, aber hier trifft sie beide Theorien gleich, denn keine widerspricht sich selbst. Theorie 2 ist nicht widersprüchlich, sondern so offen, dass kein Ergebnis ihr schaden kann."},{"option":2,"text":"Nutzbare Anwendungen können ein Gewinn sein, doch hier geht es um dieselbe Beobachtung, die beide Theorien betreffen. Ob sich etwas technisch verwerten lässt, entscheidet nicht, welche der beiden sich überhaupt prüfen lässt."},{"option":3,"text":"Je mehr Beobachtungen eine Theorie erklärt, desto besser, das stimmt grundsätzlich. Theorie 2 deckt aber nur scheinbar alles ab: Sie verträgt jedes Ergebnis, ohne etwas zu erklären, und das ist keine Erklärungskraft."}],"familie":"widerlegung-benennen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Thornton, S.: Karl Popper. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Popper, K. R. (1959): The Logic of Scientific Discovery. London: Hutchinson (dt. Logik der Forschung, 1935)","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3cc2271636735f87"}},{"id":"qx-a1-014","clusterId":"A","werkstueckRef":"A.3","stufe":2,"question":"Welche Rückfrage deckt den Kern des Problems an dieser Behauptung am besten auf?","scenario":"Eine Hellseherin sagt: „Meine Gabe wirkt nicht unter Testbedingungen. Die Anwesenheit von Skeptikern und Messgeräten stört die feinstofflichen Energien.“ Du möchtest ihre Fähigkeit überprüfen.","options":["„Wie hoch ist die Wahrscheinlichkeit, dass Hellsehen überhaupt existiert, und wann scheiden unwahrscheinliche Behauptungen aus der Prüfung aus?“","„Welches Ergebnis eines fairen Tests würdest du als Beleg dafür akzeptieren, dass deine Gabe nicht funktioniert?“","„Wie würdest du die Behauptung formulieren, wenn du ganz auf mehrdeutige Begriffe verzichten müsstest?“","„Warum solltest du glaubwürdig sein, wenn du doch selbst von deiner Fähigkeit überzeugt bist?“"],"correctIndex":1,"explanation":"Die Hellseherin erklärt das Ausbleiben des Effekts schon im Voraus: Sobald jemand prüft, „stört“ das Messen die Gabe. Damit kann kein denkbares Testergebnis sie noch widerlegen, und eine Behauptung, die nicht scheitern kann, sagt nichts über die Welt. Die Rückfrage nach dem akzeptierten Gegenbeleg legt genau das offen: Nennt sie ein Ergebnis, ist die Behauptung prüfbar; findet sie keines, ist sie immunisiert. Unwahrscheinlich ist nicht dasselbe wie unprüfbar: Eine unwahrscheinliche Behauptung, die ein klares Scheitern zuließe, wäre durchaus testbar. Auch Befangenheit oder unscharfe Wortwahl sind hier nicht der Kern. Entscheidend ist, dass die Begründung jedes Scheitern im Voraus wegerklärt.","coreRule":"⚡ Frag bei jeder Behauptung: Welches Ergebnis würde sie widerlegen? Eine Behauptung, die ihr Scheitern schon vorab wegerklärt, sagt nichts mehr über die Welt.","beleg":"Werkstück A.3 (Anwendung & Relevanz: Bei Parawissenschaft & Aberglaube)","status":"entwurf","kurz":"Die Rückfrage nach dem Gegenbeleg zeigt, ob die Behauptung überhaupt scheitern kann. Plausibilität oder Wortwahl anzugreifen trifft nicht den Kern: Schon ihre Begründung erklärt jedes Scheitern im Voraus weg.","prueffrage":"Unter welchen Bedingungen hat sie ihre Gabe bisher gezeigt, und wer war dabei?","rueckmeldung":[{"option":0,"text":"Wie wahrscheinlich Hellsehen ist, spielt für die Beweislast eine Rolle. Den Kern trifft es aber nicht: Auch eine unwahrscheinliche Behauptung wäre testbar, wenn sie klar scheitern dürfte. Hier erklärt die Begründung jedes Scheitern weg."},{"option":2,"text":"Klare Begriffe machen eine Behauptung greifbarer, und „feinstoffliche Energien“ ist tatsächlich unscharf. Selbst ganz präzise formuliert bliebe sie aber immun, solange das Prüfen selbst als Störung gilt."},{"option":3,"text":"Eigene Überzeugung ist tatsächlich noch kein Beleg. Die Frage zielt aber auf die Person statt auf die Behauptung. Wer aufrichtig überzeugt ist, kann trotzdem Prüfbares sagen; entscheidend ist, ob ein Scheitern denkbar bleibt."}],"familie":"widerlegung-benennen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Thornton, S.: Karl Popper. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/popper/","abruf":"2026-10-12"},{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2715730c85921a32"}},{"id":"qx-a1-015","clusterId":"A","werkstueckRef":"A.3","stufe":3,"question":"Woran erkennst du, ob die Zusatzannahme des Astronomen brauchbar oder bloße Rettung ist?","scenario":"Ein Astronom sagt: „Meine Theorie passt nicht zu den Messdaten der Bahn dieses Planeten. Ich nehme deshalb einen noch unbekannten Himmelskörper an, dessen Schwerkraft die Abweichung verursacht.“ Eine Kollegin hält dagegen: „Das ist doch nur eine Ausrede, um die Theorie zu retten.“ Beim Uranus führte genau so eine Annahme 1846 zur Entdeckung des Neptun. Beim Merkur ließ sich der angenommene Planet „Vulkan“ nie nachweisen; die Abweichung erklärte erst Einsteins Relativitätstheorie.","options":["Brauchbar ist sie, wenn sie neue, prüfbare Vorhersagen liefert, die scheitern könnten und sich zum Teil bestätigen, sonst flickt sie die Theorie nur nachträglich.","Brauchbar ist sie, wenn sich ein Wirkungsweg angeben lässt, etwa die Schwerkraft des Körpers, denn ohne denkbaren Mechanismus bleibt jede Annahme leer.","Brauchbar ist sie, wenn andere Forschende die Abweichung in den Messdaten unabhängig bestätigen, denn erst dann steht fest, dass es etwas zu erklären gibt.","Brauchbar ist sie, wenn sie mit einer einzigen zusätzlichen Annahme auskommt, denn nach dem Prinzip der Sparsamkeit ist die schlichtere Erklärung vorzuziehen."],"correctIndex":0,"explanation":"Eine Zusatzannahme allein ist noch kein Alarmsignal. Entscheidend ist, ob sie etwas Neues vorhersagt, das sich prüfen lässt und scheitern könnte, und ob sich davon etwas bestätigt: Der Planet für die Uranusbahn wurde 1846 gefunden, „Vulkan“ dagegen trotz Suche nie; diese Annahme war prüfbar, hielt der Prüfung aber nicht stand. Bloße Rettung ist eine Annahme, die jeder Prüfung ausweicht, etwa ein Himmelskörper, der grundsätzlich weder zu sehen noch zu messen sein soll; dass sie unwiderlegt bleibt, beweist nichts. Ein pauschales Verbot von Zusatzannahmen hätte den Neptun nie finden lassen. Das Urteil bleibt dabei graduell und vorläufig. Einen denkbaren Wirkungsweg hatten beide Annahmen, nämlich die Schwerkraft eines unbekannten Körpers, und trotzdem ging nur eine auf. Die Abweichung unabhängig nachzumessen klärt nur, dass es etwas zu erklären gibt, nicht ob die Erklärung stimmt. Und dass die Annahme schlicht ist, gilt für Neptun wie für Vulkan und trennt die beiden daher nicht.","coreRule":"⚡ Eine Hilfsannahme wird verdächtig, wenn sie nichts Neues vorhersagt, das scheitern könnte.","beleg":"Werkstück A.3 (Red Flags: Die Ad-hoc-Hypothese); Fn. ga-hilfsannahmen (Musgrave/Pigden, Stanford Encyclopedia of Philosophy, „Imre Lakatos“, Abschn. 2.2; McIntyre 2020, S. 38–39)","status":"entwurf","kurz":"Brauchbar ist eine Zusatzannahme, wenn sie Neues vorhersagt, das scheitern könnte, und sich davon etwas bestätigt. So war es beim Neptun, bei „Vulkan“ nicht. Der Denkfehler wäre, jede Zusatzannahme als Ausrede zu verwerfen.","prueffrage":"Was geschah nach der Zusatzannahme beim Uranus, was beim Merkur ausblieb?","rueckmeldung":[{"option":1,"text":"Ein denkbarer Wirkungsweg ist eine sinnvolle Mindestanforderung. Er trennt die beiden Fälle aber nicht: Neptun und „Vulkan“ hatten ihn beide, nämlich die Schwerkraft eines unbekannten Körpers, und nur einer wurde gefunden."},{"option":2,"text":"Bestätigte Messdaten zeigen, dass es etwas zu erklären gibt, mehr nicht. Bei Uranus und Merkur war die Abweichung beide Male real, und nur eine der beiden Zusatzannahmen hielt der Prüfung stand."},{"option":3,"text":"Die Schlichtheit einer Erklärung hilft oft bei der Wahl. Hier aber kam jede der beiden Annahmen mit einem unbekannten Körper aus, sie trennt Neptun und „Vulkan“ also nicht."}],"familie":"immunisierung-erkennen","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Musgrave, A.; Pigden, C.: Imre Lakatos. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/lakatos/","abruf":"2026-10-12"},{"typ":"url","kurz":"Wills, M. (2016): Where in the Solar System is Vulcan? JSTOR Daily","oeffentlich":true,"url":"https://daily.jstor.org/solar-system-vulcan/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"McIntyre, L. (2020): Wir lieben Wissenschaft. Berlin: Springer, S. 38–39 (laut Fußnote ga-hilfsannahmen)","oeffentlich":false}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"7e07a1f0a3763c4a"}},{"id":"qx-a1-016","clusterId":"A","werkstueckRef":"A.3","stufe":4,"question":"Ab wann wird eine nicht widerlegbare Aussage zum Problem?","scenario":"Zwei Sätze: (1) „Ich glaube, dass das Universum mich trägt.“ (2) „Meine Energieheilung wirkt auf einer Ebene, die keine Messung erfassen kann, darum brauchst du deine Therapie nicht.“ Beide sind so gebaut, dass keine Beobachtung sie widerlegen kann. Eine Freundin meint: „Wenn man etwas nicht widerlegen kann, ist beides gleich unproblematisch.“","options":["Der erste Satz bleibt als persönlicher Glaube oder Bild harmlos; der zweite wird zum Problem, weil er die Wirklichkeit beschreiben will und Entscheidungen anderer prägen kann.","Der zweite Satz wird erst zum Problem, wenn sich damit Geld verdienen lässt; ohne finanzielles Interesse bleibt eine unprüfbare Aussage ein harmloser Glaube.","Der erste Satz ist harmlos, solange nur wenige ihn teilen; der zweite wird erst gefährlich, wenn ihm viele Menschen folgen, weil erst die Verbreitung einer Ansicht Schaden anrichtet.","Keiner der beiden Sätze wird zum Problem, solange die Sprecherin aufrichtig daran glaubt; erst eine bewusste Täuschung anderer macht eine unwiderlegbare Aussage schädlich."],"correctIndex":0,"explanation":"Eine Aussage, die sich nicht widerlegen lässt, kann als persönliches Glaubensbekenntnis oder als Metapher (etwa in Kunst oder Religion) harmlos sein, denn sie erhebt nicht den Anspruch, eine objektive Beschreibung der Realität zu sein. Problematisch wird sie, wenn sie genau diesen Anspruch erhebt und auf dieser Basis Entscheidungen getroffen werden, die andere betreffen, besonders in Medizin, Politik oder Justiz. Wenn eine unprüfbare Heilmethode eine wirksame medizinische Behandlung ersetzt, kann das tödlich sein. Dass sich eine Aussage nicht widerlegen lässt, macht sie nicht zu einer Beschreibung der Wirklichkeit; entscheidend ist, welchen Anspruch sie erhebt und welche Folgen für Betroffene daran hängen, nicht die Unwiderlegbarkeit an sich. Hinweis: Widerlegbarkeit allein gilt laut Fachdiskussion nicht als scharfe Trennlinie zwischen Wissenschaft und Pseudowissenschaft. Geld spielt dabei nur eine Nebenrolle: Der Schaden entsteht schon, wenn jemand im Vertrauen auf die Aussage auf Behandlung verzichtet, auch ohne Verkaufsinteresse. Auch die Zahl der Anhänger ist nicht der Maßstab, denn die Entscheidung einer einzelnen Person kann bereits schwer wiegen. Und aufrichtiger Glaube schützt niemanden vor den Folgen einer unterlassenen Behandlung.","coreRule":"⚡ Nicht die Unwiderlegbarkeit an sich ist das Problem, sondern der Anspruch auf Wirklichkeit, an dem Entscheidungen anderer hängen.","beleg":"Werkstück A.3 (Der Kipppunkt); Fn. ga-popper (Laudan 1983, S. 111–127; Pigliucci/Boudry 2013)","status":"entwurf","kurz":"Eine unwiderlegbare Aussage ist harmlos, solange sie nur Glaube oder Bild sein will. Problematisch wird sie, wenn sie die Wirklichkeit beschreiben will und andere darauf Entscheidungen stützen, etwa den Verzicht auf Behandlung.","prueffrage":"Was würde ein schwer kranker Mensch tun, der jeden der beiden Sätze wörtlich nimmt?","rueckmeldung":[{"option":1,"text":"Wo Geld im Spiel ist, ist Misstrauen berechtigt. Der Schaden hängt daran aber nicht: Wer im Vertrauen auf die Aussage auf Behandlung verzichtet, riskiert auch dann sein Leben, wenn niemand daran verdient."},{"option":2,"text":"Verbreitung kann einen Schaden gewaltig vergrößern. Die Zahl der Anhänger ist aber nicht der Maßstab, denn schon die Entscheidung einer einzelnen Person, die deshalb eine Behandlung auslässt, kann schwer wiegen."},{"option":3,"text":"Eine bewusste Täuschung käme als eigenes Problem hinzu. Aufrichtigkeit macht die Aussage aber nicht ungefährlich: Wer auf eine wirksame Therapie verzichtet, trägt die Folgen, ganz gleich, wie ehrlich die Sprecherin überzeugt ist."}],"familie":"ergaenzen-oder-ersetzen","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Hansson, S. O.: Science and Pseudo-Science. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/pseudo-science/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Laudan, L. (1983): The Demise of the Demarcation Problem. In: Cohen, R. S.; Laudan, L. (Hg.): Physics, Philosophy and Psychoanalysis. Dordrecht: Reidel, 111–127","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"df51ac34121de6fc"}},{"id":"qx-a1-017","clusterId":"A","werkstueckRef":"A.4","stufe":1,"question":"Was ist an der Forderung des Bekannten fehlerhaft?","scenario":"Ein Bekannter sagt über seine Kristalle: „Die haben heilende Energie. Beweise mir doch, dass es nicht stimmt!“ Du hast keinen Beleg dafür, dass es falsch ist, aber auch keinen, dass es stimmt.","options":["Ein Post-hoc-Fehlschluss: Er hält eine Besserung nach dem Kauf der Kristalle schon für den Beweis, dass die Kristalle sie bewirkt haben.","Eine Umkehr der Beweislast: Wer eine Wirkung behauptet, muss sie belegen; dass sich ihr Fehlen nicht beweisen lässt, spricht nicht für sie.","Ein Autoritätsargument: Er stützt seine Behauptung allein darauf, dass angeblich anerkannte Fachleute sie für richtig halten.","Ein persönlicher Angriff (Ad hominem): Er greift deine Person an, statt auf deine Einwände einzugehen, und lenkt so vom Thema ab."],"correctIndex":1,"explanation":"Wer eine Behauptung aufstellt, muss sie belegen; wer zweifelt, muss nichts widerlegen. Das ist nicht Willkür, sondern die einzige praktikable Regel: Die Nicht-Existenz beliebiger Dinge lässt sich nie beweisen, nicht bei Russells winziger Teekanne zwischen Erde und Mars, nicht bei Geistern oder Feen. Müsste jeder Zweifler solche Behauptungen widerlegen, wäre man entweder gezwungen, alles zu glauben, oder könnte nie zu einem Urteil kommen. Dass du das Gegenteil nicht beweisen kannst, ist daher kein Hinweis auf die Wahrheit der Behauptung. Ein Post-hoc-Schluss würde eine beobachtete Besserung den Kristallen zuschreiben, doch davon ist nirgends die Rede. Auf Fachleute beruft sich der Bekannte ebenfalls nicht, er behauptet nur. Und er greift dich nicht persönlich an, sondern verlangt von dir einen Beweis, den du nicht schuldest.","coreRule":"⚡ „Beweise mir das Gegenteil“ verschiebt die Last – wer behauptet, liefert.","beleg":"Werkstück A.4 (Anwendung & Relevanz: Bei Pseudomedizin & Esoterik); Fn. ga-russell (Russell 1952, Collected Papers Bd. 11, S. 547 f.)","status":"entwurf","kurz":"Wer behauptet, dass Kristalle heilende Energie haben, muss das belegen. Dass sich das Gegenteil nicht beweisen lässt, spricht nicht für die Behauptung, denn die Nichtexistenz beliebiger Dinge lässt sich nie beweisen. Der Fehler liegt in der umgekehrten Beweislast.","prueffrage":"Wie könnte man herausfinden, ob es Menschen mit Kristallen besser geht als ohne?","rueckmeldung":[{"option":0,"text":"Ein Post-hoc-Fehlschluss ist ein echter Denkfehler: Aus „danach“ wird „deswegen“. Im Szenario ist aber von keiner Besserung die Rede; der Bekannte behauptet nur eine Wirkung und verlangt von dir einen Gegenbeweis."},{"option":2,"text":"Der Griff zur Autorität ist ein bekannter Fehler: Man stützt sich auf angebliche Experten statt auf Belege. Der Bekannte beruft sich aber auf niemanden, er behauptet die Wirkung einfach selbst."},{"option":3,"text":"Ein Ad-hominem-Angriff richtet sich gegen die Person statt gegen ihre Argumente. Der Bekannte wertet dich aber nicht ab, er verlangt nur einen Beweis von dir. Fehlerhaft ist, wem die Beweislast zufällt, nicht, wie er über dich spricht."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Russell, B. (1952): Is There a God? In: Collected Papers of Bertrand Russell, Bd. 11. London: Routledge 1997, 543–548","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"34e7ec7a5b4c94a2"}},{"id":"qx-a1-018","clusterId":"A","werkstueckRef":"A.4","stufe":2,"question":"Wie viel Beleg darfst du von den beiden Kolleginnen jeweils verlangen, bevor du ihnen glaubst?","scenario":"Eine Kollegin sagt: „Ich habe heute früh einen Kaffee getrunken.“ Eine andere sagt: „Ich wurde heute früh von Außerirdischen entführt und habe mit ihnen Kaffee getrunken.“ Du sollst entscheiden, wem du was glaubst.","options":["Bei beiden gleich viel, weil nur eine Gleichbehandlung beider Kolleginnen verhindert, dass man einer von ihnen voreingenommen begegnet.","Bei der ersten kaum, bei der zweiten ebenfalls wenig, wenn sie ihr Erlebnis detailreich erzählt, weil Detailreichtum für die Wahrheit spricht.","Bei beiden nichts, weil die Beweislast bei dir liegt: Du müsstest erst zeigen, dass die Aussagen falsch sind, bevor du sie ablehnst.","Bei der ersten kaum, bei der zweiten sehr viel, weil der geforderte Aufwand mit der Außergewöhnlichkeit der Aussage wächst."],"correctIndex":3,"explanation":"Wer etwas behauptet, muss es belegen, und zwar umso gründlicher, je außergewöhnlicher die Behauptung ist. Die Stärke der geforderten Beweise muss zur Außergewöhnlichkeit der Behauptung proportional sein. Die Aussage, heute früh einen Kaffee getrunken zu haben, erfordert kaum Beweise. Die Aussage, von Außerirdischen entführt worden zu sein und mit ihnen Kaffee getrunken zu haben, erfordert massive, stichhaltige und überprüfbare Beweise. Dass eine Aussage auffällig ist, macht sie nicht glaubwürdiger, sondern erhöht die Anforderung an den Beleg. Gleichbehandlung heißt nicht gleich viel Beleg: Gerecht ist derselbe Maßstab, und der ist bei der gewöhnlichen Aussage schnell erfüllt. Eine detailreich erzählte Geschichte ist noch kein Beleg. Und wer etwas behauptet, muss es belegen; du musst die Aussagen nicht erst widerlegen.","coreRule":"⚡ Je ungewöhnlicher die Behauptung, desto stärker müssen die Belege sein.","beleg":"Werkstück A.4 (Kontext & Tiefe)","status":"entwurf","kurz":"Der verlangte Beleg wächst mit der Außergewöhnlichkeit der Aussage: Ein Kaffee am Morgen braucht kaum einen, eine Entführung durch Außerirdische sehr viel. Verführerisch ist, beide gleich zu behandeln, obwohl gleicher Maßstab nicht gleich viel Beleg bedeutet.","prueffrage":"Was könntest du bei jeder der beiden Kolleginnen nachprüfen, um ihre Aussage zu bestätigen?","rueckmeldung":[{"option":0,"text":"Ein gleicher Maßstab für beide ist richtig, und niemand soll voreingenommen behandelt werden. Gleicher Maßstab heißt aber nicht gleich viel Beleg: Er ist bei der gewöhnlichen Aussage schnell erfüllt, bei der außergewöhnlichen erst mit viel mehr."},{"option":1,"text":"Dass beim Kaffee kaum Beleg nötig ist, stimmt. Detailreichtum belegt aber nichts, denn auch eine erfundene Geschichte lässt sich beliebig ausschmücken. Je auffälliger die Aussage, desto mehr Beleg braucht sie, nicht weniger."},{"option":2,"text":"Die Beweislast ist hier umgedreht: Wer etwas behauptet, muss es belegen, du musst es nicht erst widerlegen, bevor du es ablehnst. Zudem macht es einen Unterschied, wie außergewöhnlich die Behauptung ist, und davon hängt ab, wie viel Beleg angemessen ist."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"doi","kurz":"Deming, D. (2016): Do Extraordinary Claims Require Extraordinary Evidence? Philosophia 44(4), 1319–1331","oeffentlich":true,"doi":"10.1007/s11406-016-9779-7","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Sagan, C. (1995): The Demon-Haunted World. New York: Random House","oeffentlich":false}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"0b1e8740bde2ad3a"}},{"id":"qx-a1-019","clusterId":"A","werkstueckRef":"A.4","stufe":3,"question":"Was ist an dieser Forderung fehlerhaft?","scenario":"In einer Debatte über einen Strafprozess sagt jemand: „Der Angeklagte soll beweisen, dass er unschuldig ist. Kann er das nicht lückenlos, gilt er eben als schuldig.“","options":["Sie kehrt die Beweislast um: Die Schuld muss belegt werden, nicht die Unschuld.","Sie schließt von der Gruppe auf den Einzelfall: Die meisten Angeklagten seien schuldig.","Sie beruft sich auf eine Autorität: Der Vorwurf gelte, weil ihn die Anklage erhebt.","Sie ist ein Dammbruch-Argument: Ein Freispruch führe zu einer Welle ungestrafter Taten."],"correctIndex":0,"explanation":"Die Forderung verlangt, eine negative Behauptung („nicht schuldig“) lückenlos zu beweisen, und ein Nicht-Geschehen lässt sich kaum je lückenlos beweisen. Belegen muss grundsätzlich, wer etwas behauptet, hier also die Seite, die den Schuldvorwurf erhebt; im deutschen Strafverfahren müssen Staatsanwaltschaft und Gericht die Schuld von Amts wegen aufklären, und Zweifel gehen nach dem Grundsatz „im Zweifel für den Angeklagten“ nicht zu seinen Lasten. Genau diese Verteilung schützt die Unschuldsvermutung. Im privaten Glauben kann jeder annehmen, was er will; vor Gericht aber ist die Umkehr der Beweislast gefährlich, weil sie Unschuldige zu Verurteilten machen kann. Ein Schluss von der Gruppe auf den Einzelfall wird gar nicht gezogen, über Häufigkeiten spricht niemand. Auf eine Autorität beruft sich die Forderung ebenfalls nicht, sie verlangt vom Angeklagten selbst den Beweis. Und von einer drohenden Welle ungestrafter Taten ist nicht die Rede.","coreRule":"⚡ Wo über andere entschieden wird, trägt die Last, wer anklagt oder behauptet – nicht, wer sich verteidigt.","beleg":"Werkstück A.4 (Kontext & Tiefe; Der Kipppunkt)","status":"entwurf","kurz":"Wer etwas behauptet, muss es belegen: Hier ist das der Schuldvorwurf. Der Fehler liegt darin, vom Angeklagten den lückenlosen Beweis eines Nicht-Geschehens zu verlangen, den kaum jemand erbringen kann; so würden Unschuldige leicht zu Verurteilten.","prueffrage":"Was müsste der Angeklagte vorlegen, um lückenlos zu zeigen, dass er etwas nicht getan hat?","rueckmeldung":[{"option":1,"text":"Es klingt vernünftig, weil die Forderung Angeklagte pauschal in die Pflicht nimmt. Von Häufigkeiten ist aber nirgends die Rede: Die Aussage behauptet nicht, die meisten seien schuldig, und zieht deshalb auch keinen Schluss von der Gruppe auf den Einzelfall."},{"option":2,"text":"Im Raum steht ein Schuldvorwurf, das stimmt. Doch die Forderung stützt sich nicht darauf, dass ihn jemand Maßgebliches erhebt, sondern verlangt vom Angeklagten selbst den Beweis. Eine Berufung auf Autorität findet sich in dem Satz nicht."},{"option":3,"text":"Dammbruch-Argumente malen eine Kette schlimmer Folgen aus. Hier fehlt sie ganz: Weder ein Freispruch noch eine Welle ungestrafter Taten wird erwähnt. Die Aussage fordert nur vom Angeklagten einen lückenlosen Unschuldsbeweis."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Europarat/EGMR: Europäische Menschenrechtskonvention (deutsche Fassung), Art. 6 Abs. 2","oeffentlich":true,"url":"https://www.echr.coe.int/documents/d/echr/convention_deu","abruf":"2026-10-12"},{"typ":"url","kurz":"Bundesministerium der Justiz: Strafprozessordnung § 160 (gesetze-im-internet.de)","oeffentlich":true,"url":"https://www.gesetze-im-internet.de/stpo/__160.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Bundesministerium der Justiz: Strafprozessordnung § 244 (gesetze-im-internet.de)","oeffentlich":true,"url":"https://www.gesetze-im-internet.de/stpo/__244.html","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"da8b18972a0453a1"}},{"id":"qx-a1-020","clusterId":"A","werkstueckRef":"A.4","stufe":4,"question":"Was ist an dieser Forderung der Kern des Denkfehlers?","scenario":"Jemand behauptet, die Mondlandung sei gefälscht. Als man ihm Belege zeigt, verlangt er: „Beweis mir mit hundertprozentiger Sicherheit, dass jeder einzelne Schatten auf den Fotos echt ist.“ Eigene Belege für die Fälschung nennt er nicht.","options":["Er verlangt von der Gegenseite lückenlose Gewissheit, statt seine eigene Behauptung zu belegen.","Er setzt die Fälschung bereits voraus und erklärt damit alle Fotos vorab für gefälscht, ohne sie zu prüfen.","Er unterstellt der Gegenseite eine Position, die sie nie vertreten hat, und widerlegt dann diese erfundene Position.","Er verlangt zu Recht Genauigkeit, denn solange nicht jedes Detail belegt ist, bleibt die Fälschungsthese gleichberechtigt."],"correctIndex":0,"explanation":"Wer eine außergewöhnliche Behauptung aufstellt, muss sie selbst belegen. Hier wird die Beweislast umgekehrt: Die Gegenseite soll etwas nahezu Unmögliches leisten, nämlich absolute Sicherheit in jedem Detail. Die gibt es in der realen Welt fast nie, auch nicht bei gut gesicherten Tatsachen. Dass einzelne Details offen bleiben, macht die Fälschungsthese nicht wahr. Sie braucht eigene, überprüfbare Belege. Und um eine unbelegte Behauptung zu verwerfen, muss man nicht erst das Gegenteil beweisen.","coreRule":"⚡ Lücken beim Gegenüber sind kein Beleg für die eigene These: Wer eine Fälschung behauptet, muss sie belegen.","beleg":"Werkstück A.4 (Anwendung & Relevanz: Bei Verschwörungsmythen; Red Flags)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Wer eine Fälschung behauptet, muss sie selbst belegen. Der Denkfehler: Die Beweislast wird umgedreht, und die Gegenseite soll lückenlose Gewissheit liefern, die es selbst bei gesicherten Tatsachen fast nie gibt.","prueffrage":"Was wurde ihm an Belegen gezeigt, und auf welchen davon geht er in seiner Antwort ein?","rueckmeldung":[{"option":1,"text":"Dass er keine eigenen Belege nennt, stimmt. Er erklärt die Fotos aber nicht vorab für gefälscht, sondern stellt eine überzogene Forderung an die Gegenseite; der Kern liegt bei der Beweislast, nicht bei einem Zirkelschluss."},{"option":2,"text":"Ein Strohmann verzerrt die Position der Gegenseite, um sie leichter anzugreifen. Hier wird ihr aber nichts unterstellt: Er verlangt einen Beweis, der kaum zu liefern ist. Der Fehler liegt in seiner Forderung, nicht in einer Zuschreibung."},{"option":3,"text":"Genauigkeit zu verlangen ist an sich nicht falsch. Hundertprozentige Sicherheit in jedem Detail gibt es aber fast nie, auch bei gut gesicherten Tatsachen. Offene Details machen die Fälschungsthese nicht gleichberechtigt; sie braucht eigene Belege."}],"familie":"beweislast-klaeren","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Dowden, B.: Fallacies. Internet Encyclopedia of Philosophy (Einträge „Appeal to Ignorance“, „Misplaced Burden of Proof“)","oeffentlich":true,"url":"https://iep.utm.edu/fallacy/","abruf":"2026-10-12"}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"9b71a85eef93e37d"}},{"id":"qx-a1-021","clusterId":"A","werkstueckRef":"A.5","stufe":1,"question":"Was ist die sparsamste Erklärung für diesen Zusammenhang?","scenario":"Im Vergleich von 17 europäischen Ländern hängen die Zahl der Storchenpaare und die Zahl der Geburten deutlich zusammen: Die Korrelation liegt bei 0,62 und ist statistisch signifikant. Ein Kommentator schreibt daraus: „Störche bringen eben doch die Babys.“","options":["Der Zufall erzeugt das Muster: Wer viele Größen vergleicht, findet irgendwo eine hohe Korrelation.","Die Landesgröße treibt beides an: Große Länder haben mehr Platz für Störche und mehr Einwohner.","Die Länderauswahl erzeugt das Muster: Wer nur auffällige Länder betrachtet, findet Zusammenhänge.","Die Geburten ziehen die Störche an: Wo viele Kinder zur Welt kommen, siedeln sich mehr Störche an."],"correctIndex":1,"explanation":"Die Korrelation ist echt: Sie wurde für 17 Länder berechnet (r = 0,62) und ist statistisch signifikant. Daraus folgt aber nicht, dass Störche Babys bringen. Bei einem Zusammenhang zwischen A und B gibt es mindestens vier Möglichkeiten: A verursacht B, B verursacht A, ein dritter Faktor verursacht beide, oder es ist Zufall. Hier liegt ein dritter Faktor nahe: Große Länder haben mehr Platz für Störche und mehr Einwohner, also auch mehr Geburten. Die Landesgröße steckt hinter beiden Zahlen und erklärt den Zusammenhang, ohne dass man etwas annehmen muss, was im Szenario nicht vorkommt. Ein bestimmter Korrelationswert beweist nie eine Ursache, egal wie hoch er ist. Zufall durch Mehrfachvergleiche ist ein echtes Risiko, wenn man unter vielen Größen sucht, hier werden aber nur zwei Größen verglichen, und der Zusammenhang ist signifikant. Eine verzerrte Länderauswahl wäre ein berechtigter Vorbehalt, nur gibt das Szenario keinen Hinweis, dass die Länder nach auffälligen Werten ausgesucht wurden. Eine umgekehrte Wirkrichtung ist als Möglichkeit immer zu prüfen, doch es ist keine Wirkungskette erkennbar, über die Geburten Störche herbeilocken sollten.","coreRule":"⚡ Bevor du A als Ursache von B nimmst, such nach einem Faktor C, der beide antreibt.","beleg":"Werkstück A.5 (Kontext & Tiefe: Ein dritter Faktor C); Fn. ga-stoerche (Matthews 2000, Teaching Statistics 22(2), S. 36–38; dt. Fassung 2001, S. 22)","status":"entwurf","kurz":"Zwei Zahlen, die beide mit der Landesgröße wachsen, hängen zusammen, ohne dass eine die andere bewirkt. Große Länder bieten Störchen mehr Platz und haben mehr Einwohner, also mehr Geburten. Aus einer echten Korrelation folgt keine Ursache.","prueffrage":"Worin unterscheiden sich die 17 Länder sonst noch, außer in der Zahl der Störche und der Geburten?","rueckmeldung":[{"option":0,"text":"Zufallsmuster sind ein echtes Risiko, wenn man unter vielen Größen sucht. Hier werden aber nur zwei Größen verglichen, und der Zusammenhang ist signifikant. Es gibt zudem eine einfachere, naheliegende Erklärung."},{"option":2,"text":"Eine verzerrte Länderauswahl wäre ein berechtigter Einwand, wenn es dafür einen Anhaltspunkt gäbe. Das Szenario nennt aber keinen, dass die Länder nach auffälligen Werten ausgesucht wurden. Ohne ihn ist das eine Annahme, keine Erklärung."},{"option":3,"text":"Die umgekehrte Wirkrichtung sollte man bei jedem Zusammenhang prüfen. Hier ist aber keine Wirkungskette erkennbar, über die mehr Geburten Störche herbeilocken sollten. Die Erklärung bräuchte dafür eine Annahme, die nirgends begründet wird."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Matthews, R. (2001): Der Storch bringt die Babys zur Welt (p = 0.008). Stochastik in der Schule 21(2)","oeffentlich":true,"url":"https://www.stochastik-in-der-schule.de/sisonline/struktur/jahrgang21-2001/heft2/Langfassungen/2001-2_Matth.pdf","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Matthews, R. (2000): Storks Deliver Babies (p = 0.008). Teaching Statistics 22(2), 36–38","oeffentlich":false,"doi":"10.1111/1467-9639.00013"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"dc96f2bda8877a18"}},{"id":"qx-a1-022","clusterId":"A","werkstueckRef":"A.5","stufe":2,"question":"Was lässt sich aus diesem beobachteten Zusammenhang allein ableiten?","scenario":"Eine Schlagzeile lautet: „Menschen, die Diät-Cola trinken, wiegen im Schnitt mehr.“ Ein Kommentar folgert: „Diät-Cola macht dick.“","options":["Dass es für jeden Einzelnen gilt, denn was im Gruppendurchschnitt zutrifft, trifft auch auf jedes Mitglied zu.","Dass die Trinkmenge das Gewicht bestimmt, denn wer mehr Diät-Cola trinkt, wiegt auch entsprechend mehr.","Dass die Richtung offen bleibt: Es kann auch umgekehrt sein, denn wer abnehmen will, greift eher zur Diät-Cola.","Dass es sich überall zeigt, denn ein Zusammenhang aus einer Erhebung gilt genauso in anderen Bevölkerungen."],"correctIndex":2,"explanation":"Eine Korrelation zwischen Diät-Cola-Konsum und Körpergewicht lässt zunächst offen, in welche Richtung der Zusammenhang läuft. Es ist ebenso gut möglich, dass Menschen, die mit ihrem Gewicht kämpfen und abnehmen wollen, häufiger zur Diät-Cola greifen: Dann verursacht das Gewicht den Konsum und nicht umgekehrt. Eine bloße Korrelation, auch aus vielen Beobachtungen, belegt noch keine Ursache; die Richtung bleibt offen. Die Sachfrage selbst ist offen: In kurzen Versuchen senkten Süßstoffe das Gewicht leicht, aber nur gegenüber Zucker, wohl zumindest teils über weniger Kalorien. In Beobachtungsstudien ging mehr Süßstoff mit höherem BMI einher, umgekehrte Kausalität gilt der WHO aber nicht als alleinige Erklärung, und ihre bedingte Empfehlung gegen Süßstoffe zur Gewichtskontrolle stützt sich auf Evidenz geringer Sicherheit. Für die Frage zählt: Die Schlagzeile allein verrät nicht, was Ursache und was Wirkung ist. Aus einem Gruppendurchschnitt folgt nichts für jede einzelne Person. Von Trinkmengen ist in der Schlagzeile nicht die Rede, eine Dosiswirkung lässt sich daraus also nicht ablesen. Und ein Zusammenhang aus einer Erhebung muss sich in anderen Bevölkerungen nicht wiederholen.","coreRule":"⚡ Eine Korrelation zeigt keine Richtung: Frag auch, ob B der Grund für A sein kann.","beleg":"Werkstück A.5 (Kontext & Tiefe: Umgekehrte Kausalität); Fn. ga-suessstoff (WHO 2023, S. viii–xi und 14)","status":"entwurf","kurz":"Aus der Schlagzeile lässt sich nur ein Zusammenhang ablesen, nicht seine Richtung. Der Kommentar liest eine Ursache hinein, doch es kann auch umgekehrt sein: Wer abnehmen will, greift eher zur Diät-Cola.","prueffrage":"Wurden dieselben Menschen nur einmal gewogen oder schon vor und nach dem Umstieg auf Diät-Cola?","rueckmeldung":[{"option":0,"text":"Die Schlagzeile beschreibt einen Durchschnitt über viele Menschen. Daraus folgt nicht, dass es bei jeder einzelnen Person so ist; manche Trinker wiegen wenig, manche Nichttrinker viel."},{"option":1,"text":"Von Trinkmengen ist in der Schlagzeile gar keine Rede; sie vergleicht nur Trinker mit anderen. Eine Dosiswirkung lässt sich daraus nicht ablesen, und „bestimmt“ unterstellt zudem schon eine Ursache, die offen ist."},{"option":3,"text":"Eine einzelne Erhebung zeigt das Muster in ihrer eigenen Stichprobe. Ob es in anderen Bevölkerungen genauso auftritt, muss eigens geprüft werden; es folgt nicht aus dem beobachteten Zusammenhang."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"WHO (2023): Use of non-sugar sweeteners: WHO guideline","oeffentlich":true,"url":"https://www.who.int/publications/i/item/9789240073616","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"b95df23665957860"}},{"id":"qx-a1-023","clusterId":"A","werkstueckRef":"A.5","stufe":3,"question":"Jemand sagt: „Dass Rauchen Lungenkrebs verursacht, ist nie in einem Experiment bewiesen worden, denn niemand kann Menschen per Los zum Rauchen verpflichten. Also ist es bis heute bloß eine Korrelation.“ Was ist an diesem Schluss fehlerhaft?","options":["Er übersieht, dass sich Kausalität auch ohne Experiment erhärten kann, wenn viele große, unabhängige Beobachtungsstudien über Jahrzehnte immer wieder dasselbe zeigen.","Er übersieht, dass seltene Ausnahmen, etwa Raucher, die nie erkranken, einen statistischen Zusammenhang nicht widerlegen, sondern nur einzelne Fälle betreffen.","Er verwechselt statistische Signifikanz mit praktischer Bedeutung, denn auch ein winziger Zusammenhang kann bei großer Stichprobe signifikant ausfallen.","Er verallgemeinert vorschnell von einzelnen Beobachtungen auf alle Menschen, obwohl sich aus Einzelfällen kein allgemeiner Zusammenhang ableiten lässt."],"correctIndex":0,"explanation":"Der Schluss behandelt „kein Losexperiment am Menschen“ als „kein Beweis“. Solche Experimente liefern zwar den saubersten Nachweis, sind aber nicht der einzige Weg. Beim Rauchen und Lungenkrebs kam der Beleg vor allem aus großen, jahrzehntelangen Beobachtungsstudien, deren Befunde sich immer wieder bestätigten; Tierversuche mit Tabakteer und der Nachweis krebserregender Stoffe im Rauch passten dazu. Dafür reicht allerdings keine einzelne Studie; erst die Breite und Beständigkeit der Befunde trägt. Der Satz „Korrelation ist nicht Kausalität“ verbietet also nicht, Ursachen zu erkennen, wenn die Evidenz so breit und beständig ist. Ausnahmen widerlegen einen statistischen Zusammenhang nicht, aber darum geht es dem Sprecher nicht. Er verwechselt auch nichts mit praktischer Bedeutung, denn er bestreitet die Ursache, nicht die Größe des Effekts. Und er verallgemeinert nicht von Einzelfällen, sondern lässt nur einen einzigen Beweistyp gelten.","coreRule":"⚡ Auch ohne Experiment kann sich Kausalität belegen lassen: durch große, jahrzehntelange Beobachtungsstudien, deren Befunde sich immer wieder bestätigen.","beleg":"Werkstück A.5 (Kontext & Tiefe: A verursacht B); Werkstück A.2 (Ebene 3: Die Gefahr der „Störfaktoren“)","status":"entwurf","scenario":"","kurz":"Kein Losexperiment am Menschen heißt nicht „kein Beweis“: Wenn viele große, unabhängige Beobachtungsstudien über Jahrzehnte immer dasselbe zeigen, kann das eine Ursache erhärten. Der Fehler liegt darin, nur einen einzigen Beweistyp gelten zu lassen.","prueffrage":"Welche Arten von Belegen außer einem Losexperiment lässt der Sprecher überhaupt gelten?","rueckmeldung":[{"option":1,"text":"Dass seltene Ausnahmen einen statistischen Zusammenhang nicht widerlegen, stimmt. Der Sprecher führt aber gar keine Ausnahmen an. Sein Schluss hängt daran, dass er nur ein Experiment als Beweis gelten lässt."},{"option":2,"text":"Auch winzige Effekte können bei großen Stichproben signifikant ausfallen, das ist richtig. Der Sprecher bestreitet aber die Ursache, nicht die Größe des Effekts. Von Bedeutung ist hier also nicht das Maß, sondern der Beweistyp."},{"option":3,"text":"Das wäre ein Fehler, wenn jemand aus wenigen Fällen auf alle schlösse. Der Sprecher tut das aber nicht: Er erkennt nur einen Beweistyp an. Und viele übereinstimmende Beobachtungen tragen durchaus allgemeine Schlüsse."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Parascandola, M.; Weed, D. L.; Dasgupta, A. (2006): Two Surgeon General's reports on smoking and cancer: a historical investigation of the practice of causal inference. Emerging Themes in Epidemiology 3:1","oeffentlich":true,"doi":"10.1186/1742-7622-3-1","abruf":"2026-10-12"},{"typ":"doi","kurz":"Doll, R.; Peto, R.; Boreham, J.; Sutherland, I. (2004): Mortality in relation to smoking: 50 years' observations on male British doctors. BMJ 328, 1519","oeffentlich":true,"doi":"10.1136/bmj.38142.554479.AE","abruf":"2026-10-12"},{"typ":"doi","kurz":"Doll, R.; Hill, A. B. (1950): Smoking and carcinoma of the lung; preliminary report. BMJ 2(4682), 739–748","oeffentlich":true,"doi":"10.1136/bmj.2.4682.739","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"e3031bf4c37ddeb1"}},{"id":"qx-a1-024","clusterId":"A","werkstueckRef":"A.5","stufe":4,"question":"Wie beurteilst du diesen Schluss?","scenario":"Eltern berichten: Kurz nach der Impfung ihres Kindes seien erste Anzeichen von Autismus bemerkt worden. Sie schließen daraus, die Impfung sei die Ursache.","options":["Er ist ein Post-hoc-Fehlschluss, denn erste Anzeichen treten oft genau in dem Alter auf, in dem auch geimpft wird, und große Studien fanden keinen ursächlichen Zusammenhang.","Er ist ein Autoritätsargument, denn die Eltern stützen sich allein auf das Ansehen einer Fachperson, statt zu prüfen, ob ihre Aussage durch Belege gedeckt ist.","Er ist ein Fall von Regression zur Mitte, denn ein auffällig schlechter Messwert fällt bei der nächsten Messung von selbst wieder besser aus, ohne dass etwas dazwischenkam.","Er ist ein Ad-hominem-Argument, denn die Eltern widerlegen keine Aussage, sondern greifen die Person oder Firma an, die den Impfstoff hergestellt hat, um dessen Sicherheit zu bestreiten."],"correctIndex":0,"explanation":"Das ist der klassische Post-hoc-Fehlschluss („danach, also deswegen“). Das zeitliche Zusammentreffen erklärt sich dadurch, dass erste Anzeichen von Autismus oft genau in dem Alter auftreten, in dem auch geimpft wird. Es ist eine zeitliche Korrelation, kein Beleg für Kausalität. Einen ursächlichen Zusammenhang haben große Studien immer wieder gesucht und nicht gefunden: In einer dänischen Studie mit 657.461 Kindern lag das Hazard Ratio für Autismus nach der Masern-Mumps-Röteln-Impfung bei 0,93; die Studie fand kein erhöhtes Autismusrisiko. Der Fehlschluss liegt in der Ableitung einer Ursache aus der zeitlichen Abfolge. Die anderen Denkfehler gibt es, sie passen aber nicht: Die Eltern berufen sich auf keine Fachperson, sondern auf ihre eigene Beobachtung. Es wurde kein auffälliger Messwert erhoben, der später zur Mitte zurückkehren könnte. Und niemand greift eine Person oder Firma an, es wird lediglich aus einer zeitlichen Abfolge auf eine Ursache geschlossen.","coreRule":"⚡ „Danach“ heißt nicht „deswegen“. Prüfe, ob der Zeitpunkt ohnehin zusammenfällt, und frag nach Vergleichen mit vielen Fällen.","beleg":"Werkstück A.5 (Anwendung & Relevanz: Bei der Anti-Impf-Bewegung); Fn. ga-hviid (Hviid u. a. 2019, Annals of Internal Medicine 170(8), S. 513–520)","status":"entwurf","kurz":"Dass erste Anzeichen nach der Impfung auffielen, zeigt nur eine zeitliche Abfolge. Sie fällt in ein Alter, in dem beides ohnehin häufig zusammentrifft, und große Studien fanden keinen ursächlichen Zusammenhang.","prueffrage":"Wie viele Kinder bekommen dieselbe Impfung, ohne dass danach irgendetwas auffällt?","rueckmeldung":[{"option":1,"text":"Autoritätsargumente gibt es, und sie klingen oft überzeugend. Die Eltern berufen sich hier aber auf keine Fachperson, sondern auf das, was sie selbst beobachtet haben. Der Schluss hängt an der Abfolge, nicht an einer Autorität."},{"option":2,"text":"Regression zur Mitte betrifft auffällige Messwerte, die bei einer erneuten Messung von selbst zurückgehen. Hier wurde aber nichts gemessen und nichts wiederholt. Es geht allein darum, ob aus „danach“ ein „deswegen“ folgt."},{"option":3,"text":"Ein Angriff auf die Person oder Firma hinter einer Aussage wäre ein Ad-hominem-Argument. Die Eltern greifen aber niemanden an. Sie schließen aus dem zeitlichen Zusammentreffen auf eine Ursache, und genau dort liegt das Problem."}],"familie":"was-waere-ohne","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Hviid, A.; Hansen, J. V.; Frisch, M.; Melbye, M. (2019): Measles, Mumps, Rubella Vaccination and Autism: A Nationwide Cohort Study. Annals of Internal Medicine 170(8), 513–520 (Abstract)","oeffentlich":true,"doi":"10.7326/M18-2101","url":"https://pubmed.ncbi.nlm.nih.gov/30831578/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"643556e693c4399b"}},{"id":"qx-a1-025","clusterId":"A","werkstueckRef":"A.6","stufe":1,"question":"Was erklärt diese Entwicklung am besten?","options":["Die Autofahrer sind auf andere Strecken ausgewichen, und deshalb hat sich dieselbe Zahl an Fahrten nur neu verteilt, ohne dass es mehr wurden.","Der Stadtrat hat die Bauzeit zu optimistisch eingeschätzt (Planungsfehlschluss), und deshalb kam die Spur zu spät, um den Stau zu verhindern.","Die neue Fahrspur hat das Autofahren attraktiver gemacht, und deshalb sind mehr Menschen gefahren, bis der Stau in der Innenstadt wieder da war.","Der erneute Stau ist ein statistischer Ausreißer, und deshalb hat er mit der Fahrspur nichts zu tun, denn die Staulage schwankt jährlich."],"correctIndex":2,"explanation":"Die Maßnahme setzt vermutlich eine verstärkende Schleife in Gang: Mehr Kapazität macht das Autofahren attraktiver, mehr Menschen fahren, und dadurch steigt die Auslastung, bis der Gewinn aufgezehrt ist. Der Plan betrachtete nur die direkte Kette „mehr Platz, weniger Stau“ und übersah die Rückkopplung samt Zeitverzögerung. Wer so einen Eingriff plant, fragt deshalb nicht nur nach der direkten Folge, sondern auch nach den Folgen der Folgen. Andere Gedanken klingen vernünftig, passen aber nicht: Dass die Fahrer nur ausgewichen wären, widerspricht dem gestiegenen Verkehrsaufkommen insgesamt. Der Planungsfehlschluss betrifft die Einschätzung von Bauzeit und Kosten, nicht das Verhalten der Fahrer, und im Szenario ist die Spur längst gebaut. Und ein bloßer Ausreißer erklärt nicht, warum das Aufkommen insgesamt wächst.","coreRule":"⚡ Wer nur die direkte Ursache-Wirkungs-Kette betrachtet, übersieht Rückkopplungen und Verzögerungen. Frage: Was sind die Konsequenzen der Konsequenzen?","quote":"Lineares Denken sieht einen fallenden Dominostein. Systemdenken sieht ein Spinnennetz: Zupft man an einer Stelle, vibriert das ganze Netz.","quoteLabel":"Zum Weiterdenken:","beleg":"Werkstück A.6 (Kernidee; Kontext & Tiefe; Red Flags)","status":"entwurf","scenario":"Eine Stadt will die Staus in der Innenstadt bekämpfen und baut eine zusätzliche Fahrspur. Der Stadtrat verlässt sich dabei auf eine einfache Rechnung: Mehr Fahrspuren bedeuten mehr Platz, mehr Platz bedeutet weniger Stau. Zwei Jahre später steht die Innenstadt wieder im Stau, und das Verkehrsaufkommen insgesamt ist gestiegen.","kurz":"Mehr Fahrspuren machen das Autofahren attraktiver, also fahren mehr Menschen, bis der Stau zurück ist. Der Plan sah nur die direkte Kette „mehr Platz, weniger Stau“ und übersah die Rückkopplung, die den Gewinn nach einiger Zeit aufzehrt.","prueffrage":"Wie verlief der Stau in den zwei Jahren nach dem Ausbau: Kam er sofort zurück oder erst nach und nach?","rueckmeldung":[{"option":0,"text":"Dass sich Fahrten verlagern, kommt vor, und deshalb klingt das plausibel. Dann bliebe die Gesamtzahl der Fahrten aber gleich, hier ist das Verkehrsaufkommen insgesamt jedoch gestiegen."},{"option":1,"text":"Zu optimistische Bauzeiten sind ein bekanntes Muster. Im Szenario ist die Spur aber längst gebaut, und das Problem liegt im Verhalten der Fahrer, nicht in der Planung der Bauzeit."},{"option":3,"text":"Die Staulage schwankt tatsächlich von Jahr zu Jahr. Ein einzelner Ausreißer erklärt aber nicht, warum das Verkehrsaufkommen insgesamt gewachsen ist, und das spricht für eine dauerhafte Ursache."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Duranton, G.; Turner, M. A. (2009): The Fundamental Law of Road Congestion: Evidence from US Cities. NBER Working Paper 15376 (später American Economic Review 2011)","oeffentlich":true,"url":"https://www.nber.org/papers/w15376","abruf":"2026-10-12"},{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System. Donella Meadows Project","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"15332e18e09b7189"}},{"id":"qx-a1-026","clusterId":"A","werkstueckRef":"A.6","stufe":2,"question":"Welche Erklärung beschreibt am besten, was hier geschieht und warum die Hilfe nach hinten losgeht?","scenario":"Eine Hilfsorganisation verschenkt kostenlos Güter in einem armen Land, um die Armut zu lindern. In den ersten Monaten sieht das nach einem Erfolg aus. Nach einigen Jahren geht es der lokalen Wirtschaft jedoch schlechter als zuvor, und die Armut ist gewachsen. Ein Mitarbeiter schlägt vor: „Wir müssen einfach mehr verteilen.“","options":["Abnehmende Erträge: Jede weitere Einheit Hilfe nützt etwas weniger als die vorige, sodass der Nutzen bei wachsender Menge gegen null geht und die Lage bestenfalls stagniert.","Ausgleichende Rückkopplung: Die Hilfe senkt die Armut, mit der Armut sinkt der Hilfsbedarf, und die Lage nähert sich von selbst einem Gleichgewicht, in dem keine Hilfe mehr nötig ist.","Verstärkende Rückkopplung: Die kostenlosen Güter unterbieten lokale Anbieter, deren Einkommen sinkt, die Armut wächst und mit ihr der Hilfsbedarf; die Hilfe verstärkt das Problem, das sie lösen soll.","Zeitverzögerung: Die Wirkung der Hilfe zeigt sich erst nach Jahren, die jetzige Verschlechterung ist nur die Talsohle vor der Erholung und geht mit weiterer Hilfe vorüber."],"correctIndex":2,"explanation":"Wer ein Symptom (Armut) direkt bekämpft, ohne das System zu betrachten, übersieht Rückwirkungen: Kostenlose Güter unterbieten die lokale Wirtschaft, sie bricht zusammen, und langfristig wächst die Armut weiter. Das ist eine verstärkende Rückkopplungsschleife. Da die Hilfe selbst Teil dieser Schleife ist, ist mehr vom Gleichen kaum eine Lösung. Ein Systemdenker erwartet solche unbeabsichtigten Nebenwirkungen und fragt nach den Konsequenzen der Konsequenzen. Die anderen Begriffe sind für sich sinnvolle Werkzeuge, passen aber nicht auf diesen Fall: Abnehmende Erträge beschreiben einen schwächer werdenden Nutzen, hier aber wird die Lage schlechter als vor der Hilfe. Ein ausgleichender Kreislauf würde die Armut senken, sie wächst jedoch. Und eine Zeitverzögerung erklärt nicht, warum es der Wirtschaft schlechter geht als zuvor; das spricht dafür, dass die Hilfe selbst die Rückkopplung auslöst.","coreRule":"⚡ Wer nur ein Symptom behandelt, setzt oft eine Schleife in Gang, die das Problem verschärft.","beleg":"Werkstück A.6 (Anwendung & Relevanz: Bei sozialen und politischen Problemen)","status":"entwurf","kurz":"Die kostenlosen Güter verdrängen lokale Anbieter, deren Einkommen sinkt, und mit der Armut wächst der Hilfsbedarf. Die Hilfe speist so das Problem, das sie lösen will; nur auf das Symptom zu schauen, übersieht diese Rückwirkung.","prueffrage":"Welche Kennzahlen der lokalen Wirtschaft haben sich nach Beginn der Verteilung zuerst verschlechtert, und in welchen Branchen?","rueckmeldung":[{"option":0,"text":"Dass zusätzliche Hilfe oft weniger bringt, gibt es wirklich. Hier wird die Lage aber schlechter als vor der Hilfe, nicht nur flacher; der Begriff erklärt keinen Schaden, nur einen schwächeren Nutzen."},{"option":1,"text":"Ein Kreislauf, der sich von selbst einpendelt, ergäbe sinkende Armut und weniger Bedarf. Das Szenario zeigt das Gegenteil: Die Armut wächst. Der beschriebene Mechanismus passt also nicht zu dem, was tatsächlich geschieht."},{"option":3,"text":"Verzögerte Wirkungen sind bei Hilfsprogrammen häufig und die ersten Monate sahen gut aus. Eine Verzögerung erklärt aber nicht, warum es der Wirtschaft schlechter geht als zuvor, und eine kommende Erholung ist reine Annahme."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Frazer, G. (2008): Used-Clothing Donations and Apparel Production in Africa. Economic Journal 118(532), 1764–1784 (Abstract, IDEAS/RePEc)","oeffentlich":true,"url":"https://ideas.repec.org/a/ecj/econjl/v118y2008i532p1764-1784.html","abruf":"2026-10-12"},{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System. Donella Meadows Project","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"}],"thema":"Geld und Zahlen","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"f83ee58765183fc1"}},{"id":"qx-a1-027","clusterId":"A","werkstueckRef":"A.6","stufe":3,"question":"Was ist an dieser Schlussfolgerung fehlerhaft?","scenario":"In einer Sitzung geht es um ein Problem, an dem viele Faktoren beteiligt sind. Jemand sagt: „Das ist ein komplexes System, da können wir ohnehin nichts bewirken – also lassen wir es.“","options":["Es ist ein Fehlschluss von „komplex“ auf „sinnlos“: Man kann Teile einzeln untersuchen, prüfen, wie sie ins Ganze passen, und so überlegt eingreifen.","Es ist ein Zirkelschluss: Der Sprecher setzt voraus, was er erst zeigen will, nämlich dass das Problem so komplex ist, dass Eingriffe nichts bewirken können.","Es ist ein Strohmann: Der Sprecher greift eine Position an, die niemand vertreten hat, nämlich dass sich komplexe Probleme mit einem einzigen Eingriff lösen ließen.","Es ist ein Autoritätsargument: Der Sprecher beruft sich allein auf die Meinung einer Fachperson, statt die Sache selbst zu prüfen und zu begründen."],"correctIndex":0,"explanation":"Die Aussage schließt von „komplex“ auf „nichts zu bewirken“ – das ist ein Fehlschluss. Komplexität heißt, dass Wirkungen verzögert, indirekt und mit Rückkopplungen auftreten und dass es unbeabsichtigte Nebenwirkungen geben kann. Das ist ein Grund, sorgfältiger vorzugehen, kein Grund, nichts zu tun. Sinnvoll ist ein Wechsel der Perspektive: Ein einzelnes Teil lässt sich isoliert analysieren (wie ein Zahnrad), und danach fragt man, wie es mit dem Ganzen zusammenhängt (wie das Zahnrad im Uhrwerk). So entstehen überlegte Eingriffe, die sowohl das einzelne Teil als auch sein Zusammenspiel im Ganzen berücksichtigen. Wer Komplexität als Ausrede für Untätigkeit benutzt, macht das Denkwerkzeug selbst zum Hindernis. Die anderen Fehlschlüsse gibt es, sie passen aber nicht: Der Sprecher begründet seinen Schluss mit der Komplexität und setzt den Schluss nicht schon voraus. Er greift auch keine Position an, die niemand vertreten hat. Und er beruft sich auf keine Autorität.","coreRule":"⚡ Komplexität ist ein Grund für sorgfältiges Handeln, nicht für Untätigkeit – wechsle zwischen Teil und Ganzem.","beleg":"Werkstück A.6 (Der Kipppunkt: Systemdenken als Ausrede für Untätigkeit; Wechsel zwischen reduktionistischer Analyse und systemischer Synthese)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Aus „komplex“ folgt nicht „sinnlos“. Komplexität heißt verzögerte, indirekte Wirkungen und mögliche Nebenwirkungen, also ein Grund für sorgfältigeres Vorgehen. Teile lassen sich einzeln prüfen und dann im Zusammenspiel betrachten.","prueffrage":"Gab es bei ähnlich verzweigten Problemen schon Eingriffe, die etwas bewirkt haben, und woran ließ sich das ablesen?","rueckmeldung":[{"option":1,"text":"Ein Zirkelschluss liegt nicht vor, denn der Sprecher nennt mit der Komplexität einen eigenen Grund und setzt seinen Schluss nicht schon voraus. Der Fehler liegt im Sprung von „komplex“ auf „wirkungslos“."},{"option":2,"text":"Dass sich komplexe Probleme kaum mit einem einzigen Eingriff lösen lassen, stimmt. Aber niemand hat hier etwas Gegenteiliges behauptet, das der Sprecher verzerrt hätte. Er zieht nur selbst einen zu weiten Schluss."},{"option":3,"text":"Eine Autorität kommt in der Aussage gar nicht vor. Der Sprecher beruft sich auf die Beschaffenheit des Problems, nicht auf eine Fachperson. Geprüft werden muss deshalb, ob seine Begründung seinen Schluss trägt."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Meadows, D.: Dancing With Systems. Donella Meadows Project","oeffentlich":true,"url":"https://donellameadows.org/archives/dancing-with-systems/","abruf":"2026-10-12"},{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System. Donella Meadows Project","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"8782267ac56a9ce2"}},{"id":"qx-a1-028","clusterId":"A","werkstueckRef":"A.6","stufe":4,"question":"Wie bewertest du diese Behauptung am sinnvollsten?","scenario":"Ein viral geteiltes Video behauptet: „Als in Yellowstone wieder Wölfe angesiedelt wurden, haben sie sogar den Lauf der Flüsse verändert.“ Du weißt: Es gab dort zeitgleich auch Jagd, Dürrejahre, Bären und Pumas, und in der Umgebung wurden Biber ausgewildert.","options":["Sie ist eine Umkehrung von Ursache und Wirkung: Nicht die Wölfe haben den Park verändert, sondern der veränderte Park hat die Wölfe angelockt und zur Rückkehr bewogen.","Sie ist eine monokausale Verkürzung: Eine Wirkkette über Hirsche und Pflanzen ist plausibel, ihre Stärke ist aber umstritten, und der veränderte Flusslauf gilt als überzeichnet.","Sie ist ein Fall von Überlebensverzerrung: Betrachtet wurde nur der Park, in dem die Wiederansiedlung gelang, während gescheiterte Wiederansiedlungen anderswo unbeachtet blieben.","Sie ist ein Autoritätsargument: Das Video stützt sich allein auf das Ansehen bekannter Fachleute, statt die Belege für die Wirkkette offenzulegen und prüfbar zu machen."],"correctIndex":1,"explanation":"In einem System wirkt selten nur eine einzige Ursache. Die Behauptung nimmt eine plausible Wirkkette (Wölfe, weniger Hirsche, erholte Weiden, mehr Biber) und kürzt sie zur Ein-Ursache-Story, bis hin zum veränderten Flusslauf. Dagegen sprechen mehrere Mitverursacher: Jagd, Dürrejahre, Bären und Pumas hatten ebenfalls ihren Anteil am Rückgang der Hirsche, die Weiden erholten sich nur stellenweise, und Biber profitierten auch von Auswilderungen in der Umgebung. Dass Wölfe über Hirsche und Pflanzen wirken können, ist plausibel; unter Ökologen ist aber umstritten, wie stark diese Kaskade tatsächlich ist (Ripple/Beschta 2012 für eine starke, Brice u. a. 2022 für eine überschätzte Kaskade). Die Flusslauf-Aussage stammt aus einer populären Zuspitzung und gilt als deutlich überzeichnet. Die anderen Denkfehler gibt es, sie passen aber nicht: Die Wölfe wurden von Menschen wieder angesiedelt, der Park hat sie also nicht angelockt. Es wurde kein erfolgreicher Einzelfall unter vielen herausgepickt, denn es geht um die Mitursachen im selben Park. Und das Video behauptet nur, ohne sich auf Fachleute zu berufen.","coreRule":"⚡ Auch die schönste Kaskade hat mehrere Ursachen: Prüfe, wie stark der Einzelfaktor wirklich wirkt und was sonst noch mitspielt.","beleg":"Werkstück A.6 (Der Wolf und der Fluss); Fn. ga-yellowstone (Ripple/Beschta 2012, Biological Conservation 145(1), S. 205–213; Brice u. a. 2022, Ecology Letters 25(1), S. 177–188)","status":"entwurf","kurz":"Eine plausible Wirkkette über Hirsche und Pflanzen wird zur Ein-Ursache-Story verkürzt. Jagd, Dürre, Bären, Pumas und Biber-Auswilderungen wirkten mit, die Stärke der Wolfs-Kaskade ist umstritten, und der Flusslauf gilt als überzeichnet.","prueffrage":"Was geschah im selben Zeitraum in Yellowstone und seiner Umgebung noch, das dieselben Veränderungen erklären könnte?","rueckmeldung":[{"option":0,"text":"Bei Zusammenhängen lohnt es sich, die Richtung zu prüfen. Hier passt sie aber nicht: Die Wölfe wurden von Menschen wieder angesiedelt, der Park hat sie nicht angelockt. Der Mangel liegt darin, dass ein ganzes Geflecht von Ursachen zu einer einzigen verkürzt wird."},{"option":2,"text":"Ein herausgepickter Einzelfall kann tatsächlich täuschen. Hier geht es aber nicht um gescheiterte Wiederansiedlungen anderswo, sondern um das, was im selben Park gleichzeitig geschah: Jagd, Dürre, Bären, Pumas und Biber wirkten ebenfalls mit."},{"option":3,"text":"Das Video legt zwar keine Belege offen, beruft sich aber auch nicht auf Fachleute, es behauptet nur. Ein Autoritätsargument liegt daher nicht vor. Das eigentliche Problem ist, dass eine plausible Wirkkette zur Ein-Ursache-Geschichte verkürzt wird."}],"familie":"monokausal-erkennen","fertigkeit":"F2","quellen":[{"typ":"doi","kurz":"Brice, E. M.; Larsen, E. J.; MacNulty, D. R. (2022): Sampling bias exaggerates a textbook example of a trophic cascade. Ecology Letters 25(1), 177–188","oeffentlich":true,"doi":"10.1111/ele.13915","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Ripple, W. J.; Beschta, R. L. (2012): Trophic cascades in Yellowstone: The first 15 years after wolf reintroduction. Biological Conservation 145(1), 205–213","oeffentlich":false,"doi":"10.1016/j.biocon.2011.11.005"},{"typ":"literatur","kurz":"Smith, D. W.; Tyers, D. B. (2012): The History and Current Status and Distribution of Beavers in Yellowstone National Park. Northwest Science 86(4)","oeffentlich":false,"doi":"10.3955/046.086.0404"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"33eb9977993541e1"}},{"id":"qx-a1-029","clusterId":"A","werkstueckRef":"A.7","stufe":1,"question":"Was wäre jetzt die vernünftigste Reaktion deines Kollegen?","scenario":"Ein Kollege sagt in der Besprechung: „Es ist zu 100 % sicher, dass das neue Produkt floppt.“ Du fragst ihn, wie sicher er sich auf einer Skala von 1 bis 100 wirklich ist. Er antwortet nach kurzem Zögern: „Na ja, vielleicht 70.“ Kurz darauf kommen erste Rückmeldungen aus einem Testmarkt: Die Kundschaft reagiert deutlich besser als erwartet.","options":["Seine Einschätzung nach unten anpassen, etwa auf 50 %, weil die neuen Rückmeldungen gegen einen Flop sprechen, ein einzelner Testmarkt aber noch nicht reicht, sie ganz umzukehren.","Die Einschätzungen mehrerer Kolleginnen und Kollegen einholen und deren Mittelwert übernehmen, weil der Durchschnitt einer Gruppe genauer ist als jedes Einzelurteil.","Prüfen, wie oft frühere Urteile mit 70 % Sicherheit zutrafen, und seine Einschätzung bis dahin offenlassen, weil sich erst dann sagen lässt, wie viel sie wert war.","Bei 70 % bleiben, weil ein einzelner Testmarkt nicht repräsentativ sein muss und die Rückmeldungen deshalb an seinem Urteil nichts ändern dürfen."],"correctIndex":0,"explanation":"Eine Einschätzung ist ein Vertrauensgrad, der auf der Basis neuer Informationen angepasst werden sollte. Die Rückmeldungen sprechen gegen den Flop, also darf der Wert sinken. Dabei kippt er nicht in ein neues Extrem: Wer wegen eines einzigen Hinweises von „sicher Flop“ auf „sicherer Erfolg“ springt, ersetzt die eine Gewissheit durch die nächste. Wie hoch der neue Wert genau liegt, ist eine Einschätzungsfrage; entscheidend ist, dass er sich mit den neuen Informationen bewegt. Handeln bei Unsicherheit gelingt gerade dadurch, dass man ausdrückt, wie sicher man ist, und bereit bleibt, die Zahl zu korrigieren. Andere Gedanken sind für sich sinnvoll, passen aber nicht: Das Mittel mehrerer Schätzungen kann helfen, bezieht aber die neue Information aus dem Testmarkt nicht ein. Die Treffsicherheit früherer Urteile zu prüfen ist ein gutes Werkzeug, doch es gibt keinen Grund, die Einschätzung deshalb offenzulassen. Und dass ein Testmarkt nicht alles zeigt, rechtfertigt eine kleinere, aber keine ausbleibende Anpassung.","coreRule":"⚡ Sag nicht „sicher“ oder „unmöglich“, sondern wie sicher – und passe die Zahl an, wenn neue Hinweise kommen.","beleg":"Werkstück A.7 (Kernidee; Red Flags)","status":"entwurf","kurz":"Eine Einschätzung ist ein Vertrauensgrad und darf sich mit neuen Hinweisen bewegen: Die guten Rückmeldungen lassen den Wert sinken. Der Fehler wäre, entweder stur festzuhalten oder wegen eines Testmarkts ins andere Extrem zu springen.","prueffrage":"Wie gut haben Testmärkte bei früheren Produkten vorhergesagt, ob diese später floppten?","rueckmeldung":[{"option":1,"text":"Der Durchschnitt mehrerer Urteile kann tatsächlich genauer sein als ein einzelnes. Er berücksichtigt aber nicht, was gerade aus dem Testmarkt hereingekommen ist, und beantwortet deshalb nicht, wie der Kollege auf diese neue Information reagieren sollte."},{"option":2,"text":"Früheres Urteilen auf Treffsicherheit zu prüfen ist ein gutes Werkzeug. Die neuen Rückmeldungen liegen aber schon vor, deshalb gibt es keinen Grund, die Einschätzung bis dahin offenzulassen, statt sie jetzt anzupassen."},{"option":3,"text":"Ein einzelner Testmarkt muss nicht repräsentativ sein, das stimmt. Das spricht aber nur für eine kleinere Anpassung, nicht für gar keine: Wer trotz neuer Hinweise bei 70 bleibt, bewegt seine Zahl nicht mit der Datenlage."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Joyce, J.: Bayes' Theorem. Stanford Encyclopedia of Philosophy (Erstveröffentlichung 2003)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bayes-theorem/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Atanasov, P.; Witkowski, J.; Ungar, L.; Mellers, B.; Tetlock, P. (2020): Small steps to accuracy: Incremental belief updaters are better forecasters. Organizational Behavior and Human Decision Processes 160, 19–35","oeffentlich":true,"doi":"10.1016/j.obhdp.2020.02.001","url":"https://faculty.wharton.upenn.edu/wp-content/uploads/2022/03/1-s2.0-S0749597819300949-main.pdf","seite":"S. 19 (Abstract)","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"a3048c64042cfdd4"}},{"id":"qx-a1-030","clusterId":"A","werkstueckRef":"A.7","stufe":2,"question":"Wie solltest du dein Vertrauen in die Meldung ansetzen und anpassen?","scenario":"Eine Freundin schickt dir eine schockierende Schlagzeile von einer Seite, die in der Vergangenheit überwiegend Falsches veröffentlicht hat. Sie schreibt: „Das ist bestimmt wahr, so etwas würde niemand erfinden.“ Weitere Belege nennt sie nicht.","options":["Zunächst hoch, weil eine so folgenschwere Meldung ernst genommen werden muss, falls sie stimmt; im Zweifel gebietet Vorsicht, vom Schlimmsten auszugehen.","Zunächst mittel, weil es ein Fehlschluss wäre, eine Meldung nach ihrer Herkunft zu beurteilen; allein der Inhalt zählt, und der liefert noch keinen Beleg.","Zunächst niedrig, weil Meldungen dieser Quelle in der Vergangenheit nur selten zutrafen; erst weitere, bessere Belege würden dein Vertrauen anheben.","Zunächst hoch, weil deine Freundin die Meldung als wahr weitergibt; das Urteil einer vertrauten Person zählt mehr als die Trefferquote einer fremden Seite."],"correctIndex":2,"explanation":"Der sinnvolle Ausgangspunkt ist die Basisrate: Wie oft stimmen Meldungen dieser Art von dieser Quelle? Ist die Rate gering, ist auch das anfängliche Vertrauen gering, wie dramatisch die Schlagzeile auch klingt, denn dass sie schockiert, macht sie nur auffälliger, nicht wahrscheinlicher. Ein mittleres Vertrauen wäre nur angemessen, wenn Meldungen der Quelle etwa zur Hälfte stimmten. Neue Belege verschieben den Ausgangswert, ersetzen ihn aber nicht: Trifft eine Krankheit nur einen von 10 000 Menschen, hebt selbst ein positives Ergebnis eines Tests, der in 99 % der Fälle richtig liegt, die Wahrscheinlichkeit nur auf knapp 1 %. Die anderen Gedanken klingen vernünftig, passen aber nicht: Eine Meldung allein wegen ihrer Herkunft abzulehnen wäre ein Fehlschluss, hier dient die Trefferquote jedoch nur als Ausgangswert, der durch Belege veränderbar bleibt. Vorsicht beim Handeln heißt nicht, eine Meldung für wahrscheinlich zu halten. Und deine Freundin nennt keinen Beleg, sodass ihr Urteil die Trefferquote der Quelle nicht aufwiegt.","coreRule":"⚡ Beginne mit der Basisrate der Quelle und lass nur bessere Belege dein Vertrauen heben.","beleg":"Werkstück A.7 (Anwendung & Relevanz: Bei Fake News; Das Anti-Denkmuster)","status":"entwurf","kurz":"Der Ausgangswert richtet sich danach, wie oft Meldungen dieser Quelle stimmen, und die Rate ist niedrig. Dass eine Schlagzeile schockiert, macht sie nur auffälliger, nicht wahrscheinlicher. Erst bessere Belege würden das Vertrauen anheben.","prueffrage":"Was wusstest du über diese Seite schon, bevor deine Freundin dir die Schlagzeile schickte?","rueckmeldung":[{"option":0,"text":"Bei folgenschweren Meldungen ist Aufmerksamkeit angebracht, und Vorsicht beim Handeln kann sinnvoll sein. Wie wahrscheinlich die Meldung ist, hängt davon aber nicht ab: Wie schlimm es wäre, sagt nichts darüber, ob es stimmt."},{"option":1,"text":"Daran stimmt, dass der Inhalt allein noch keinen Beleg liefert. Die Quelle wird hier aber nicht als Urteil herangezogen, sondern als Ausgangswert, und der kann durch Belege steigen. Mittleres Vertrauen passte nur bei etwa halber Trefferquote."},{"option":3,"text":"Auf Menschen, die man kennt, zu vertrauen ist oft vernünftig. Hier nennt die Freundin aber keinen Beleg, sie gibt nur ihr Gefühl weiter. Das wiegt eine Quelle, die überwiegend Falsches veröffentlicht hat, nicht auf."}],"familie":"basisrate-beachten","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Joyce, J.: Bayes' Theorem. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bayes-theorem/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Gigerenzer, G.; Gaissmaier, W.; Kurz-Milcke, E.; Schwartz, L. M.; Woloshin, S. (2007): Helping Doctors and Patients Make Sense of Health Statistics. Psychological Science in the Public Interest 8(2), 53–96","oeffentlich":true,"doi":"10.1111/j.1539-6053.2008.00033.x","url":"https://kops.uni-konstanz.de/entities/publication/1c820f2d-aeed-4bfd-b65b-0e3f86803750/full","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"9a3a5fe3ab63e279"}},{"id":"qx-a1-031","clusterId":"A","werkstueckRef":"A.7","stufe":3,"question":"Was ist an dieser Haltung des Teams ein Denkfehler?","scenario":"Euer Team soll bis Freitag entscheiden, ob es ein Angebot annimmt. Seit drei Wochen rechnet ihr Wahrscheinlichkeiten für jede denkbare Folge durch. Eine Kollegin sagt: „Wir entscheiden erst, wenn wir die Wahrscheinlichkeiten ganz genau kennen.“ Neue Informationen sind in absehbarer Zeit nicht zu erwarten.","options":["Das Team verwechselt Abwägen mit Entscheiden: Wer nie auf unvollständiger Grundlage handelt, bleibt handlungsunfähig, weil Entscheiden immer ein Handeln trotz Restunsicherheit ist.","Das Team betrachtet zu wenige Folgen: Wer nicht jede denkbare Folge durchrechnet, übersieht seltene, aber schwerwiegende Ereignisse und entscheidet deshalb falsch.","Das Team hat zu früh aufgehört, Daten zu sammeln: Mit mehr Informationen ließen sich die Wahrscheinlichkeiten bis Freitag noch genau bestimmen.","Das Team unterliegt dem Planungsfehlschluss: Es unterschätzt den Zeitaufwand für die Umsetzung des Angebots und plant deshalb zu knapp."],"correctIndex":0,"explanation":"Das Team rechnet seit Wochen und entscheidet nicht. Im Alltag müssen wir oft Entscheidungen auf der Grundlage unvollständiger Informationen treffen. Der Punkt ist nicht, niemals zu handeln, sondern sich des Unsicherheitsgrades bewusst zu sein. Wahrscheinlichkeiten machen Unsicherheit sichtbar, sie beseitigen sie nicht. Wer auf völlige Genauigkeit wartet, die gar nicht zu bekommen ist, verwechselt Abwägen mit Entscheiden. Andere Fehler gibt es zwar, sie passen aber nicht: Zu wenige Folgen betrachtet das Team nicht, es rechnet ja schon jede denkbare durch. Dass mit mehr Daten alles klarer würde, scheidet aus, weil neue Informationen nicht zu erwarten sind. Und mit dem Zeitaufwand der Umsetzung hat die Haltung nichts zu tun, denn es geht um die Entscheidung selbst.","coreRule":"⚡ Unsicherheit ist ein Grund, sie zu beziffern – nicht, auf die Entscheidung zu verzichten.","beleg":"Werkstück A.7 (Der Kipppunkt)","status":"entwurf","kurz":"Wahrscheinlichkeiten machen Unsicherheit sichtbar, beseitigen sie aber nicht. Wer auf völlige Genauigkeit wartet, die nicht zu bekommen ist, verwechselt Abwägen mit Entscheiden und bleibt handlungsunfähig, obwohl man oft trotz Restunsicherheit entscheiden muss.","prueffrage":"Was würde sich an den Zahlen ändern, wenn das Team noch eine weitere Woche rechnet?","rueckmeldung":[{"option":1,"text":"Seltene, schwere Ereignisse zu übersehen ist tatsächlich ein typischer Fehler. Hier passt er aber nicht: Das Team rechnet laut Szenario schon jede denkbare Folge durch, sein Problem ist das Nichtentscheiden, nicht fehlende Sorgfalt."},{"option":2,"text":"Mehr Daten verbessern Schätzungen oft, hier sind aber in absehbarer Zeit keine neuen Informationen zu erwarten. Das Team hat nicht zu früh aufgehört; es wartet auf eine Genauigkeit, die ihm gar nicht zur Verfügung steht."},{"option":3,"text":"Den Aufwand der Umsetzung zu unterschätzen ist ein bekannter Fehler, der Anlass für diese Antwort liegt aber woanders. Die Haltung des Teams betrifft die Entscheidung selbst, von Umsetzung und Zeitplanung ist im Szenario gar nicht die Rede."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Bounded Rationality (Erstveröffentlichung 2018, überarbeitet 2024)","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bounded-rationality/","abruf":"2026-10-12"},{"typ":"url","kurz":"Joyce, J.: Bayes' Theorem. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bayes-theorem/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"d54c518018c1e2a8"}},{"id":"qx-a1-032","clusterId":"A","werkstueckRef":"A.7","stufe":4,"question":"Welche Reaktion auf das Video ist am besten begründet?","scenario":"Nach einer Wahl kursiert ein Video, das einen Zählfehler in einem einzelnen Wahllokal zeigt. Jemand ruft: „Die Wahl wurde zu 100 % gestohlen!“ Eine Zuhörerin hält dagegen und will den Hinweis nach Wahrscheinlichkeiten einordnen.","options":["Sie schließt, dass Betrug wahrscheinlich ist, denn solche Zählfehler sind bei korrekten Wahlen selten, und was bei Ehrlichkeit selten ist, spricht für Betrug.","Sie fragt, wie wahrscheinlich Wahlbetrug vorher war und wie stark der Hinweis ist, denn ein einzelner Zählfehler hebt die Wahrscheinlichkeit nur minimal an.","Sie prüft nur, ob der Zählfehler zur Betrugsannahme passt, denn passt er dazu, stützt er sie, und ein Vergleich mit anderen Erklärungen ist nicht nötig.","Sie setzt Betrug und korrekte Zählung auf je 50 %, denn der Zählfehler lässt sich keiner der beiden Möglichkeiten eindeutig zuordnen und beide bleiben gleich möglich."],"correctIndex":1,"explanation":"Wer „zu 100 % gestohlen“ ruft, denkt in Gewissheiten. Besser ist die Frage, wie wahrscheinlich Wahlbetrug in diesem System von vornherein war und wie stark der neue Hinweis ist. Ein einzelner Zählfehler ist ein schwacher Hinweis, weil sich auch bei korrekten Wahlen gelegentlich jemand verzählt: Er passt zu beiden Erklärungen fast gleich gut, verschiebt die Wahrscheinlichkeit deshalb allenfalls minimal, und sie bleibt sehr gering. Wertlos ist er trotzdem nicht: Man sollte ihn einordnen, etwa prüfen, ob sich solche Fehler häufen oder alle in dieselbe Richtung weisen. Dass zwei Erklärungen denkbar sind, macht sie noch nicht gleich wahrscheinlich. Auch die anderen Überlegungen klingen sinnvoll, passen aber nicht: Dass ein Fehler bei korrekten Wahlen selten ist, macht Betrug nicht automatisch wahrscheinlich, weil der Fehler gelegentlich auch ohne Betrug vorkommt. Und es genügt nicht, dass der Hinweis zur Betrugsannahme passt, denn er passt ebenso zur harmlosen Erklärung.","coreRule":"⚡ Eine kleine Anomalie ist ein kleines Update, kein Urteil – gewichte Hinweise nach Stärke und Ausgangswahrscheinlichkeit.","beleg":"Werkstück A.7 (Anwendung & Relevanz: Bei Verschwörungsmythen; Red Flags)","status":"entwurf","kurz":"Wie sehr der Zählfehler den Verdacht stützt, hängt davon ab, wie wahrscheinlich Betrug vorher war und wie gut der Fehler zu Betrug im Vergleich zu bloßem Verzählen passt. Er passt zu beidem fast gleich gut, also verschiebt er wenig.","prueffrage":"Wie viele Wahllokale gab es insgesamt, und in wie vielen davon wurden Zählfehler gefunden?","rueckmeldung":[{"option":0,"text":"Dass solche Fehler bei korrekten Wahlen selten sind, stimmt. Selten heißt aber nicht unmöglich: Verzählen passiert gelegentlich auch ohne Betrug, der Fehler passt also zu beiden Erklärungen fast gleich gut und spricht kaum für Betrug."},{"option":2,"text":"Der Zählfehler passt tatsächlich zur Betrugsannahme. Er passt aber genauso zur harmlosen Erklärung eines gewöhnlichen Verzählens. Ob ein Hinweis eine Annahme stützt, zeigt erst der Vergleich mit den anderen Erklärungen."},{"option":3,"text":"Der Fehler lässt sich tatsächlich keiner der beiden Erklärungen eindeutig zuordnen. Zwei denkbare Erklärungen sind aber nicht gleich wahrscheinlich: Dass Betrug vorher sehr unwahrscheinlich war, bleibt auch nach dem Video weitgehend bestehen."}],"familie":"gewissheit-kalibrieren","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Joyce, J.: Bayes' Theorem. Stanford Encyclopedia of Philosophy","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bayes-theorem/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"3e7208588501d545"}},{"id":"qx-a1-033","clusterId":"A","werkstueckRef":"A.8","stufe":1,"question":"Wer hat recht, und womit lässt sich das am besten begründen?","scenario":"Ein Kollege sagt: „Ich esse jeden Mittag einen Burger, weil ich Hunger habe. Satt zu sein ist die Folge erster Ordnung. Dass ich nachmittags müde bin und langsam zunehme, ist die zweite. Dass mein Herzrisiko steigt und meine Gesundheitskosten in 20 Jahren höher ausfallen, ist die dritte.“ Seine Kollegin widerspricht: „Das Herzrisiko wiegt doch am schwersten, also müsste es die erste Ordnung sein.“","options":["Die Kollegin: Wie in der Eisenhower-Matrix sortiert man nach Wichtigkeit, also steht die gewichtigste Folge, das Herzrisiko, an erster Stelle.","Der Kollege: Die Ordnung zählt die Schritte zwischen Handlung und Folge, also die Stelle in der Kette, und nicht das Gewicht, das eine Folge hat.","Die Kollegin: Nach dem Pareto-Prinzip erzeugen wenige Folgen den Großteil der Wirkung, und diese wirkmächtigste Folge, das Herzrisiko, steht deshalb vorn.","Beide irren: Die Folgen wirken im Kreis aufeinander zurück (Rückkopplung), und deshalb gibt es keine feste Reihenfolge, die man zählen könnte."],"correctIndex":1,"explanation":"Die Ordnung einer Folge sagt, an welcher Stelle der Kette sie steht, nicht, wie schwer sie wiegt. Wer bei jeder Folge „Und was dann?“ fragt und die Antworten der Reihe nach ordnet, erhält genau diese Kette. Im Beispiel führt der Burger direkt zum Sattsein, das ist die erste Ordnung. Müdigkeit und Gewichtszunahme kommen als nächster Schritt hinzu, Herzrisiko und Gesundheitskosten stehen noch eine Stufe später. Dass eine schwere Folge auch von dritter Ordnung sein kann, ist eine Schlussfolgerung aus dieser Zählweise, denn das Gewicht einer Folge bestimmt ihre Stelle in der Kette nicht. Die anderen Gedanken sind für sich brauchbare Werkzeuge, passen aber nicht hierher: Die Eisenhower-Matrix sortiert Aufgaben nach Wichtigkeit, nicht Folgen nach ihrer Stelle in einer Kette. Das Pareto-Prinzip sagt, welche Folgen am meisten wiegen, nicht, in welchem Schritt sie auftreten. Und Rückkopplungen sind ein gutes Werkzeug für Schleifen, das Beispiel beschreibt aber eine Kette, in der jede Folge aus der vorigen hervorgeht.","coreRule":"⚡ Die Ordnung zählt Schritte in der Kette der Folgen, nicht, wie schwer eine Folge wiegt.","beleg":"Werkstück A.8 (Kontext & Tiefe)","status":"entwurf","kurz":"Die Ordnung zählt die Schritte in der Kette von der Handlung zur Folge, nicht das Gewicht. Naheliegend ist, die schwerste Folge nach vorn zu rücken, doch sie kann trotzdem erst drei Schritte später eintreten.","prueffrage":"Welche der genannten Folgen bliebe noch, wenn er vom täglichen Burger weder müde würde noch zunähme?","rueckmeldung":[{"option":0,"text":"Die Eisenhower-Matrix hilft, Aufgaben nach Wichtigkeit zu ordnen. Hier geht es aber um die Stelle einer Folge in einer Kette, und die hängt nicht davon ab, wie schwer sie wiegt."},{"option":2,"text":"Das Pareto-Prinzip zeigt, welche Folgen am meisten wiegen, und das Herzrisiko mag dazugehören. Wann eine Folge auftritt, sagt es aber nicht, und genau das bestimmt die Ordnung."},{"option":3,"text":"Rückkopplungen sind bei Schleifen ein gutes Werkzeug. Das Beispiel beschreibt aber eine Kette, in der jede Folge aus der vorigen hervorgeht, und die lässt sich zählen. Der Kollege irrt hier nicht."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Parrish, S. (Farnam Street, 2016): Second-Order Thinking: What Smart People Use to Outperform","oeffentlich":true,"url":"https://fs.blog/second-order-thinking/","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2bb7f9bc4132b189"}},{"id":"qx-a1-034","clusterId":"A","werkstueckRef":"A.8","stufe":2,"question":"Welche Folgenkette zeigt, was du mit der Frage „Und was dann?“ bei dieser Gewohnheit entdeckst?","scenario":"Eine Freundin visualisiert täglich eine halbe Stunde lang ihren künftigen Reichtum. Dafür lässt sie ihre Weiterbildung ausfallen. Sie ist überzeugt, dass das „Gesetz der Anziehung“ das Geld schon herbeiführen wird.","options":["Das Ausbleiben des Erfolgs gilt als Beleg gegen die Methode, sie gibt sie auf; die verlorene Zeit war nur ein harmloser Umweg ohne weitere Folgen.","Wer tagtäglich nur Gedanken übt, riskiert nichts: Eine reine Denkübung kostet weder Zeit noch Chancen und kann deshalb keine Nebenwirkungen haben.","Folgen höherer Ordnung gibt es nur bei teuren Entscheidungen, nicht bei Gewohnheiten, die man jederzeit beenden und ohne Verlust wieder aufnehmen kann.","Die Zeit für Qualifizierung fehlt; bleibt der Erfolg aus, sucht sie die Schuld bei sich („zu wenig positiv gedacht“) und steigert sich noch tiefer in die Methode hinein."],"correctIndex":3,"explanation":"Die Frage „Und was dann?“ legt eine Kette offen. Erste Folge: Die Zeit fließt ins Visualisieren und fehlt für Qualifizierung, Arbeit und die Lösung realer Probleme. Zweite Folge: Wirkt die Methode nicht, bleibt die Methode selbst unangetastet, denn sie lässt sich so deuten, dass das Scheitern am eigenen „nicht positiven Denken“ liegt. Das erzeugt Schuldgefühle und kann zu noch intensiverem magischem Denken führen, einem Teufelskreis. Die anderen Antworten halten den Blick bei der ersten, bequemen Ebene fest: Sie unterstellen, dass eine Gewohnheit ohne Kosten sei, nur weil sie unsichtbar bleibt. Dabei kostet jede Stunde, die man in eine Sache steckt, auch die Alternative, die man dafür nicht tut.","coreRule":"⚡ Frag nach jeder Lösung „Und was dann?“ – auch nach den Folgen der Folgen.","beleg":"Werkstück A.8 (Anwendung & Relevanz: Bei Aberglaube & magischem Denken)","status":"entwurf","kurz":"Die halbe Stunde täglich fehlt für Weiterbildung, und bleibt der Erfolg aus, lässt sich das als zu wenig positives Denken deuten. So wird die Methode nie widerlegt, es entsteht Schuld, und das magische Denken kann sich noch verstärken.","prueffrage":"Wie oft ist ihre Weiterbildung schon ausgefallen, und was hat sich an ihrer Lage seitdem verändert?","rueckmeldung":[{"option":0,"text":"Ein Misserfolg müsste eigentlich gegen eine Methode sprechen. Hier lässt er sich aber umdeuten: Es lag dann am eigenen Denken, nicht an der Methode. Zudem war die Zeit nicht folgenlos, denn die Weiterbildung blieb liegen."},{"option":1,"text":"Es werden zwar nur Gedanken geübt, doch dafür geht täglich eine halbe Stunde drauf, und die Weiterbildung fällt aus. Wer Zeit verwendet, hat immer Kosten, auch wenn sie unsichtbar bleiben."},{"option":2,"text":"Bei teuren Entscheidungen fällt die Kette der Folgen sofort auf, bei Gewohnheiten weniger. Sie ist aber auch hier da: Die Zeit ist schon weg, die Weiterbildung ausgefallen, und Selbstvorwürfe können dazukommen."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Parrish, S. (Farnam Street, 2016): Second-Order Thinking: What Smart People Use to Outperform","oeffentlich":true,"url":"https://fs.blog/second-order-thinking/","abruf":"2026-10-12"}],"thema":"Psychologie","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"552cfb5ffcaa33c9"}},{"id":"qx-a1-035","clusterId":"A","werkstueckRef":"A.8","stufe":3,"question":"Wie solltest du in dieser Lage vorgehen?","scenario":"Ein Team diskutiert seit Wochen alle denkbaren Folgen einer kleinen Software-Umstellung bis in die vierte und fünfte Ordnung und kommt zu keinem Beschluss.","options":["Sich auf die wahrscheinlichsten und schädlichsten Folgen der nächsten Stufe beschränken, diese in die Entscheidung einbeziehen und dann handeln.","Alle Folgen nach Wahrscheinlichkeit und Schaden bewerten und den Erwartungswert jeder Variante berechnen, bevor das Team einen Beschluss fasst.","Zuerst die Nulloption, also das Nichtstun, ebenso gründlich durchdenken wie die Umstellung selbst, bevor das Team einen Beschluss fasst.","Ein Pre-Mortem ansetzen, bei dem das Team jeden denkbaren Grund für ein Scheitern sammelt, bis keiner mehr offen ist, und erst dann entscheiden."],"correctIndex":0,"explanation":"Wer sich in einem unendlichen Netz möglicher Konsequenzen verliert, fällt in die „Analyse-Paralyse“ und kann nicht mehr handeln. Alle Folgen vorherzusehen ist unmöglich. Das Ziel ist nicht Perfektion, sondern Verbesserung: die wahrscheinlichsten und schädlichsten Folgen der nächsten Stufe identifizieren, in die Entscheidung einbeziehen und dann handeln. Manchmal ist sogar eine Lösung erster Ordnung die beste verfügbare Option. Weitere Berechnungen, die Nulloption oder ein Pre-Mortem sind für sich gute Werkzeuge, passen aber nicht zu dieser Lage: Das Team bewertet seit Wochen Folgen, und noch mehr Rechnen verlängert nur die Lähmung. Auch die Nulloption und ein Pre-Mortem erweitern die Analyse, statt zu einem Beschluss zu führen. Bei einer kleinen Umstellung stünde dieser Aufwand zudem in keinem Verhältnis zum Nutzen.","coreRule":"Ziel ist nicht Perfektion, sondern Verbesserung: die wahrscheinlichsten und schädlichsten Folgen erkennen und einbeziehen.","beleg":"Werkstück A.8 (Der Kipppunkt)","status":"entwurf","kurz":"Alle Folgen vorherzusehen ist unmöglich. Wer sie endlos weiterverfolgt, bleibt in der Analyse stecken. Es genügt, die wahrscheinlichsten und schädlichsten Folgen der nächsten Stufe zu berücksichtigen und dann zu handeln.","prueffrage":"Wie viel Neues hat die Diskussion der vierten und fünften Ordnung in den letzten Wochen zur Entscheidung beigetragen?","rueckmeldung":[{"option":1,"text":"Folgen nach Wahrscheinlichkeit und Schaden zu bewerten ist an sich sinnvoll. Hier läuft das aber seit Wochen, und über alle Folgen zu rechnen hat kein Ende, weil sich nicht alles vorhersehen lässt. Mehr Rechnen verlängert nur die Lähmung."},{"option":2,"text":"Die Nulloption mitzudenken ist ein gutes Werkzeug, denn auch Nichtstun hat Folgen. Das Team hat aber nicht zu wenig Analyse, sondern zu viel. Eine zweite gründliche Analyse führt nicht zu einem Beschluss, schon gar nicht bei einer kleinen Umstellung."},{"option":3,"text":"Ein Pre-Mortem kann Risiken gut sichtbar machen. Wer aber jeden denkbaren Grund sammelt, bis keiner mehr offen ist, findet kein Ende, denn es gibt immer noch einen weiteren. So wird aus dem Werkzeug eine neue Quelle der Lähmung."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Bounded Rationality","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bounded-rationality/","abruf":"2026-10-12"},{"typ":"url","kurz":"Parrish, S. (Farnam Street, 2016): Second-Order Thinking","oeffentlich":true,"url":"https://fs.blog/second-order-thinking/","abruf":"2026-10-12"}],"thema":"Technik und KI","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"98f9e456af79d23b"}},{"id":"qx-a1-036","clusterId":"A","werkstueckRef":"A.8","stufe":4,"question":"Ein Kollege sagt in der Diskussion über Bonusprogramme: „Das beweist doch, dass Kopfgelder nach hinten losgehen: In Delhi wurde auf Kobras ein Kopfgeld ausgesetzt, die Leute haben die Schlangen gezüchtet, und am Ende gab es mehr Kobras als vorher.“ Du recherchierst kurz: Die Geschichte wird seit der Jahrtausendwende als Lehrbeispiel für Fehlanreize erzählt, doch für Kobra-Zuchtbetriebe im britischen Indien findet sich kein zeitgenössischer Beleg. Wie gehst du mit dem Argument um?","options":["Du lässt das Beispiel gelten, weil viele es erzählen: Wenn zahlreiche Quellen übereinstimmen, spricht das für Zuverlässigkeit.","Du fragst zuerst, wem die Geschichte nützt, und bewertest das Argument nach den Interessen des Kollegen, der sie erzählt.","Du trennst beides: Das Beispiel taugt ohne Beleg nicht als Beweis, die allgemeine Aussage prüfst du an besser dokumentierten Fällen.","Du hältst die Geschichte für im Kern zutreffend, weil sie plausibel klingt: Dass Menschen Anreize ausnutzen, ist schließlich gut bekannt."],"correctIndex":2,"explanation":"Eine Geschichte wird nicht dadurch wahr, dass sie oft erzählt wird. Wo die Quelle fehlt, trägt das Beispiel als Beweis nicht. Dass es sich nicht belegen lässt, widerlegt aber auch nicht die allgemeine Aussage: Dass Anreize das Gegenteil des Beabsichtigten bewirken können, ist an anderen, gut dokumentierten Fällen zeigbar. Also trennst du beides und prüfst den Mechanismus mit solideren Belegen. Im konkreten Fall führt die Spur zu einem Zeitungsbericht von 1873, der die Zucht nur als Gerücht wiedergab, und zu Fachleuten, die sie schon damals für unwahrscheinlich hielten. Ein Kopfgeldprogramm in Madras wurde 1873 tatsächlich eingeschränkt, aber wegen der Kosten, nicht wegen aufgedeckten Betrugs. Dass viele Stellen die Geschichte weitererzählen, macht sie nicht belegter, denn Wiederholung ist keine unabhängige Bestätigung. Wer fragt, wem die Geschichte nützt, prüft den Erzähler statt der Behauptung. Und dass sie plausibel klingt, ersetzt keinen Beleg für genau diesen Fall.","coreRule":"⚡ Eine gute Lehrgeschichte ist kein Beleg – trenne den Mechanismus von der Anekdote.","beleg":"Werkstück A.8 (Das Kobra-Problem); Fn. ga-kobra (Siebert 2001; Friends of Snakes Society 2025); Anmerkung anm-ga-kobra","status":"entwurf","scenario":"","kurz":"Ohne Quelle taugt das Kobra-Beispiel nicht als Beweis, doch das widerlegt die allgemeine Aussage nicht. Der naheliegende Fehler ist, beides zu vermengen: Anreize können nach hinten losgehen, das prüfst du an besser dokumentierten Fällen.","prueffrage":"Woher stammt die Geschichte ursprünglich, und was lässt sich aus der Zeit selbst dazu finden?","rueckmeldung":[{"option":0,"text":"Viele übereinstimmende Quellen sind ein gutes Zeichen, wenn sie unabhängig voneinander belegen. Hier erzählen sie aber einander nach, und Wiederholung ersetzt keine zeitgenössische Quelle für genau diesen Fall."},{"option":1,"text":"Interessen eines Erzählers können Skepsis wecken. Dann prüfst du aber den Erzähler statt die Behauptung, und nichts deutet darauf hin, dass der Kollege hier Eigeninteressen verfolgt; er gibt eine verbreitete Geschichte weiter."},{"option":3,"text":"Dass Menschen Anreize ausnutzen können, ist gut bekannt, und dafür gibt es dokumentierte Fälle. Daraus folgt aber nicht, dass es genau in Delhi so geschah: Plausibel zu klingen ersetzt keinen Beleg für den einzelnen Fall."}],"familie":"lehrgeschichte-pruefen","fertigkeit":"F1","quellen":[{"typ":"url","kurz":"Friends of Snakes Society (2025, aktualisiert 16.09.2026): The Cobra Effect: Colonial Misinformation Masquerading as Economic Theory","oeffentlich":true,"url":"https://friendsofsnakes.org.in/cobra-effect/","abruf":"2026-10-12"},{"typ":"url","kurz":"Gilbert, M. J.: Interview mit Michael G. Vann zur Rattenjagd in Hanoi 1902. World History Connected 15.2","oeffentlich":true,"url":"https://worldhistoryconnected.press.uillinois.edu/15.2/vann_interview.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Siebert, H. (2001): Der Kobra-Effekt. Wie man Irrwege der Wirtschaftspolitik vermeidet","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ba15897c710782db"}},{"id":"qx-a1-037","clusterId":"A","werkstueckRef":"A.8.1","stufe":1,"question":"Welche Schlussfolgerung ist hier am besten begründet?","options":["Hier wirkt eine verstärkende Schleife: Mehr Weitererzählen bringt noch mehr Weitererzählen, und ohne bremsende Gegenkraft beruhigt sich das Gerücht nicht von selbst.","Hier wirkt eine ausgleichende Schleife wie beim Thermostat: Jedes Zuviel löst eine Gegenreaktion aus, deshalb findet das System von selbst in den Normalzustand zurück.","Hier wirkt die Regression zur Mitte: Nach einem extremen Ausschlag liegen spätere Werte meist näher am Durchschnitt, deshalb beruhigt sich die Verbreitung bald von selbst.","Hier wirkt das Gesetz der großen Zahlen: Wo viele Menschen beteiligt sind, gleichen sich Zufälle aus, deshalb stabilisiert sich die Verbreitung bald von selbst."],"correctIndex":0,"explanation":"Entscheidend ist die Richtung der Rückkopplung. Beim Gerücht führt mehr Verbreitung zu mehr Weitererzählen und damit zu noch mehr Verbreitung: eine verstärkende Schleife, die sich aufschaukelt, bis eine ausgleichende Kraft sie bremst, etwa weil kaum noch jemand übrig ist, der das Gerücht nicht kennt, oder weil das Interesse nachlässt. Ein Zielzustand, zu dem ein System von selbst zurückkehrt, entsteht nur bei ausgleichenden Schleifen: Beim Thermostat führt eine zu hohe Temperatur zu weniger Heizen und damit wieder zu sinkender Temperatur. Dass sich das Gerücht von selbst beruhigt und zum Normalzustand zurückfindet, folgt aus der beschriebenen Dynamik also nicht. Eine ausgleichende Schleife braucht eine Gegenreaktion auf das Zuviel, hier verstärkt jedes Zuviel sich selbst. Die Regression zur Mitte betrifft zufällige Ausschläge von Messwerten, nicht einen Prozess, der sich selbst antreibt. Das Gesetz der großen Zahlen mittelt unabhängige Zufälle, hier hängen die Beteiligten aber über das Weitererzählen voneinander ab.","coreRule":"⚡ Frag bei jedem Prozess: Bremst das Ergebnis den Vorgang (ausgleichend, Richtung Zielzustand) oder treibt es ihn weiter an (verstärkend, Richtung Eskalation)?","beleg":"Werkstück A.8.1 (Kernidee: Zwei Haupttypen)","status":"entwurf","scenario":"In einer Diskussion über ein Gerücht sagt jemand: „Das Gerücht hat sich in zwei Tagen verzehnfacht. Je mehr Leute es hören, desto mehr erzählen es weiter. Das System wird sich bestimmt von selbst wieder beruhigen und zu seinem Normalzustand zurückfinden.“","kurz":"Mehr Hörer bedeuten mehr Weitererzähler, und das treibt die Verbreitung weiter an. Der Denkfehler ist, ein Aufschaukeln für eine Schleife mit Gegenreaktion zu halten: Zurück zum Normalzustand geht es nur, wo ein Zuviel eine Gegenkraft auslöst.","prueffrage":"Wie viele Leute haben das Gerücht am ersten Tag weitererzählt, und wie viele am zweiten?","rueckmeldung":[{"option":1,"text":"Beim Thermostat bremst die Temperatur ihren eigenen Anstieg, deshalb passt das Bild so gut zum Wort „Normalzustand“. Beim Gerücht fehlt diese Gegenreaktion: Jedes Zuviel verstärkt sich selbst. Gebremst wird erst später, etwa wenn kaum noch jemand das Gerücht nicht kennt."},{"option":2,"text":"Nach einem extremen Wert liegt der nächste oft näher am Durchschnitt, das stimmt bei zufälligen Schwankungen. Die Verzehnfachung ist aber kein Zufallsausschlag, sondern Folge eines Prozesses, der sich selbst antreibt. Dafür sagt die Regression zur Mitte keine baldige Beruhigung voraus."},{"option":3,"text":"Bei vielen unabhängigen Zufällen gleichen sich Abweichungen tatsächlich aus. Hier sind die Beteiligten aber nicht unabhängig: Sie hören das Gerücht voneinander und geben es weiter. Dadurch schaukelt sich die Verbreitung auf, statt sich auszumitteln."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System (Donella Meadows Project)","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Meadows, D. H. (2008): Thinking in Systems: A Primer","oeffentlich":false}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"07a175e50962bb85"}},{"id":"qx-a1-038","clusterId":"A","werkstueckRef":"A.8.1","stufe":2,"question":"Was ist hier der klügste nächste Schritt?","scenario":"Du verlierst mit Sport und weniger Kalorien zunächst Gewicht, doch nach einigen Monaten stagniert es, obwohl du dich scheinbar an alles hältst wie am Anfang. Du überlegst, wie du jetzt vorgehst.","options":["Du fragst, ob der frühe Erfolg überhaupt vom Plan kam, und vergleichst dich dazu mit Menschen, die nichts verändert haben.","Du fragst, wie es anderen mit demselben Plan im Durchschnitt ergeht, und richtest deine Erwartung an diesem Durchschnitt aus.","Du fragst, wie lange die Wirkung eines Plans braucht, um sichtbar zu werden, und wartest, bis die verzögerte Rückmeldung eintrifft.","Du fragst, wie sich dein Körper und dein Essverhalten durch deine Handlung verändert haben, und passt dein Vorgehen daran an."],"correctIndex":3,"explanation":"Eine Handlung verändert das System, auf das sie wirkt: Ein leichterer Körper verbraucht weniger Energie, der Stoffwechsel passt sich zum Teil an, und oft lockert sich unbemerkt auch das eigene Essverhalten. Dieselbe Handlung führt dann nicht mehr zum selben Ergebnis. Deshalb prüfst du, was sich verändert hat, und passt dein Vorgehen an. Ein Vorbehalt gehört dazu: Nach einer Modellrechnung von Hall und Kollegen (2011) liegt die Ursache des typischen Plateaus nach 6 bis 8 Monaten eher in nachlassender Einhaltung der Diät als in einem plötzlich gebremsten Stoffwechsel. Gerade deshalb lohnt es sich, ehrlich nachzumessen, statt nur zu raten. Die anderen Gedanken sind für sich nützlich, treffen aber nicht den Kern: Ob der frühe Erfolg vom Plan kam, ist hier nicht fraglich, denn das Gewicht ist ja gesunken. Ein Durchschnitt anderer Menschen sagt nicht, was sich bei dir verändert hat. Und eine Verzögerung erklärt kein Plateau, nachdem die Wirkung bereits sichtbar war.","coreRule":"⚡ Führt die Handlung nicht mehr zum Ziel, hat sich das System verändert: Prüfe die Rückmeldung und passe an, statt mehr vom Gleichen zu tun.","beleg":"Werkstück A.8.1 (Geschichte des Thermostats und des Diät-Plateaus); Fn. ga-diaet-plateau (Hall u. a. 2011, The Lancet 378(9793), S. 826–837)","status":"entwurf","kurz":"Dein Vorgehen hat dein Körpergewicht und vermutlich auch dein Essverhalten verändert, deshalb wirkt dieselbe Handlung nicht mehr gleich. Naheliegend ist, nur den Plan zu befragen; klüger ist, ehrlich nachzumessen, was sich bei dir verändert hat.","prueffrage":"Zeigen Waage und Maßband seit Wochen dieselben Werte, wenn du immer zur gleichen Tageszeit misst?","rueckmeldung":[{"option":0,"text":"Ein Vergleich mit Menschen ohne Veränderung klärt, ob ein Erfolg vom Plan stammt. Hier ist das aber schon beantwortet: Das Gewicht ist ja gesunken. Offen ist, warum es jetzt stagniert, und dazu sagt dieser Vergleich nichts."},{"option":1,"text":"Der Durchschnitt anderer kann als grobe Orientierung helfen. Er sagt dir aber nicht, was sich bei dir verändert hat, etwa beim Energieverbrauch oder bei deinen Essgewohnheiten, und gerade das erklärt dein Plateau."},{"option":2,"text":"Manche Wirkungen zeigen sich tatsächlich erst spät. Deine ist aber schon eingetreten: Das Gewicht ist gesunken. Eine Verzögerung erklärt nicht, warum es danach stehen bleibt, und Abwarten klärt die Ursache nicht."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Hall, K. D. u. a. (2011): Quantification of the effect of energy imbalance on bodyweight. The Lancet 378(9793), 826–837","oeffentlich":true,"doi":"10.1016/S0140-6736(11)60812-X","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC3880593","abruf":"2026-10-12"}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"1aad256b17e7a917"}},{"id":"qx-a1-039","clusterId":"A","werkstueckRef":"A.8.1","stufe":3,"question":"Eine Gemeinde senkt die Abwasserbelastung eines Sees. Fachleute erwarten, dass die Wirkung der Maßnahmen erst nach rund 20 Jahren sichtbar wird. Nach fünf Jahren ohne erkennbare Besserung fordern einige, die Maßnahmen als wirkungslos aufzugeben, andere wollen sie verdoppeln. Welche Überlegung zur Steuerung dieser Schleife ist am stichhaltigsten?","options":["Bei stark verzögerter Rückmeldung sagt das Ausbleiben von Wirkung wenig aus: Wer früh abbricht oder verdoppelt, steuert womöglich falsch, deshalb braucht es früher messbare Zwischenindikatoren.","Bei sehr häufiger Rückmeldung gerät eine Schleife leicht ins Schwingen: Wer auf jede kleine Schwankung reagiert, übersteuert womöglich, deshalb braucht es nur seltene und späte Messungen.","Bei fünf Jahren ohne Besserung ist die einfachste Erklärung, dass die Maßnahmen nichts bewirken (Ockhams Rasiermesser): Wer weiter wartet, steuert womöglich falsch, deshalb braucht es zuerst einen Neuansatz.","Bei ausbleibender Wirkung gilt das Prinzip von Dosis und Wirkung: Mehr Einsatz bringt mehr Effekt, deshalb braucht es zuerst eine deutliche Verstärkung der Maßnahmen und erst danach weitere Messungen."],"correctIndex":0,"explanation":"Eine ausgleichende Schleife steuert gut, solange ihre Rückmeldung rechtzeitig kommt. Ist sie stark verzögert, zeigt sich die Wirkung einer Handlung erst, wenn längst nachgesteuert wurde: Wer nach fünf Jahren ohne sichtbaren Effekt abbricht, gibt womöglich eine wirksame Maßnahme auf; wer verdoppelt, schießt womöglich über das Ziel hinaus. Früher messbare Zwischenindikatoren verkürzen diese Verzögerung, etwa die Frage, ob die Zuflüsse tatsächlich weniger belastet sind. Zu häufiges Reagieren auf jede Schwankung ist bei schneller Rückmeldung ein Problem, hier kommt die Rückmeldung aber zu spät und nicht zu oft. Dass die Maßnahmen nichts bewirken, wäre nur eine mögliche Erklärung; nach einem Viertel der erwarteten Zeit ist ausbleibende Besserung dafür kaum ein Beleg. Mehr Einsatz würde in einem so trägen System erst sehr spät zeigen, ob er nötig war, und kann das Ziel überschießen.","coreRule":"⚡ Je länger die Rückmeldung braucht, desto weniger darfst du aus fehlender Wirkung schließen. Suche früher messbare Zwischenindikatoren, bevor du abbrichst oder verdoppelst.","beleg":"Werkstück A.8.1 (Der Kipppunkt: Der Verzögerungs-Kipppunkt)","status":"entwurf","scenario":"","quote":"","quoteLabel":"","kurz":"Wenn die Wirkung erst nach rund 20 Jahren sichtbar wird, sagt fünf Jahre ohne Besserung kaum etwas aus: Abbrechen und Verdoppeln können beide danebenliegen. Früh messbare Zwischenindikatoren verkürzen die Verzögerung.","prueffrage":"Was genau wurde in den fünf Jahren im See gemessen, und wie oft?","rueckmeldung":[{"option":1,"text":"Dass zu häufiges Reagieren eine Schleife ins Schwingen bringen kann, stimmt bei schneller Rückmeldung. Hier kommt die Rückmeldung aber zu spät, nicht zu oft, und seltene, späte Messungen würden die Verzögerung nur verlängern."},{"option":2,"text":"Die einfachste Erklärung ist nur dann die beste, wenn sie die Lage gleich gut erklärt. Hier war die Wirkung erst nach rund 20 Jahren erwartet; nach einem Viertel der Zeit ist die ausbleibende Besserung kaum ein Beleg für Wirkungslosigkeit."},{"option":3,"text":"Mehr Einsatz kann mehr bewirken, doch ob er nötig ist, zeigt ein so träges System erst sehr spät. Die Verdoppelung kann das Ziel überschießen, bevor die Wirkung der ersten Maßnahmen überhaupt sichtbar wurde."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Meadows, D.: Leverage Points: Places to Intervene in a System (Donella Meadows Project)","oeffentlich":true,"url":"https://donellameadows.org/archives/leverage-points-places-to-intervene-in-a-system/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Jeppesen, E. u. a. (2005): Lake responses to reduced nutrient loading – an analysis of contemporary long-term data from 35 case studies. Freshwater Biology 50, 1747–1771","oeffentlich":true,"doi":"10.1111/j.1365-2427.2005.01415.x","url":"https://kops.uni-konstanz.de/bitstreams/862b4528-106d-4161-9d82-4edf44290472/download","seite":"S. 1747–1748 (Summary, Punkt 2)","abruf":"2026-10-12"}],"thema":"Natur und Klima","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"bc0037bc5c9f7e82"}},{"id":"qx-a1-040","clusterId":"A","werkstueckRef":"A.8.1","stufe":4,"question":"Welche Einschätzung wird der Lage am ehesten gerecht?","scenario":"Ein Bekannter klickt aus Neugier auf ein „skeptisches“ Video über Chemtrails. Danach werden ihm immer mehr und immer extremere Videos zum Thema vorgeschlagen, und er hält die Behauptung zunehmend für belegt: „Das gibt es ja überall, das kann kein Zufall sein.“ Eine Kollegin meint: „Die Plattform hat ihn radikalisiert. Er hat anfangs nur ein einziges Video angeklickt, alles Weitere hat der Algorithmus ihm vorgesetzt.“","options":["Die Dynamik ist eine verstärkende Schleife aus Klick, Empfehlung und wachsender Überzeugung. Die Behauptung, der Algorithmus allein sei schuld, ist aber zu stark, denn er verstärkt eher vorhandene Neigungen, als dass er sie erzeugt.","Die Dynamik ist eine verstärkende Schleife aus Klick, Empfehlung und wachsender Überzeugung. Die Kollegin hat deshalb recht, denn der Algorithmus erzeugt die Überzeugung allein, während der Bekannte nur aufnimmt, was ihm vorgesetzt wird.","Die Dynamik ist vor allem ein Bestätigungsfehler: Der Bekannte wählt und deutet alles so, dass es seine Ansicht stützt. Die Kollegin überschätzt die Plattform, denn deren Empfehlungen ändern an seiner Überzeugung nichts.","Die Dynamik ist eine ausgleichende Schleife, weil die Plattform auf jeden Klick reagiert und so seine Überzeugung stabilisiert. Die Behauptung der Kollegin ist deshalb falsch, denn von einer Eskalation kann hier keine Rede sein."],"correctIndex":0,"explanation":"Hier greifen zwei Dinge ineinander: Der Klick signalisiert Interesse, die Plattform spielt mehr und extremeres Material aus, der Nutzer sieht „überall Beweise“ und klickt weiter. Das ist eine verstärkende Schleife, in der Output wieder zum Input wird. Daraus folgt aber nicht, dass der Algorithmus allein die Überzeugung formt. Die Rolle von Empfehlungssystemen ist umstritten: Sie wirken eher als Verstärker vorhandener Neigungen denn als Puppenspieler, und tiefer hinein führen oft Abonnements und Links, die andere schicken. Die Schleife braucht beide Seiten, die Technik und den Menschen, der darauf reagiert. Wer nur eine Seite verantwortlich macht, verkürzt die Ursachen. Eine ausgleichende Schleife würde den Ausgangszustand stabilisieren, statt zu eskalieren; hier wächst die Überzeugung aber immer weiter. Dass der Algorithmus die Überzeugung ganz allein erzeuge, übersieht, dass der Bekannte jedes Mal selbst klickt und deutet. Ein Bestätigungsfehler allein erklärt die Eskalation nicht, denn erst die Empfehlungen liefern ihm immer neues Material.","coreRule":"⚡ Eine Schleife braucht beide Seiten: Auch ein Algorithmus verstärkt oft nur, was schon da ist. Wer „allein schuld“ sagt, hat die Rückkopplung nicht verstanden.","beleg":"Werkstück A.8.1 (Anwendung & Relevanz: Der algorithmische Kaninchenbau)","status":"entwurf","quote":"","quoteLabel":"","kurz":"Klick, Empfehlung und wachsende Überzeugung verstärken sich gegenseitig. Verkürzt wird es, wenn man nur eine Seite verantwortlich macht: Der Algorithmus verstärkt eher vorhandene Neigungen, und der Bekannte klickt und deutet jedes Mal selbst.","prueffrage":"Wie viele der vorgeschlagenen Videos hat er tatsächlich angeklickt, und wie viele hat er übersprungen?","rueckmeldung":[{"option":1,"text":"Die Schleife ist hier richtig erkannt, und die Empfehlungen treiben sie tatsächlich an. Dass der Algorithmus die Überzeugung allein erzeuge, trägt aber nicht: Der Bekannte klickt und deutet selbst, und Empfehlungen verstärken eher, was schon angelegt ist."},{"option":2,"text":"Dass er alles so deutet, dass es seine Ansicht stützt, ist plausibel. Dass die Empfehlungen daran nichts ändern, trifft aber nicht zu: Sie liefern ihm immer neues, extremeres Material, und erst dadurch eskaliert die Lage."},{"option":3,"text":"Eine ausgleichende Schleife würde den Ausgangszustand halten. Hier wächst die Überzeugung aber, und die Videos werden extremer, also verstärkt sich etwas. Dass die Plattform auf jeden Klick reagiert, macht daraus noch keine Stabilisierung."}],"familie":"systemisch-denken","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Chen, A. Y.; Nyhan, B.; Reifler, J.; Robertson, R. E.; Wilson, C. (2023): Subscriptions and external links help drive resentful users to alternative and extremist YouTube channels. Science Advances 9(35), eadd8080","oeffentlich":true,"doi":"10.1126/sciadv.add8080","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10468121/","abruf":"2026-10-12"},{"typ":"doi","kurz":"Hosseinmardi, H. u. a. (2021): Examining the consumption of radical content on YouTube. PNAS 118(32), e2101967118","oeffentlich":true,"doi":"10.1073/pnas.2101967118","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8364190/","abruf":"2026-10-12"}],"thema":"Netz und Medien","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"30ace0f5a277ee0b"}},{"id":"qx-a1-041","clusterId":"A","werkstueckRef":"A.9","stufe":1,"question":"Was spricht dafür, dass die Leiterin hier klüger vorgeht als der Kollege?","scenario":"Ein Projektteam plant die Einführung einer neuen Software. Kurz vor dem Start sagt die Leiterin: „Stellen wir uns vor, in einem Jahr ist dieses Projekt die größte Katastrophe unserer Firmengeschichte. Was ist passiert?“ Ein Kollege widerspricht: „Das ist Schwarzmalerei. Wir sollten uns lieber darauf konzentrieren, wie wir erfolgreich sind.“","options":["Sie senkt die Erwartungen des Teams im Voraus, damit später niemand enttäuscht ist, falls das Projekt in einem schlechten Ergebnis endet.","Sie lässt das Team sein Projekt mit dem Durchschnitt vergleichbarer Softwareprojekte vergleichen, damit die Planung auf einer realistischen Außensicht beruht.","Sie lässt das Team die Wege des Scheiterns durchdenken, damit die größten und wahrscheinlichsten Fehler gezielt vermieden werden können.","Sie legt den schlimmsten Fall als Planungsgrundlage fest, damit Zeit und Budget so großzügig bemessen werden, dass auch dieser Fall abgedeckt ist."],"correctIndex":2,"explanation":"Die Leiterin kehrt die Frage um: Statt „Wie gelingt das Projekt?“ fragt sie „Was würde es garantiert ruinieren?“. Das ist oft leichter zu beantworten, denn über Gefahren und Fehlerquellen lässt sich meist konkreter nachdenken als über eine perfekte Erfolgsstrategie. Aus den gefundenen Ursachen entsteht eine Liste von Dingen, die man gezielt vermeidet. So schließt man die größten und dümmsten Fehler aus, und das verbessert das Ergebnis oft deutlich. Das ist keine Schwarzmalerei, denn es geht nicht darum, das Scheitern zu erwarten, sondern es zu verhindern. Die Erwartungen zu senken würde keinen einzigen Fehler verhindern. Der Vergleich mit dem Durchschnitt anderer Projekte ist ein nützliches Werkzeug, die Leiterin fragt aber nach den konkreten Ursachen in diesem Projekt. Und einen Puffer für den schlimmsten Fall einzuplanen setzt voraus, dass man ihn kennt; sie sucht erst, was ihn herbeiführen würde.","coreRule":"⚡ Frag nicht nur, wie du gewinnst, sondern auch, wie du sicher scheiterst – und meide genau das.","beleg":"Werkstück A.9 (Die Rede des Piloten; Kernidee)","status":"entwurf","kurz":"Die Leiterin fragt nach den Wegen des Scheiterns, weil sich über Fehlerquellen meist konkreter nachdenken lässt als über eine perfekte Strategie. Das ist keine Schwarzmalerei: Das Scheitern wird nicht erwartet, sondern gezielt verhindert.","prueffrage":"Wann stellt die Leiterin ihre Frage, und was ließe sich zu diesem Zeitpunkt noch ändern?","rueckmeldung":[{"option":0,"text":"Niedrigere Erwartungen dämpfen vielleicht die Enttäuschung, doch kein einziger Fehler wird dadurch verhindert. Die Leiterin will das Scheitern nicht abfedern, sondern seine Ursachen finden und ausschließen."},{"option":1,"text":"Der Vergleich mit ähnlichen Projekten ist ein nützliches Werkzeug, nur ist es nicht das, was die Leiterin hier tut. Sie fragt nicht nach Durchschnittswerten, sondern nach den konkreten Ursachen, die gerade dieses Projekt ruinieren könnten."},{"option":3,"text":"Einen Puffer für den schlimmsten Fall kann nur einplanen, wer ihn kennt. Die Leiterin sucht aber erst, was ihn herbeiführen würde, und legt nichts fest. Aus den gefundenen Ursachen wird eine Liste, die man gezielt vermeidet, statt einfach großzügiger zu kalkulieren."}],"familie":"vom-scheitern-her-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Klein, G. (2007): Performing a Project Premortem. Harvard Business Review (September 2007)","oeffentlich":true,"url":"https://hbr.org/2007/09/performing-a-project-premortem","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Mitchell, D. J.; Russo, J. E.; Pennington, N. (1989): Back to the future: Temporal perspective in the explanation of events. Journal of Behavioral Decision Making","oeffentlich":false},{"typ":"doi","kurz":"Van Vleck, E. B. (1916): Current Tendencies of Mathematical Research. Bulletin of the American Mathematical Society 23(1), 1–13","oeffentlich":true,"doi":"10.1090/S0002-9904-1916-02863-1","seite":"S. 3","abruf":"2026-10-04"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"02c3ce20f4a3cb0f"}},{"id":"qx-a1-042","clusterId":"A","werkstueckRef":"A.9","stufe":2,"question":"Welches Vorgehen deckt die größten Risiken am zuverlässigsten auf?","scenario":"Dein Team plant den Start eines neuen Produkts. Alle sind begeistert, und im Plan steht nur, was alles gut laufen soll. Eine Kollegin fragt, wie ihr den Plan am besten auf Schwachstellen prüft.","options":["Ihr nehmt an, der Start sei ein Jahr später eine Katastrophe, sammelt, was dazu geführt haben müsste, und macht daraus eine verbindliche „Nicht-tun“-Liste.","Ihr rechnet für den Start den Erwartungswert aus, indem ihr Gewinn und Verlust mit ihren Wahrscheinlichkeiten gewichtet, und startet, wenn das Ergebnis positiv ist.","Ihr vergleicht den Plan mit dem eines früheren erfolgreichen Produktstarts, prüft, ob dort alle Schritte ebenfalls vorkamen, und ergänzt, was fehlt.","Ihr zerlegt den Plan in Meilensteine mit festen Terminen, damit Verzögerungen früh auffallen, und steuert bei Abweichungen jeweils sofort nach."],"correctIndex":0,"explanation":"Ein Plan, der nur aus Best-Case-Annahmen besteht, übersieht Risiken, weil niemand nach den Wegen des Scheiterns gesucht hat. Der Perspektivwechsel, das Scheitern als Tatsache anzunehmen und rückwärts zu fragen, was dazu geführt haben müsste, macht diese Wege sichtbar. Das fällt leichter, als einen perfekten Erfolgsweg zu entwerfen, denn Gefahren und Fehlerquellen erkennen wir meist besser als komplexe Erfolgsstrategien. Aus den gefundenen Ursachen entsteht eine konkrete „Nicht-tun“-Liste. Eine Erwartungswertrechnung ist nützlich, setzt aber voraus, dass man mögliche Verluste und ihre Wahrscheinlichkeiten schon kennt; genau das fehlt hier, denn im Plan stehen nur gelungene Abläufe. Der Vergleich mit einem erfolgreichen Start zeigt nur, was bei einem Gelingen vorkam, nicht, woran Vorhaben scheitern. Meilensteine zeigen Abweichungen erst, wenn sie eintreten, und decken nicht vorab auf, wo der Plan Lücken hat.","coreRule":"⚡ Mach vorab die Autopsie: Wie ist das Projekt gescheitert? Und plane gegen genau das.","beleg":"Werkstück A.9 (Kontext & Tiefe: „Worst-Case“-Inversion; Werkbank-Frage)","status":"entwurf","kurz":"Ein Plan voller Best-Case-Annahmen übersieht Risiken, weil niemand nach Wegen des Scheiterns gesucht hat. Nimmt man das Scheitern als Tatsache an und fragt rückwärts, was dazu geführt haben müsste, werden diese Wege sichtbar.","prueffrage":"Welche Annahmen im Plan hat bisher noch niemand ernsthaft in Frage gestellt, und wer hätte einen Grund, sie anzuzweifeln?","rueckmeldung":[{"option":1,"text":"Gewinn und Verlust mit Wahrscheinlichkeiten zu gewichten, klingt gründlich und ist grundsätzlich nützlich. Dafür müsste man mögliche Verluste und ihre Wahrscheinlichkeiten aber schon kennen, und im Plan stehen nur gelungene Abläufe."},{"option":2,"text":"Der Vergleich kann fehlende Schritte aufzeigen. Er zeigt aber nur, was bei einem Gelingen vorkam, nicht, woran Vorhaben scheitern, und lässt die Fehlerquellen unberührt, die im eigenen Plan noch niemand gesucht hat."},{"option":3,"text":"Feste Meilensteine helfen, Verzögerungen früh zu bemerken und nachzusteuern. Das setzt aber erst ein, wenn eine Abweichung eintritt, und sagt nicht vorab, wo der Plan Lücken hat."}],"familie":"vom-scheitern-her-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Klein, G. (2007): Performing a Project Premortem. Harvard Business Review","oeffentlich":true,"url":"https://hbr.org/2007/09/performing-a-project-premortem","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Mitchell, D. J.; Russo, J. E.; Pennington, N. (1989): Back to the future: Temporal perspective in the explanation of events. Journal of Behavioral Decision Making","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"4ed2dda3a97b03de"}},{"id":"qx-a1-043","clusterId":"A","werkstueckRef":"A.9","stufe":3,"question":"Was ist an diesem Vorgehen verfehlt?","scenario":"In jeder Besprechung zählt ein Kollege neue Risiken auf. Das Projekt wird nie gestartet, weil nie alle Risiken beseitigt sind.","options":["Es ist verfehlt, denn Risiken gehören schriftlich festgehalten statt mündlich genannt; erst eine schriftliche Liste macht sie bearbeitbar und lässt sie abhaken.","Es ist verfehlt, denn ein Einzelner übersieht beim Sammeln leicht Risiken; erst mehrere unabhängige Sichtweisen im Team liefern ein verlässliches Gesamtbild.","Es ist verfehlt, denn Risiken lassen sich erst bewerten, wenn ihre Ursachen geklärt sind; die bloße Aufzählung überspringt diese Ursachenanalyse.","Es ist verfehlt, denn null Risiko ist unerreichbar; man muss die gewichtigsten Risiken vermeiden und dann mit dem Rest handeln, statt zu warten."],"correctIndex":3,"explanation":"Risiken zu suchen und zu vermeiden ist nützlich, es senkt die Wahrscheinlichkeit des Scheiterns. Es kippt aber in Lähmung, sobald man verlangt, vor dem Handeln alle Risiken auszuräumen. Das ist unmöglich, denn alle Risiken auf null zu senken, gelingt nie. Klug ist, die größten, dümmsten und wahrscheinlichsten Fehlerquellen gezielt auszuschließen, mit dem Rest bewusst zu leben und zu handeln. Ob Risiken schriftlich oder mündlich genannt werden, ändert nichts daran, dass die Liste nie abgearbeitet ist. Mehr Sichtweisen würden die Liste eher länger machen, nicht den Start möglich. Auch eine Ursachenanalyse liefert nur genauere Risiken, aber keine Entscheidung, wann genug geprüft ist.","coreRule":"⚡ Risiken suchen heißt gewichten, nicht abschaffen: Die größten, dümmsten und wahrscheinlichsten vermeiden, dann mit klugem Mut handeln.","beleg":"Werkstück A.9 (Der Kipppunkt)","status":"entwurf","kurz":"Alle Risiken auszuräumen, gelingt nie, deshalb wird das Projekt nie starten. Sinnvoll ist, die größten und wahrscheinlichsten Fehlerquellen gezielt auszuschließen und mit dem Rest bewusst zu handeln.","prueffrage":"Wie viele der aufgezählten Risiken hätten das Projekt ernsthaft gefährdet, und wie viele waren eher Kleinigkeiten?","rueckmeldung":[{"option":0,"text":"Eine schriftliche Liste kann Risiken tatsächlich greifbarer machen. Am Kern ändert das aber nichts: Auch eine geschriebene Liste wird nie leer, solange man vor dem Start alles Risiko beseitigen will."},{"option":1,"text":"Mehr Blickwinkel decken oft zusätzliche Risiken auf. Genau das verlängert aber die Liste, statt den Start zu ermöglichen. Das Problem ist nicht eine unvollständige Sammlung, sondern dass kein Punkt festgelegt ist, an dem genug geprüft ist."},{"option":2,"text":"Wer Ursachen kennt, beschreibt Risiken genauer und kann sie besser einschätzen. Die Frage, wann genug geprüft ist, beantwortet das nicht: Mit genaueren Risiken bleibt die Liste trotzdem endlos, und die Entscheidung zum Start bleibt aus."}],"familie":"vom-scheitern-her-denken","fertigkeit":"F4","quellen":[{"typ":"url","kurz":"Stanford Encyclopedia of Philosophy: Bounded Rationality","oeffentlich":true,"url":"https://plato.stanford.edu/entries/bounded-rationality/","abruf":"2026-10-12"},{"typ":"url","kurz":"Klein, G. (2007): Performing a Project Premortem. Harvard Business Review","oeffentlich":true,"url":"https://hbr.org/2007/09/performing-a-project-premortem","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"dc67eb48bb9a7e49"}},{"id":"qx-a1-044","clusterId":"A","werkstueckRef":"A.9","stufe":4,"question":"Was ist hier die klügste Prüffrage, bevor du dich entscheidest?","scenario":"Eine Gemeinschaft verspricht dir „totale Freiheit“ und „Erleuchtung“ und wirbt mit begeisterten Erfolgsberichten ihrer Mitglieder. Du überlegst, ob du beitreten sollst.","options":["Ich frage mich, woran man erkennen würde, dass ich in geistige Unfreiheit gerate, und prüfe, ob die Gruppe genau diese Schritte von mir verlangt.","Ich prüfe, ob die Erfolgsberichte der Mitglieder in sich stimmig und detailreich sind; je stimmiger sie wirken, desto glaubwürdiger ist die Gruppe.","Ich frage die Mitglieder, ob sie sich frei fühlen, und prüfe, ob alle einhellig zustimmen; dann halte ich die Gruppe für unbedenklich.","Ich frage, wie lange die Gruppe schon besteht, und prüfe, ob sie über Jahre Bestand hatte; was lange überdauert, hat sich in der Regel bewährt."],"correctIndex":0,"explanation":"Wer nur fragt, wie der versprochene Weg zum Ziel führt, bleibt im Erzählrahmen der Gruppe. Die umgekehrte Frage ist schärfer: Was müsste ich tun, um garantiert in geistiger Unfreiheit zu landen? Typische Antworten sind das kritische Denken aufgeben, sich von anderen Informationsquellen abschneiden, eine Person als unfehlbar akzeptieren und das eigene Vermögen übertragen. Verlangt die Gruppe genau das, ist das ein starkes Warnsignal, egal wie schön ihr Versprechen klingt. Die Inversion lenkt den Blick auf die Wege des Scheiterns (vgl. Überlebensirrtum), statt auf die Erfolgsgeschichten, die man zu hören bekommt. Stimmige, detailreiche Berichte zeigen nur, dass die Geschichten gut erzählt sind, nicht, was aus denen wurde, die gegangen sind. Einhellige Zustimmung der Mitglieder sagt nichts über die Schritte, die die Gruppe von dir verlangt. Und dass eine Gruppe lange besteht, spricht für ihre Haltbarkeit, nicht dafür, dass sie ihren Mitgliedern guttut.","coreRule":"⚡ Frag, wie du dich garantiert in Unfreiheit bringen würdest, und prüfe, ob eine Gruppe genau diese Schritte von dir verlangt.","beleg":"Werkstück A.9 (Anwendung & Relevanz: Bei Kulten & manipulativen Systemen; Verbindungen: Überlebensirrtum)","status":"entwurf","kurz":"Entscheidend ist, was die Gruppe von dir verlangt, nicht was sie dir verspricht. Verlangt sie Denkverzicht, Abschottung oder Vermögensübertragung, ist das ein Warnsignal, so schön das Versprechen auch klingt. Erfolgsberichte verdecken das.","prueffrage":"Was weißt du über Mitglieder, die die Gruppe wieder verlassen haben, und warum sie gegangen sind?","rueckmeldung":[{"option":1,"text":"Stimmige, detailreiche Berichte wirken überzeugend, zeigen aber nur, dass gut erzählt wird. Zu Wort kommen die, die geblieben sind; von denen, die gegangen sind, hört man nichts. Mehr Stimmigkeit macht die Gruppe also nicht glaubwürdiger."},{"option":2,"text":"Wer gefragt wird, ist schon drin, und das Gefühl der Freiheit kann sich einstellen, während die Schritte dorthin längst Abhängigkeit erzeugen. Ein einhelliges Ja sagt nichts darüber, was die Gruppe von dir verlangt, und rechtfertigt kein „unbedenklich“."},{"option":3,"text":"Lange Dauer spricht für Haltbarkeit der Gruppe, nicht dafür, dass sie ihren Mitgliedern guttut. Auch Gemeinschaften, die Menschen schaden, können über Jahre bestehen. Gefragt ist, was sie von dir verlangt, nicht wie alt sie ist."}],"familie":"vom-scheitern-her-denken","fertigkeit":"F4","quellen":[{"typ":"doi","kurz":"Van Vleck, E. B. (1916): Current Tendencies of Mathematical Research. Bulletin of the American Mathematical Society 23(1), 1–13","oeffentlich":true,"doi":"10.1090/S0002-9904-1916-02863-1","seite":"S. 3","abruf":"2026-10-04"},{"typ":"literatur","kurz":"Lifton, R. J. (1961): Thought Reform and the Psychology of Totalism (Kap. 22)","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"66201543157069fe"}},{"id":"qx-a1-045","clusterId":"A","werkstueckRef":"A.10","stufe":1,"question":"In einer Debatte über Homeoffice sagt Jana: „Wer Homeoffice will, möchte doch nur den ganzen Tag im Schlafanzug auf dem Sofa liegen und nichts leisten.“ Anschließend widerlegt sie diese Behauptung ausführlich. Ihr Gegenüber Murat zuckt nur mit den Schultern. Warum ändert Janas Widerlegung an der Frage nach dem Homeoffice kaum etwas?","options":["Sie hat eine verzerrte, leicht angreifbare Version der Gegenposition widerlegt, nicht die Position, die Murat tatsächlich vertritt.","Sie hat von einer zeitlichen Abfolge auf eine Ursache geschlossen, obwohl zwei Ereignisse auch nur zufällig nacheinander eintreten können.","Sie hat sich auf eine Autorität berufen, die zum Thema Homeoffice nichts Fachliches beitragen kann, statt eigene Gründe zu nennen.","Sie hat nur zwei Möglichkeiten zugelassen, ganz im Büro oder ganz zu Hause, und alle Zwischenlösungen ausgeblendet."],"correctIndex":0,"explanation":"Wer eine Karikatur der Gegenposition besiegt, hat über die eigentliche Position nichts gezeigt. Janas Widerlegung trifft nur die Schlafanzug-Version, nicht Murats mögliche Gründe wie Zeitersparnis, konzentriertes Arbeiten oder Vereinbarkeit mit Familie. Ein Sieg zählt erst, wenn die stärkste, fairste Fassung der Gegenseite standhält. Erst dann hat man die Idee wirklich geprüft und nicht nur eine bequeme Attrappe. Andere Denkfehler gibt es durchaus, sie liegen hier aber nicht vor: Jana schließt weder aus einer zeitlichen Abfolge auf eine Ursache noch beruft sie sich auf eine fachfremde Autorität, und sie lässt auch nicht nur zwei Möglichkeiten gelten. Ihr Problem ist das Ziel ihrer Widerlegung, nicht deren Form.","coreRule":"⚡ Nur die stärkste Version einer Idee zu besiegen, ist ein Sieg – einen Strohmann zu besiegen, beweist nichts.","quote":"","quoteLabel":"","beleg":"Werkstück A.10 (Kontext & Tiefe)","status":"entwurf","scenario":"","kurz":"Jana widerlegt nur die Schlafanzug-Karikatur, nicht Murats mögliche Gründe wie Zeitersparnis, konzentriertes Arbeiten oder Familie. Wer eine bequeme Attrappe besiegt, hat die eigentliche Position nicht geprüft.","prueffrage":"Wer hat die Schlafanzug-Behauptung in die Debatte gebracht, und was hat Murat selbst dazu gesagt?","rueckmeldung":[{"option":1,"text":"Dieser Fehler braucht zwei Ereignisse, von denen eines das andere angeblich verursacht. Davon steht im Gespräch nichts: Jana schließt aus keiner zeitlichen Abfolge auf eine Ursache, sondern unterstellt anderen ein Motiv."},{"option":2,"text":"Eine Berufung auf Autorität würde heißen, dass Jana sich auf eine fachfremde Person oder Stelle stützt. Sie nennt aber niemanden, sondern widerlegt mit eigenen Argumenten, nur gegen eine Behauptung, die kaum jemand vertritt."},{"option":3,"text":"Ein falsches Dilemma stellt nur zwei Wege zur Wahl und blendet den Rest aus. Jana spricht aber gar nicht über Büro oder Zuhause als einzige Optionen, sondern über das angebliche Motiv der Homeoffice-Befürworter."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"3 Quarks Daily (23.05.2013): Daniel Dennett's seven tools for thinking – Auszug aus Dennett 2013, zuerst The Guardian, Abschn. „Respect your opponent“","oeffentlich":true,"url":"https://3quarksdaily.com/?p=18487","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Dennett, D. C. (2013): Intuition Pumps and Other Tools for Thinking","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2e08c518490f8a78"}},{"id":"qx-a1-046","clusterId":"A","werkstueckRef":"A.10","stufe":2,"question":"Welches Vorgehen ist am sinnvollsten, um Jana fair und trotzdem wirksam zu widersprechen?","options":["Zuerst Janas Position so genau und stark wiedergeben, dass sie zustimmt; dann Gemeinsamkeiten nennen und was du von ihr gelernt hast; erst danach deine Kritik äußern.","Zuerst Jana für ihr Engagement loben; dann deine Kritik an ihrer Position äußern; zum Schluss wieder etwas Anerkennendes sagen, damit das Gespräch freundlich endet.","Zuerst deine Sicht aus der Ich-Perspektive darlegen („Ich sehe das anders, weil …“); dann Jana fragen, was sie dazu denkt; zum Schluss Gemeinsamkeiten festhalten.","Zuerst Jana gezielte Fragen zu ihrer Position stellen; dann die Antworten auf Widersprüche abklopfen; erst danach, wenn nötig, deine eigene Sicht nennen."],"correctIndex":0,"explanation":"Wer die Gegenposition erst in ihrer stärksten Form wiedergibt und sich bestätigen lässt, zwingt sich selbst zum echten Verstehen. Danach trifft die Kritik die tatsächliche Position und nicht eine Karikatur. Wer eine schwache Version widerlegt, hat nichts erreicht; wer die stärkste Version widerlegt, hat die Idee wirklich geprüft. Außerdem hört ein Gegenüber, das sich fair behandelt fühlt, der Kritik eher zu. Die Reihenfolge ist: verstehen und fair wiedergeben, Übereinstimmungen benennen, Gelerntes würdigen, erst dann widersprechen. Diese Abfolge ist als „Rapoports Regeln“ bekannt. Lob vor und nach der Kritik macht das Gespräch freundlich, zeigt aber nicht, dass du ihre Position verstanden hast. Die eigene Sicht in Ich-Form zu äußern vermeidet Vorwürfe, lässt aber offen, ob du sie richtig erfasst hast. Fragen können helfen, Janas Gründe zu verstehen, ersetzen aber nicht die Wiedergabe, die sie bestätigen kann.","coreRule":"⚡ Erst verstehen und würdigen, dann widersprechen.","beleg":"Werkstück A.10 (Kontext & Tiefe: Rapoports Regeln)","status":"entwurf","scenario":"In einer Gesprächsrunde vertritt Jana die Ansicht, innerorts solle überall Tempo 30 gelten. Du hältst das für überzogen und willst ihr widersprechen, ohne dass sie sich missverstanden fühlt.","kurz":"Wer Janas Position erst in ihrer stärksten Form wiedergibt und sich bestätigen lässt, widerspricht der echten Position statt einer Karikatur. Außerdem hört sie Kritik eher zu, wenn sie sich fair behandelt fühlt.","prueffrage":"Wie geht Jana vermutlich mit deinen Einwänden um, wenn sie den Eindruck hat, du hättest ihre Sicht gar nicht verstanden?","rueckmeldung":[{"option":1,"text":"Lob macht das Gespräch freundlich und ist nicht verkehrt. Es sagt aber nichts darüber, ob du Janas Position verstanden hast, und deine Kritik kann an ihr vorbeigehen."},{"option":2,"text":"Ich-Aussagen vermeiden Vorwürfe, und Gemeinsamkeiten festzuhalten ist gut. Doch solange du Janas Position nicht wiedergegeben hast, bleibt offen, ob du sie richtig erfasst hast."},{"option":3,"text":"Fragen helfen, Janas Gründe zu verstehen. Sie ersetzen aber nicht die Wiedergabe, die sie bestätigen kann, und das Abklopfen auf Widersprüche kann sich wie ein Verhör anfühlen."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"3 Quarks Daily (23.05.2013): Daniel Dennett's seven tools for thinking – Auszug aus Dennett 2013, zuerst The Guardian, Abschn. „Respect your opponent“","oeffentlich":true,"url":"https://3quarksdaily.com/?p=18487","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Rapoport, A. (1960): Fights, Games, and Debates","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"1c4af0a12c4b2581"}},{"id":"qx-a1-047","clusterId":"A","werkstueckRef":"A.10","stufe":3,"question":"Was ist an dieser Schlussfolgerung falsch?","scenario":"Eine Bekannte meint: „Wer fair diskutieren will, muss die Position seines Gegenübers erst in ihrer stärksten Form darstellen, bevor er sie kritisiert. Also muss er das auch bei der Behauptung tun, 2 + 2 sei 5, und bei Propaganda, die gezielt Falschinformationen verbreitet.“","options":["Sie überträgt eine Regel für Gespräche mit gutem Willen und Vernunft auch auf Fälle, in denen diese Voraussetzungen fehlen.","Sie meint, wer eine Position in ihrer stärksten Form darstellt, müsse ihr auch zustimmen, und verwechselt so Verstehen mit Zustimmen.","Sie hält die Regel für eine Frage des freundlichen Tons und verwechselt so Fairness mit Höflichkeit.","Sie begeht einen Sein-Sollen-Fehlschluss: Aus dem, was in Debatten üblich ist, leitet sie ab, was in jedem Fall geboten sei."],"correctIndex":0,"explanation":"Absurde oder gefährliche Thesen muss man nicht als legitim behandeln und deshalb auch nicht in ihrer „stärksten Version“ konstruieren, etwa die Behauptung, 2 + 2 sei 5. Die Regel, eine Gegenposition erst in ihrer stärksten Form darzustellen, gilt für Debatten, in denen ein Minimum an gutem Willen und Rationalität auf der Gegenseite angenommen werden kann. Bei reiner Propaganda oder bösartiger Desinformation fehlt diese Grundlage. Dort können andere Werkzeuge, etwa das klare Benennen der rhetorischen Taktiken, wirksamer sein. Der Fehlschluss liegt also darin, eine Regel auszudehnen, ohne zu prüfen, ob ihre Voraussetzungen erfüllt sind. Verstehen mit Zustimmen zu verwechseln wäre ein bekannter Fehler, die Bekannte fordert hier aber nur die Darstellung, nicht die Zustimmung. Es geht ihr auch nicht um den Ton, sondern um die inhaltliche Wiedergabe. Und einen Sein-Sollen-Fehlschluss begeht sie nicht, denn sie leitet die Pflicht aus dem Ziel fairen Diskutierens ab; verfehlt ist die Reichweite, nicht die Herleitung.","coreRule":"⚡ Eine Regel gilt nur, solange ihre Voraussetzungen erfüllt sind: Die stärkste Version einer Position zu formulieren setzt guten Willen voraus.","beleg":"Werkstück A.10 (Der Kipppunkt)","status":"entwurf","kurz":"Die Regel, eine Gegenposition erst in ihrer stärksten Form darzustellen, setzt ein Minimum an gutem Willen und Rationalität voraus. Der Fehler liegt darin, sie auf Propaganda oder „2 + 2 = 5“ auszudehnen, ohne zu prüfen, ob diese Voraussetzung dort überhaupt gegeben ist.","prueffrage":"Was bezweckt jemand, der gezielt Falschinformationen verbreitet, mit seinen Behauptungen?","rueckmeldung":[{"option":1,"text":"Verstehen und Zustimmen zu verwechseln ist tatsächlich ein verbreiteter Fehler. Die Bekannte verlangt aber nur die Darstellung, ausdrücklich vor der Kritik, also keine Zustimmung. Ihr Fehler liegt woanders."},{"option":2,"text":"Fairness und Höflichkeit sind wirklich zweierlei. Die Bekannte spricht aber nicht über den Tonfall, sondern darüber, die Position inhaltlich in ihrer stärksten Form wiederzugeben. Mit dem Ton hat ihre Regel nichts zu tun."},{"option":3,"text":"Ein Sein-Sollen-Fehlschluss würde aus bloßer Üblichkeit ein Gebot machen. Die Bekannte leitet die Pflicht aber aus dem Ziel des fairen Diskutierens ab. Das ist als Herleitung nicht das Problem, sondern wie weit sie die Regel ausdehnt."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"3 Quarks Daily (23.05.2013): Daniel Dennett's seven tools for thinking – Auszug aus Dennett 2013, zuerst The Guardian","oeffentlich":true,"url":"https://3quarksdaily.com/?p=18487","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Dennett, D. C. (2013): Intuition Pumps and Other Tools for Thinking","oeffentlich":false}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"6e955afec90f4c6c"}},{"id":"qx-a1-048","clusterId":"A","werkstueckRef":"A.10","stufe":4,"question":"Welche Eröffnung ist der beste erste Schritt, bevor du deine Kritik äußerst?","scenario":"Dein Onkel schwört auf Homöopathie. Du hältst ihre Wirksamkeit für nicht belegt, willst ihn aber nicht gleich vor den Kopf stoßen. Du überlegst, wie du das Gespräch beginnst, damit er dir wirklich zuhört und du seine Position nicht zur Karikatur machst.","options":["„Homöopathie ist wissenschaftlich widerlegt, dazu gibt es genug Studien. Wir können also gleich zum nächsten Thema übergehen, ohne weiter darüber zu reden.“","„Du hast recht, die Schulmedizin kann nicht alles. Dann ist Homöopathie bestimmt genauso wirksam, und wir müssen da nichts weiter prüfen.“","„Du misstraust der oft unpersönlichen Medizin mit ihren starken Nebenwirkungen und suchst eine sanfte Methode, die dir Kontrolle und Fürsorge gibt. Habe ich dich da richtig verstanden?“","„Du glaubst also ernsthaft, dass ein paar Zuckerkügelchen eine Erkältung heilen können, und gibst dafür auch noch bereitwillig Geld aus?“"],"correctIndex":2,"explanation":"Die Eröffnung gibt die Gründe und Bedürfnisse des Onkels so fair und stark wieder, dass er zustimmen kann, und lädt ausdrücklich zur Bestätigung ein. Erst danach hat Kritik Gewicht, denn wer sich verstanden fühlt, hört eher zu, und wer die stärkste Fassung einer Position prüft, widerlegt wirklich etwas und nicht bloß eine Karikatur. Wer das Gespräch mit „widerlegt, nächstes Thema“ abwürgt, prüft die Position gar nicht erst, und der Onkel fühlt sich abgetan. Die spöttische Rückfrage („Du glaubst also ernsthaft …?“) verzerrt dagegen seine Haltung zur Karikatur und zielt auf die Person statt auf ihre Gründe: ein Strohmann. Pauschale Zustimmung wiederum ist kein Verstehen, sondern ein Rückzug, denn sie gibt die eigene Prüfung auf; eine faire Wiedergabe ist gerade keine Zustimmung, sondern die Grundlage einer ehrlichen Widerlegung.","coreRule":"⚡ Gib die Position des anderen so wieder, dass er „genau“ sagt, ohne ihr damit zuzustimmen. Erst dann kritisiere.","beleg":"Werkstück A.10 (Anwendung & Relevanz: Im Dialog mit Anhängern von Pseudomedizin; Red Flags)","status":"entwurf","kurz":"Wer die Gründe des Onkels so wiedergibt, dass er zustimmen kann, schafft die Grundlage dafür, dass er der Kritik zuhört und dass sie seine stärkste Position trifft statt einer Karikatur. Verzerren, Abwürgen oder bloßes Zustimmen verfehlt das.","prueffrage":"Wie reagiert dein Onkel vermutlich, wenn er sich schon durch deinen ersten Satz belächelt oder abgewiesen fühlt?","rueckmeldung":[{"option":0,"text":"Die Studienlage spricht tatsächlich gegen eine Wirkung über Placebo hinaus. Mit dem Abwürgen erfährst du aber nie, was deinen Onkel überzeugt, und er fühlt sich abgetan statt gehört. So wird nichts widerlegt, nur ein Gespräch beendet."},{"option":1,"text":"Dass die Schulmedizin Grenzen hat, stimmt. Daraus folgt aber nicht, dass Homöopathie wirkt. Mit der Zustimmung gibst du deine eigene Prüfung auf; verstehen heißt nicht, der Kritik zu entsagen."},{"option":3,"text":"Dass Globuli oft keinen nachweisbaren Wirkstoff enthalten, trifft zu. Der spöttische Ton macht aus der Haltung deines Onkels aber eine Karikatur und unterstellt ihm Naivität: ein Angriff auf die Person statt Auseinandersetzung mit seinen Gründen."}],"familie":"fair-wiedergeben","fertigkeit":"F3","quellen":[{"typ":"url","kurz":"3 Quarks Daily (23.05.2013): Daniel Dennett's seven tools for thinking – Auszug aus Dennett 2013, zuerst The Guardian, Abschn. „Respect your opponent“","oeffentlich":true,"url":"https://3quarksdaily.com/?p=18487","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Rapoport, A. (1960): Fights, Games, and Debates","oeffentlich":false}],"thema":"Gesundheit","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"2a38378215ba6a36"}},{"id":"qx-a1-049","clusterId":"A","werkstueckRef":"A.11","stufe":1,"question":"Was ist an Peters Schluss am problematischsten?","scenario":"Dein Team hat einen Plan ohne eine einzige Gegenstimme beschlossen. Peter fasst zusammen: „Alle sind dafür, niemand hat einen Einwand gebracht. Also wissen wir: Der Plan hat keine ernsthaften Schwächen.“","options":["Er behandelt das Fehlen geäußerter Einwände als Beweis, dass keine Schwächen existieren, obwohl der Wunsch nach Harmonie berechtigte Einwände unterdrücken kann.","Er stützt seinen Schluss auf einen Experten, dessen Fachgebiet nicht zum Plan passt, obwohl ein Autoritätsargument nur bei einschlägiger Sachkenntnis trägt.","Er verzerrt die Gegenposition zu einer leicht widerlegbaren Karikatur, obwohl eine faire Prüfung die stärkste Fassung der Gegenseite würdigen müsste.","Er setzt in seiner Begründung voraus, was erst zu zeigen wäre, sodass sich der Schluss im Kreis dreht, obwohl Prämissen unabhängig vom Ergebnis tragen müssen."],"correctIndex":0,"explanation":"Dass niemand widerspricht, zeigt nur, dass niemand widersprochen hat, nicht, dass es nichts einzuwenden gäbe. Wo der Wunsch nach Harmonie stark ist, kann er auch berechtigte Einwände unterdrücken: Wer Zweifel hat, schweigt womöglich, weil Kritik als persönlicher Angriff oder Illoyalität gelten könnte, und sieht ringsum nur Zustimmung. Einstimmigkeit ist deshalb kein Beleg für einen guten Plan, sondern kann ein Alarmsignal für Gruppendenken sein. Ein mögliches Gegenmittel ist, Widerspruch ausdrücklich zu verlangen, etwa durch einen bestellten Teufelsanwalt; in einem Experiment von Nemeth, Brown und Rogers (2001) regte echter Widerspruch allerdings mehr Lösungen an als jede geprüfte Form des bestellten Teufelsanwalts, bei der Güte allein war kein Unterschied gesichert. Die anderen Denkfehler gibt es durchaus, Peter begeht sie aber nicht: Er beruft sich auf keinen Experten, es gibt keine Gegenposition, die er verzerren könnte, und sein Schluss dreht sich nicht im Kreis, sondern springt von einer Beobachtung (kein Einwand) auf eine Behauptung (keine Schwächen).","coreRule":"⚡ Schweigen ist kein Beweis für Zustimmung, und Einstimmigkeit ist kein Beweis für Qualität: Wo niemand widerspricht, muss jemand ausdrücklich den Auftrag zum Widerspruch bekommen.","beleg":"Werkstück A.11 (Kontext & Tiefe; Red Flags)","status":"entwurf","kurz":"Dass niemand widersprochen hat, zeigt nur, dass niemand widersprochen hat, nicht, dass es nichts einzuwenden gibt. Wer Zweifel hat, schweigt womöglich, um Harmonie zu wahren, und sieht dann ringsum nur Zustimmung.","prueffrage":"Hat vor der Abstimmung jemand ausdrücklich nach Einwänden oder Schwachstellen gefragt?","rueckmeldung":[{"option":1,"text":"Mit Experten ließe sich ein Schluss tatsächlich schwächen, wenn sie fachfremd sind. Peter beruft sich aber auf keine Autorität, sondern allein auf das Ausbleiben von Einwänden im Team."},{"option":2,"text":"Eine Karikatur der Gegenseite wäre ein echter Denkfehler. Hier gibt es aber keine Gegenposition, die Peter verzerren könnte: Es wurde ja gerade kein Einwand vorgebracht."},{"option":3,"text":"Ein Zirkelschluss setzt das Ergebnis schon in der Begründung voraus. Peter nimmt aber eine Beobachtung, das Ausbleiben von Einwänden, und folgert daraus eine neue Behauptung. Der Schluss ist zu schnell, nicht kreisförmig."}],"familie":"schweigen-ist-keine-zustimmung","fertigkeit":"F2","quellen":[{"typ":"literatur","kurz":"Janis, I. L. (1972): Victims of Groupthink","oeffentlich":false},{"typ":"doi","kurz":"Esser, J. K. (1998): Alive and Well after 25 Years: A Review of Groupthink Research. OBHDP 73(2–3), 116–141","oeffentlich":false,"doi":"10.1006/obhd.1998.2758"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"korrigieren","pruefsumme":"b457adc3f3a283f5"}},{"id":"qx-a1-050","clusterId":"A","werkstueckRef":"A.11","stufe":2,"question":"Was ist der beste Weg, die Entscheidung vor der Unterschrift zu prüfen?","scenario":"Du hast ein Jobangebot in einer anderen Stadt und willst es annehmen. Freunde und Familie gratulieren dir begeistert, niemand äußert Bedenken. Du möchtest sichergehen, dass die Entscheidung gut ist, bevor du unterschreibst.","options":["Du blendest alles bisher Investierte aus und fragst, ob du die Stelle heute noch annehmen würdest, damit versunkene Kosten dein Urteil nicht verzerren.","Du zerlegst die Glückwünsche in überprüfbare Tatsachenbehauptungen und bloße Wertungen und überprüfst danach nur die Tatsachenbehauptungen auf ihre Belege.","Du spielst im Gedankenexperiment durch, ob die Entscheidung widerspruchsfrei bliebe, wenn alle Menschen in deiner Lage genauso entscheiden würden.","Du nimmst dir eine feste Zeit und listest jeden erdenklichen Grund auf, warum die Entscheidung scheitern könnte, und prüfst danach, welche dieser Gründe tragen."],"correctIndex":3,"explanation":"Einhellige Zustimmung ist kein Beleg für eine gute Entscheidung: Wer gratuliert, will sich mitfreuen und die Stimmung nicht trüben, deshalb bleiben Bedenken oft unausgesprochen. Gezielt nach Schwächen zu suchen heißt, vor einer großen Entscheidung bewusst die Rolle des Advocatus Diaboli einzunehmen und jeden erdenklichen Grund aufzulisten, warum sie scheitern könnte. Danach werden die Einwände geprüft: Tragen sie, beseitigst du die Schwäche oder verwirfst den Plan; tragen sie nicht, entscheidest du mit mehr Sicherheit. Die Kritik soll die Idee stärken oder aussortieren, nicht endlos zerreden. Die anderen Werkzeuge sind in anderer Lage sinnvoll, passen hier aber nicht: Versunkene Kosten gibt es nicht, weil du noch nichts in die Stelle investiert hast. Die Glückwünsche enthalten kaum Tatsachenbehauptungen, die sich nachprüfen ließen. Und ein Gedankenexperiment über alle Menschen in deiner Lage klärt nicht, ob diese Entscheidung für dich trägt.","coreRule":"⚡ Bevor du dich festlegst, gib dir den Auftrag, deine eigene Entscheidung zu widerlegen.","beleg":"Werkstück A.11 (Anwendung & Relevanz: Im Alltag; Der Kipppunkt)","status":"entwurf","kurz":"Einhellige Glückwünsche sind noch kein Beleg, denn wer gratuliert, will sich mitfreuen, und Bedenken bleiben oft unausgesprochen. Wer gezielt nach Gründen für ein Scheitern sucht und diese dann prüft, zwingt die Entscheidung, sich zu bewähren.","prueffrage":"Wer würde dir offen widersprechen, wenn er Bedenken hätte, und was würde er dabei riskieren?","rueckmeldung":[{"option":0,"text":"Die Frage, ob du es heute noch täten, hilft, wenn schon viel in eine Sache geflossen ist. Du hast aber noch nichts in die Stelle investiert, also gibt es nichts auszublenden, und mögliche Schwächen deckt die Frage nicht auf."},{"option":1,"text":"Behauptungen auf ihre Belege zu prüfen ist ein gutes Werkzeug, nur geben die Glückwünsche dafür kaum etwas her. Gratulationen sind Mitfreude und keine Aussagen über die Entscheidung, und die Einhelligkeit selbst lässt sich auf diesem Weg nicht aufklären."},{"option":2,"text":"Die Verallgemeinerungsprobe taugt für Handlungen, die auch andere betreffen. Ob die Entscheidung widerspruchsfrei wäre, wenn alle so handelten, sagt aber nichts darüber, ob diese Stelle für dich und deine Lage trägt."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"url","kurz":"Lord, C. G.; Lepper, M. R.; Preston, E. (1984): Considering the opposite: a corrective strategy for social judgment. JPSP 47(6), 1231–1243 (Abstract, PubMed)","oeffentlich":true,"doi":"10.1037//0022-3514.47.6.1231","url":"https://pubmed.ncbi.nlm.nih.gov/6527215/","abruf":"2026-10-12"},{"typ":"url","kurz":"Behavioral Scientist (Schlitz, I., 10.07.2018): Stop Playing Devil's Advocate, and Other Advice for Better Decision Making (Interview mit Charlan Nemeth)","oeffentlich":true,"url":"https://behavioralscientist.org/stop-playing-devils-advocate-and-other-advice-for-better-decision-making/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"8842835bc3fb2f63"}},{"id":"qx-a1-051","clusterId":"A","werkstueckRef":"A.11","stufe":3,"question":"Wie schätzt du die Aussage der Geschäftsführerin ein?","scenario":"In einer Firma wurde nach einem teuren Fehlentscheid beschlossen, dass in jeder Sitzung reihum ein Teammitglied den „Teufelsanwalt“ spielt und ausdrücklich die Gegenposition zur Mehrheitsmeinung vertritt. Nach einigen Wochen meint die Geschäftsführerin: „Damit ist das Problem des fehlenden Widerspruchs gelöst.“ In einem Versuch mit Vierergruppen, die über einen Urlaubsplan berieten, hatte sich Folgendes gezeigt: Ein vorgegebener Widerspruch wirkte unterschiedlich, je nachdem, ob die Person ihn als echte Überzeugung vorbrachte oder als zugewiesene Rolle spielte.","options":["Sie ist zu optimistisch: Ein zugewiesener Widerspruch kann ein nützliches Hilfsmittel sein, doch echter Widerspruch von jemandem, der wirklich abweicht, ist ihm in der Wirkung auf die Lösungen überlegen.","Sie ist berechtigt: Ein zugewiesener Widerspruch ist beliebter als der eines echten Abweichlers, deshalb löst er den Konflikt auf und führt zu besseren Lösungen.","Sie ist berechtigt: Die Art des Widerspruchs spielt keine Rolle, entscheidend ist allein, dass die Gruppe überhaupt Gegenargumente hört.","Sie ist zu pessimistisch: Ein gespielter Gegenredner regt die Gruppe zuverlässig dazu an, offen über andere Positionen nachzudenken, solange er die Gegenposition glaubwürdig vorträgt."],"correctIndex":0,"explanation":"Die Behauptung „Problem gelöst“ ist ein Sprung von „es gibt jetzt eine Rolle“ zu „es gibt jetzt wirksamen Widerspruch“. Genau das hat ein kleiner Versuch mit 94 Studentinnen in Vierergruppen geprüft: Nach echtem Widerspruch nannten die Teilnehmerinnen mehr Lösungen als nach jeder Form des bestellten Teufelsanwalts, und auch ein Maß aus Zahl und Güte fiel zugunsten des echten Widerspruchs aus; bei der Güte allein war kein Unterschied gesichert. Beliebter als ein echter Abweichler war der Rollenspieler nicht, und die Diskussion mit ihm wurde als ebenso konfliktreich erlebt. In einer Vorstudie regte der gespielte Gegenredner vor allem Gedanken an, die die Ausgangsposition untermauerten, nicht solche über andere Positionen. Du darfst die Rolle also als Hilfsmittel schätzen, aber nicht darauf vertrauen, dass sie echten Widerspruch ersetzt.","coreRule":"⚡ Eine gespielte Gegenrede ersetzt keinen echten Widerspruch. Sie ist ein Hilfsmittel, kein Heilmittel.","beleg":"Werkstück A.11 (Kontext & Tiefe; Der Kipppunkt); Fn. ga-nemeth (Nemeth, Brown, Rogers 2001, European Journal of Social Psychology 31(6), S. 707–720)","status":"entwurf","kurz":"„Problem gelöst“ springt von „es gibt jetzt eine Rolle“ zu „es gibt wirksamen Widerspruch“. Im Versuch war echter Widerspruch dem bestellten überlegen; die Rolle kann helfen, ersetzt ihn aber nicht.","prueffrage":"Was lässt sich in den Sitzungen beobachten, das zeigt, dass der Widerspruch wirklich etwas verändert hat?","rueckmeldung":[{"option":1,"text":"Ein bestellter Gegenredner wirkt, als brächte er weniger Streit. Im Versuch war er aber nicht beliebter als ein echter Abweichler, die Diskussion galt als ebenso konfliktreich, und echter Widerspruch schnitt bei den Lösungen besser ab."},{"option":2,"text":"Gegenargumente sind an sich wichtig. Doch die Art des Widerspruchs spielte im Versuch eine Rolle: Echter Widerspruch war jeder Form des bestellten Teufelsanwalts überlegen, auch wenn der Unterschied bei der Güte allein nicht gesichert war."},{"option":3,"text":"Ein glaubwürdig vorgetragener Gegenpart wirkt, als würde er zum Umdenken anregen. In einer Vorstudie regte der gespielte Gegenredner aber vor allem Gedanken an, die die Ausgangsposition stützten, nicht solche über andere Positionen."}],"familie":"gegenbeleg-suchen","fertigkeit":"F5","quellen":[{"typ":"doi","kurz":"Nemeth, C.; Brown, K.; Rogers, J. (2001): Devil's advocate versus authentic dissent: stimulating quantity and quality. European Journal of Social Psychology 31(6), 707–720","oeffentlich":false,"doi":"10.1002/ejsp.58"},{"typ":"url","kurz":"Behavioral Scientist (Schlitz, I., 10.07.2018): Stop Playing Devil's Advocate, and Other Advice for Better Decision Making (Interview mit Charlan Nemeth)","oeffentlich":true,"url":"https://behavioralscientist.org/stop-playing-devils-advocate-and-other-advice-for-better-decision-making/","abruf":"2026-10-12"}],"thema":"Zusammenleben","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"ce8453cac5957054"}},{"id":"qx-a1-052","clusterId":"A","werkstueckRef":"A.11","stufe":4,"question":"Wie solltest du diese Behauptung einordnen?","scenario":"Im Netz heißt es: „Seit Johannes Paul II. 1983 die Prüfung durch den Advocatus Diaboli bei Heiligsprechungen entmachtet hat, explodierten die Heiligsprechungen – der Beweis, dass diese Rolle funktioniert hat.“ Belegt ist: Er sprach in seinem Pontifikat 482 Menschen heilig, mehr als seine Vorgänger der vorangegangenen fünf Jahrhunderte zusammen. Zugleich wurde mit derselben Reform ein Großteil der Ermittlungsarbeit auf die Ortsbistümer verlagert, und er setzte sich persönlich stark für Heiligsprechungen ein.","options":["Der Anstieg ist belegt, aber vermutlich Zufall; bei so kleinen Fallzahlen schwanken die Werte stark, und aus Schwankungen lässt sich nichts ableiten.","Die Zahlen sind belegt, aber andere Ursachen bleiben offen; solange sie nicht ausgeschlossen sind, ist die Aussage nur eine Vermutung und kein Beweis.","Die Zahl allein sagt nichts aus; ohne einen Vergleichswert aus früheren Zeiträumen lässt sich nicht beurteilen, ob überhaupt ein Anstieg stattgefunden hat.","Die Behauptung ist ein Strohmann; sie unterstellt Kritikern der Rolle eine Position, die diese nie vertreten haben, und widerlegt dann diese Unterstellung."],"correctIndex":1,"explanation":"Die Zahl ist gut belegt und der zeitliche Zusammenfall ebenfalls. Daraus folgt aber noch keine Ursache: Dieselbe Reform hat auch die Ermittlungsarbeit auf die Ortsbistümer verlagert, und der Papst setzte sich persönlich für Heiligsprechungen ein. Jede dieser Erklärungen kommt als Mitursache in Frage; ob und wie stark, ist unter Kirchenhistorikern umstritten. Wer den Anstieg als Beweis für die Wirkung der Rolle ausgibt, zieht aus einer Korrelation einen Kausalschluss und übergeht konkurrierende Erklärungen. Redlich ist es, die Zahl anzuerkennen und den Schluss offen zu lassen, bis andere Erklärungen geprüft sind. Die anderen Einordnungen klingen nach bekannten Prüfregeln, passen hier aber nicht: Bei 482 Heiligsprechungen, mehr als in den fünf Jahrhunderten davor zusammen, kann von kleinen, zufälligen Schwankungen keine Rede sein. Ein Vergleichswert wird in den Angaben ja mitgeliefert. Und von Kritikern, denen etwas unterstellt würde, ist nirgends die Rede.","coreRule":"⚡ Zeitliches Zusammenfallen heißt nicht, dass das eine das andere bewirkte – auch bei gut belegten Zahlen.","beleg":"Werkstück A.11 (Kontext & Tiefe); Fn. ga-jp2 (Johannes Paul II., Divinus Perfectionis Magister, 25.1.1983, Nr. 10 und 13; Bigalke 2025, S. 106)","status":"entwurf","kurz":"Zahl und zeitlicher Zusammenfall sind belegt, daraus folgt aber keine Ursache: Dieselbe Reform verlagerte die Ermittlungen auf die Bistümer, und der Papst warb selbst für Heiligsprechungen. Solange das nicht geprüft ist, bleibt der Schluss eine Vermutung.","prueffrage":"Was davon ist belegt, und was behauptet nur der Beitrag im Netz?","rueckmeldung":[{"option":0,"text":"Dass der Anstieg belegt ist, stimmt. Bei 482 Heiligsprechungen, mehr als in den fünf Jahrhunderten davor zusammen, ist aber keine kleine, zufällige Schwankung am Werk. Der Einwand geht am Kern vorbei: Strittig ist die Ursache, nicht die Zahl."},{"option":2,"text":"Ein Vergleichswert steht im Szenario schon: Die Zahl übertrifft die der fünf Jahrhunderte davor zusammen. Der Anstieg lässt sich also beurteilen. Offen bleibt, was ihn verursacht hat, nicht ob es ihn gab."},{"option":3,"text":"Ein Strohmann verzerrt die Position anderer, um sie zu widerlegen. Hier ist von Kritikern der Rolle aber nirgends die Rede. Die Behauptung zieht stattdessen aus einem zeitlichen Zusammenfall einen Ursachenschluss."}],"familie":"korrelation-und-ursache","fertigkeit":"F2","quellen":[{"typ":"url","kurz":"Pew Research Center (Lipka, M.; Townsend, T., 24.04.2014): Papal saints: Once a given, now extremely rare","oeffentlich":true,"url":"https://www.pewresearch.org/short-reads/2014/04/24/papal-saints-once-a-given-now-extremely-rare/","abruf":"2026-10-12"},{"typ":"url","kurz":"Johannes Paul II. (1983): Apostolische Konstitution Divinus Perfectionis Magister, 25.01.1983 (engl. Fassung, vatican.va)","oeffentlich":true,"url":"https://www.vatican.va/content/john-paul-ii/en/apost_constitutions/documents/hf_jp-ii_apc_25011983_divinus-perfectionis-magister.html","abruf":"2026-10-12"},{"typ":"literatur","kurz":"Bigalke, B., in: Vitanova-Kerber, V.; Zander, H. (Hg.) (2025): Esoteric Catholicism. Berlin: De Gruyter","oeffentlich":false}],"thema":"Geschichte und Wissenschaft","pruefung":{"lauf":"quiz-audit-v3","modell":"claude-sonnet-5-5","datum":"2026-10-13","urteil":"ok","pruefsumme":"473954e7831c174a"}}]`);export{t as n,n as t};